-- =====================================================================
-- 095 — Perfil completo + farmacologia de 30 fármacos (lote 4)
-- ---------------------------------------------------------------------
-- Perfis (drug_profiles, padrão 090) E farmacologia (drug_pharmacology,
-- padrão 088/091/092) dos 30 fármacos seguintes por nº de pares na BD,
-- todos sem perfil e sem farmacologia (confirmado por consulta read-only).
-- Fontes (citadas por linha):
--   • 27 fármacos: secções INDICATIONS AND USAGE, ADVERSE REACTIONS,
--     CONTRAINDICATIONS, WARNINGS AND PRECAUTIONS + secção 12 CLINICAL
--     PHARMACOLOGY dos rótulos aprovados DailyMed (setIDs validados);
--   • cetirizina, cianocobalamina, levocetirizina: rótulos OTC DailyMed
--     (Drug Facts, sem secção 12) + farmacocinética PubMed (citadas);
-- Conteúdo autoral (não copiado), ancorado nos números das fontes.
-- Idempotente: ON CONFLICT (drug_id) DO NOTHING — reaplicar é seguro.
-- Padrão 7.6 (JOIN ON d.slug = v.slug). Aplicar na ordem 079 → 095.
-- =====================================================================

INSERT INTO public.drug_profiles
  (drug_id, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
   indications_pt, indications_en, side_effects_pt, side_effects_en,
   precautions_pt, precautions_en, source_pt, source_en, status)
SELECT d.id, v.overview_public_pt, v.overview_public_en, v.overview_pro_pt, v.overview_pro_en,
       v.indications_pt, v.indications_en, v.side_effects_pt, v.side_effects_en,
       v.precautions_pt, v.precautions_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('morfina',
   'A morfina é um analgésico opióide forte usado no alívio da dor aguda ou crónica grave que não responde a analgésicos mais fracos. Atua no cérebro e na medula espinhal, reduzindo a perceção da dor. É um medicamento sujeito a controlo especial (estupefaciente): pode causar dependência, sonolência, obstipação e, em doses elevadas, depressão respiratória potencialmente fatal. Deve ser usada sob prescrição e vigilância médica, com a menor dose eficaz pelo menor tempo possível.',
   'Morphine is a strong opioid analgesic used to relieve severe acute or chronic pain that does not respond to weaker painkillers. It acts on the brain and spinal cord to reduce the perception of pain. It is a controlled substance (narcotic): it can cause dependence, drowsiness, constipation and, at high doses, potentially fatal respiratory depression. It must be used under medical prescription and supervision, at the lowest effective dose for the shortest possible time.',
   'Agonista opióide mu de referência (padrão-ouro da analgesia forte), indicado na dor aguda e crónica grave que requer opióide quando as alternativas são inadequadas. Efeito analgésico máximo ~60 min após a toma oral; biodisponibilidade oral <40% (elevado metabolismo pré-sistémico, variabilidade interindividual grande). Semivida ~2 h (IV) com efeito de 4-6 h. Risco de dependência, tolerância, síndrome de abstinência, hiperalgesia induzida por opióides e depressão respiratória — reservar para doentes em que alternativas não opióides são inadequadas e vigiar de perto.',
   'Reference mu-opioid receptor agonist (gold standard for strong analgesia), indicated for severe acute and chronic pain requiring an opioid when alternatives are inadequate. Peak analgesic effect ~60 min after oral dosing; oral bioavailability <40% (extensive presystemic metabolism, large inter-individual variability). Half-life ~2 h (IV) with 4-6 h duration of effect. Risk of dependence, tolerance, withdrawal syndrome, opioid-induced hyperalgesia and respiratory depression — reserve for patients in whom non-opioid alternatives are inadequate and monitor closely.',
   E'Dor aguda grave que requer analgésico opióide e para a qual as alternativas são inadequadas.\nDor crónica grave que requer analgésico opióide e para a qual as alternativas são inadequadas.',
   E'Severe acute pain requiring an opioid analgesic and for which alternative treatments are inadequate.\nSevere chronic pain requiring an opioid analgesic and for which alternative treatments are inadequate.',
   E'Obstipação (muito frequente — usar laxante profilático).\nNáuseas e vómitos (sobretudo no início).\nSonolência, sedação, tonturas, confusão.\nDepressão respiratória (dose-dependente — risco major, vigiar).\nPrurido, rubor, sudação.\nRetenção urinária, miose.\nDependência, tolerância e síndrome de abstinência com uso prolongado.\nHipotensão ortostática.\nHiperalgesia induzida por opióides (paradoxal) com uso crónico.',
   E'Constipation (very common — use prophylactic laxatives).\nNausea and vomiting (especially at initiation).\nDrowsiness, sedation, dizziness, confusion.\nRespiratory depression (dose-dependent — major risk, monitor).\nPruritus, flushing, sweating.\nUrinary retention, miosis.\nDependence, tolerance and withdrawal syndrome with prolonged use.\nOrthostatic hypotension.\nOpioid-induced hyperalgesia (paradoxical) with chronic use.',
   E'Não usar em crianças <12 anos (contraindicado); risco de depressão respiratória grave.\nEvitar com benzodiazepinas, álcool e outros depressores do SNC — risco de sedação profunda, coma e morte.\nContraindicado em depressão respiratória significativa, asma aguda/grave não monitorizada e obstrução gastrointestinal.\nInterações com inibidores/indutores do CYP3A4 e 2D6 podem alterar os níveis e o efeito.\nNão suspender bruscamente — retirar gradualmente para evitar abstinência.\nVigiar sinais de uso indevido, desvio e sobredosagem; considerar naloxona em doentes de risco.\nUsar com precaução na insuficiência renal/hepática, idosos e debilitados.',
   E'Do not use in children <12 years (contraindicated); risk of severe respiratory depression.\nAvoid with benzodiazepines, alcohol and other CNS depressants — risk of profound sedation, coma and death.\nContraindicated in significant respiratory depression, acute/severe asthma in an unmonitored setting and GI obstruction.\nInteractions with CYP3A4/2D6 inhibitors and inducers may alter levels and effect.\nDo not stop abruptly — taper gradually to avoid withdrawal.\nMonitor for signs of misuse, diversion and overdose; consider naloxone in at-risk patients.\nUse with caution in renal/hepatic impairment, the elderly and the debilitated.',
   'DailyMed/FDA — Morphine Sulfate Tablets (SpecGx), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8b69f67f-30b3-4982-953e-5a4b87ec6ac6',
   'DailyMed/FDA — Morphine Sulfate Tablets label (SpecGx), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8b69f67f-30b3-4982-953e-5a4b87ec6ac6'),

  ('moxifloxacina',
   'A moxifloxacina é um antibiótico da classe das fluoroquinolonas, usado no tratamento de infeções respiratórias (pneumonia adquirida na comunidade, exacerbações de bronquite crónica, sinusite) em adultos. Atua impedindo a multiplicação das bactérias. Deve ser usado apenas com prescrição médica; pode causar efeitos adversos graves e raros como rotura de tendões, lesão nervosa e alterações do ritmo cardíaco (QT longo).',
   'Moxifloxacin is an antibiotic of the fluoroquinolone class, used to treat respiratory infections (community-acquired pneumonia, exacerbations of chronic bronchitis, sinusitis) in adults. It works by preventing bacteria from multiplying. It should only be used on medical prescription; it can cause serious and rare adverse effects such as tendon rupture, nerve damage and heart rhythm changes (QT prolongation).',
   'Fluoroquinolona de largo espetro (bactericida, inibição da topoisomerase II/ADN girase e IV), ativa contra Gram-positivos (S. pneumoniae incluindo MDRSP, S. aureus), Gram-negativos (H. influenzae, M. catarrhalis, K. pneumoniae, E. coli) e atípicos (Mycoplasma, Chlamydophila, Legionella). Biodisponibilidade oral ~90%; semivida 12±1,3 h (estado estacionário ao 3.º dia com 400 mg/dia). Risco de QT prolongado, tendinopatia/rotura tendinosa, neuropatia periférica e efeitos no SNC — reservar para infeções em que os benefícios superam os riscos.',
   'Broad-spectrum fluoroquinolone (bactericidal, inhibition of topoisomerase II/DNA gyrase and IV), active against Gram-positives (S. pneumoniae including MDRSP, S. aureus), Gram-negatives (H. influenzae, M. catarrhalis, K. pneumoniae, E. coli) and atypicals (Mycoplasma, Chlamydophila, Legionella). Oral bioavailability ~90%; half-life 12±1.3 h (steady state by Day 3 with 400 mg/day). Risk of QT prolongation, tendinopathy/tendon rupture, peripheral neuropathy and CNS effects — reserve for infections where the benefits outweigh the risks.',
   E'Pneumonia adquirida na comunidade em adultos (incluindo por S. pneumoniae multirresistente).\nExacerbação aguda de bronquite crónica.\nSinusite bacteriana aguda.\nInfeções da pele e estruturas cutâneas não complicadas (em adultos).\nInfeções intra-abdominais complicadas (em associação).',
   E'Community-acquired pneumonia in adults (including multidrug-resistant S. pneumoniae).\nAcute exacerbation of chronic bronchitis.\nAcute bacterial sinusitis.\nUncomplicated skin and skin structure infections (in adults).\nComplicated intra-abdominal infections (in combination).',
   E'Náuseas e diarreia (as mais frequentes).\nCefaleia, tonturas.\nProlongamento do intervalo QT (dose-dependente; risco de arritmias ventriculares, sobretudo com fatores de risco).\nTendinite e rotura de tendão (risco aumentado em idosos >60 anos, com corticoides, transplante renal/coração/pulmão).\nNeuropatia periférica (potencialmente irreversível — suspender aos primeiros sinais).\nEfeitos no SNC: insónia, ansiedade, confusão, convulsões.\nReações de fotossensibilidade.\nDisbiose intestinal e diarreia associada a Clostridioides difficile.',
   E'Nausea and diarrhoea (the most frequent).\nHeadache, dizziness.\nQT interval prolongation (dose-dependent; risk of ventricular arrhythmias, especially with risk factors).\nTendinitis and tendon rupture (increased risk in the elderly >60 years, with corticosteroids, kidney/heart/lung transplant).\nPeripheral neuropathy (potentially irreversible — discontinue at first signs).\nCNS effects: insomnia, anxiety, confusion, seizures.\nPhotosensitivity reactions.\nGut dysbiosis and Clostridioides difficile-associated diarrhoea.',
   E'Evitar em doentes com QT prolongado, hipocaliemia não corrigida, bradicardia significativa, insuficiência cardíaca e com fármacos que prolongam o QT.\nNão usar em caso de hipersensibilidade a fluoroquinolonas ou antecedentes de reações graves (tendinopatia, neuropatia, reações cutâneas graves).\nSuspender imediatamente aos primeiros sinais de tendinite, neuropatia periférica, reação cutânea grave ou efeito no SNC.\nTomar pelo menos 4 h antes ou 8 h depois de antiácidos, ferro, zinco, sucralfato e lantião (quelatos reduzem a absorção).\nPrecaução na miastenia gravis (pode exacerbar), epilepsia e idosos.\nEvitar exposição solar prolongada.\nNão usar na gravidez nem na amamentação (salvo indicação formal).',
   E'Avoid in patients with QT prolongation, uncorrected hypokalaemia, significant bradycardia, heart failure and with QT-prolonging drugs.\nDo not use in hypersensitivity to fluoroquinolones or a history of serious reactions (tendinopathy, neuropathy, severe skin reactions).\nDiscontinue immediately at the first signs of tendinitis, peripheral neuropathy, severe skin reaction or CNS effects.\nTake at least 4 h before or 8 h after antacids, iron, zinc, sucralfate and didanosine (chelation reduces absorption).\nCaution in myasthenia gravis (may exacerbate), epilepsy and the elderly.\nAvoid prolonged sun exposure.\nDo not use in pregnancy or breastfeeding (unless formally indicated).',
   'DailyMed/FDA — Moxifloxacin Hydrochloride Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1ed191f5-7df5-488c-bb72-91ac0b618d9a',
   'DailyMed/FDA — Moxifloxacin Hydrochloride Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1ed191f5-7df5-488c-bb72-91ac0b618d9a'),

  ('nevirapina',
   'A nevirapina é um medicamento antirretroviral usado no tratamento da infeção por VIH-1, sempre em associação com outros antirretrovirais (nunca em monoterapia). Bloqueia a multiplicação do vírus ao inibir a transcriptase reversa. Pode causar erupções cutâneas graves e lesão hepática, sobretudo nas primeiras semanas — exige vigilância clínica e analítica apertada no início do tratamento.',
   'Nevirapine is an antiretroviral medicine used to treat HIV-1 infection, always in combination with other antiretrovirals (never as monotherapy). It blocks viral replication by inhibiting reverse transcriptase. It can cause severe skin rashes and liver damage, especially in the first weeks — requiring close clinical and laboratory monitoring at treatment initiation.',
   'Inibidor não nucleósido da transcriptase reversa (NNRTI) do VIH-1: liga-se diretamente à transcriptase reversa e bloqueia as atividades polimerase dependentes de ARN e ADN, sem competir com o substrato. Biodisponibilidade oral >90% (93±9%); semivida ~45 h após dose única, que diminui para ~25-30 h com a toma múltipla (autoindução do CYP3A/2B6, clearance oral aumenta 1,5-2x em 2-4 semanas). Indutor potente do CYP3A4 e 2B6 — inúmeras interações; risco de hepatotoxicidade grave e síndrome de Stevens-Johnson/necrólise epidérmica tóxica (período de indução de 14 dias).',
   'Non-nucleoside reverse transcriptase inhibitor (NNRTI) of HIV-1: binds directly to reverse transcriptase and blocks the RNA- and DNA-dependent polymerase activities, without competing with the substrate. Oral bioavailability >90% (93±9%); half-life ~45 h after a single dose, decreasing to ~25-30 h with multiple dosing (CYP3A/2B6 autoinduction, oral clearance increases 1.5-2-fold over 2-4 weeks). Potent CYP3A4/2B6 inducer — numerous interactions; risk of severe hepatotoxicity and Stevens-Johnson syndrome/toxic epidermal necrolysis (14-day lead-in period).',
   E'Tratamento da infeção por VIH-1 em adultos e crianças ≥15 dias, em associação com outros antirretrovirais.',
   E'Treatment of HIV-1 infection in adults and paediatric patients ≥15 days of age, in combination with other antiretrovirals.',
   E'Erupção cutânea (muito frequente no início; pode ser grave — SJS/NET, potencialmente fatais).\nHepatotoxicidade: elevação das transaminases, hepatite, falência hepática (risco major nas primeiras 18 semanas, sobretudo em mulheres com CD4>250 e homens com CD4>400).\nFebre, fadiga, mialgias, adenopatias (síndrome de hipersensibilidade).\nNáuseas, diarreia.\nCefaleia, sonolência.\nSíndrome de reconstituição imune.',
   E'Skin rash (very common at initiation; may be severe — SJS/TEN, potentially fatal).\nHepatotoxicity: elevated transaminases, hepatitis, hepatic failure (major risk in the first 18 weeks, especially in women with CD4>250 and men with CD4>400).\nFever, fatigue, myalgia, lymphadenopathy (hypersensitivity syndrome).\nNausea, diarrhoea.\nHeadache, somnolence.\nImmune reconstitution syndrome.',
   E'Contraindicado na insuficiência hepática moderada a grave (Child-Pugh B/C) e em doentes com antecedentes de SJS/NET ou reação de hipersensibilidade à nevirapina.\nPeríodo de indução obrigatório: 200 mg/dia durante 14 dias antes de subir para 200 mg 2x/dia (reduz o risco de erupção grave).\nVigiar função hepática e erupção cutânea nas primeiras 18 semanas; suspender se erupção grave (bolhas, ulceração, febre, edema facial).\nNão iniciar em mulheres com CD4>250 células/mm³ nem homens com CD4>400 (risco hepático), salvo benefício claro.\nIndutor potente do CYP3A4/2B6: rever todas as medicações concomitantes (contracetivos hormonais, metadona, cetoconazol, rifampicina, inibidores da protease, etc.).\nUsar com precaução na insuficiência renal em diálise (dose adicional após cada sessão).',
   E'Contraindicated in moderate to severe hepatic impairment (Child-Pugh B/C) and in patients with a history of SJS/TEN or hypersensitivity reaction to nevirapine.\nMandatory lead-in period: 200 mg/day for 14 days before increasing to 200 mg twice daily (reduces the risk of severe rash).\nMonitor liver function and skin rash in the first 18 weeks; discontinue if severe rash (blisters, ulceration, fever, facial oedema).\nDo not initiate in women with CD4>250 cells/mm³ or men with CD4>400 (liver risk), unless clear benefit.\nPotent CYP3A4/2B6 inducer: review all concomitant medications (hormonal contraceptives, methadone, ketoconazole, rifampin, protease inhibitors, etc.).\nUse with caution in renal impairment on dialysis (additional dose after each session).',
   'DailyMed/FDA — Nevirapine Tablets (Mylan), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c6e93829-7024-48f6-8023-da6ff27dfc0a',
   'DailyMed/FDA — Nevirapine Tablets label (Mylan), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c6e93829-7024-48f6-8023-da6ff27dfc0a'),

  ('orlistat',
   'O orlistato é um medicamento para emagrecer que atua no intestino, impedindo a absorção de parte da gordura dos alimentos (cerca de 30%). É usado em adultos com obesidade (IMC ≥30) ou excesso de peso com fatores de risco (IMC ≥27), sempre associado a uma dieta hipocalórica. Como a gordura não absorvida é eliminada nas fezes, pode causar efeitos gastrointestinais (urgência fecal, flatulência, fezes gordurosas), sobretudo com refeições ricas em gordura.',
   'Orlistat is a weight-loss medicine that works in the gut, preventing the absorption of part of the fat from food (about 30%). It is used in adults with obesity (BMI ≥30) or overweight with risk factors (BMI ≥27), always combined with a reduced-calorie diet. Because unabsorbed fat is eliminated in the stools, it can cause gastrointestinal effects (faecal urgency, flatulence, oily stools), especially with high-fat meals.',
   'Inibidor das lipases gástrica e pancreática (derivado da lipstatina): forma uma ligação covalente com o sítio ativo da lipase, inativando-a e reduzindo a hidrólise dos triglicéridos da dieta — cerca de 30% da gordura ingerida não é absorvida e é eliminada nas fezes. A exposição sistémica é mínima (concentrações plasmáticas <10 ng/mL; absorção <2%); o M1, metabolito com fraca atividade, tem semivida ~3 h. O efeito depende da toma com as refeições.',
   'Inhibitor of gastric and pancreatic lipases (lipstatin derivative): forms a covalent bond with the active site of lipase, inactivating it and reducing hydrolysis of dietary triglycerides — about 30% of ingested fat is not absorbed and is eliminated in the faeces. Systemic exposure is minimal (plasma concentrations <10 ng/mL; absorption <2%); M1, the weakly active metabolite, has a half-life of ~3 h. The effect depends on taking it with meals.',
   E'Gestão da obesidade (perda e manutenção de peso) em adultos com IMC ≥30 kg/m² ou ≥27 kg/m² na presença de fatores de risco (hipertensão, diabetes, dislipidemia), em associação com dieta hipocalórica.\nRedução do risco de recuperação de peso após perda ponderal prévia.',
   E'Management of obesity (weight loss and weight maintenance) in adults with BMI ≥30 kg/m² or ≥27 kg/m² in the presence of risk factors (hypertension, diabetes, dyslipidaemia), in combination with a reduced-calorie diet.\nReduction of the risk of weight regain after prior weight loss.',
   E'Efeitos gastrointestinais (mecanismo de ação): esteatorreia/fezes gordurosas, urgência fecal, flatulência com descarga, distensão abdominal, incontinência fecal — mais frequentes com dietas ricas em gordura.\nDéfice de vitaminas lipossolúveis (A, D, E, K) — suplementar e monitorizar com uso prolongado.\nCefaleia, dor abdominal.\nReações de hipersensibilidade (raras).\nCasos raros de lesão hepática grave (pós-comercialização) e pancreatite.',
   E'Gastrointestinal effects (mechanism of action): steatorrhoea/oily stools, faecal urgency, flatulence with discharge, abdominal distension, faecal incontinence — more frequent with high-fat diets.\nDeficiency of fat-soluble vitamins (A, D, E, K) — supplement and monitor with prolonged use.\nHeadache, abdominal pain.\nHypersensitivity reactions (rare).\nRare cases of severe liver injury (postmarketing) and pancreatitis.',
   E'Contraindicado em síndrome de má absorção crónica, colestase e hipersensibilidade ao orlistato.\nTomar com as refeições principais ou até 1 h depois; se uma refeição não tiver gordura, pode omitir a dose.\nSeguir uma dieta com ≤30% de calorias de gordura para reduzir os efeitos gastrointestinais.\nSuplementar com vitaminas lipossolúveis (pelo menos 2 h após o orlistato) se o tratamento for prolongado.\nVigiar interação com varfarina (alteração do INR) e com ciclosporina/levotiroxina (absorção reduzida — separar a toma).\nInterromper se ocorrerem sinais de lesão hepática (icterícia, urina escura, prurido).\nNão é recomendado na gravidez e amamentação.',
   E'Contraindicated in chronic malabsorption syndrome, cholestasis and hypersensitivity to orlistat.\nTake with main meals or up to 1 hour after; if a meal contains no fat, the dose may be omitted.\nFollow a diet with ≤30% of calories from fat to reduce GI effects.\nSupplement with fat-soluble vitamins (at least 2 h after orlistat) if treatment is prolonged.\nMonitor the interaction with warfarin (INR changes) and with ciclosporin/levothyroxine (reduced absorption — separate dosing).\nDiscontinue if signs of liver injury occur (jaundice, dark urine, pruritus).\nNot recommended in pregnancy and breastfeeding.',
   'DailyMed/FDA — Xenical (orlistat) Capsules, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6240792b-9224-2d10-e053-2a91aa0a2c3e',
   'DailyMed/FDA — Xenical (orlistat) Capsules label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6240792b-9224-2d10-e053-2a91aa0a2c3e'),

  ('sulfassalazina',
   'A sulfassalazina é um medicamento anti-inflamatório usado no tratamento da colite ulcerosa (ativa e manutenção da remissão) e da artrite reumatoide. É composta por ácido 5-aminossalicílico (5-ASA) ligado à sulfapiridina; no cólon, as bactérias intestinais separam-nos e o 5-ASA exerce o efeito anti-inflamatório local. Deve ser usada sob orientação médica, com vigilância analítica regular.',
   'Sulfasalazine is an anti-inflammatory medicine used to treat ulcerative colitis (active disease and maintenance of remission) and rheumatoid arthritis. It is composed of 5-aminosalicylic acid (5-ASA) linked to sulfapyridine; in the colon, gut bacteria split them and 5-ASA exerts the local anti-inflammatory effect. It should be used under medical supervision, with regular laboratory monitoring.',
   'Pró-fármaco: no cólon, a azoredutase bacteriana cliva a sulfassalazina em sulfapiridina (SP) e 5-aminossalicilato (5-ASA) — a maior parte da atividade terapêutica na colite reside no 5-ASA (ação anti-inflamatória local); a SP é absorvida (bio ~60%) e metabolizada, sendo responsável por grande parte dos efeitos adversos. Biodisponibilidade da sulfassalazina intacta <15%; semivida IV ~7 h; SP ~10 h (14,8 h nos acetiladores lentos). Menos de 15% da dose intacta é absorvida no intestino delgado.',
   'Prodrug: in the colon, bacterial azoreductase cleaves sulfasalazine into sulfapyridine (SP) and 5-aminosalicylate (5-ASA) — most of the therapeutic activity in colitis resides in 5-ASA (local anti-inflammatory action); SP is absorbed (bio ~60%) and metabolised, being responsible for much of the adverse effects. Bioavailability of intact sulfasalazine <15%; IV half-life ~7 h; SP ~10 h (14.8 h in slow acetylators). Less than 15% of the intact dose is absorbed in the small intestine.',
   E'Colite ulcerosa ligeira a moderada (tratamento da doença ativa e prolongamento da remissão).\nArtrite reumatoide (em doentes que não respondem adequadamente aos AINE).\nDoença de Crohn (em alguns países, uso off-label/adjuvante).',
   E'Mild to moderate ulcerative colitis (treatment of active disease and prolongation of remission).\nRheumatoid arthritis (in patients with an inadequate response to NSAIDs).\nCrohn disease (in some countries, off-label/adjuvant use).',
   E'Anorexia, cefaleia, náuseas, vómitos, desconforto gástrico (cerca de 1/3 dos doentes).\nOligospermia reversível (nos homens).\nErupção cutânea, prurido, urticária, febre.\nAnemia hemolítica, anemia de Heinz, cianose (frequência ≤1/30).\nElevação das transaminases; hepatite (rara).\nReações de fotossensibilidade.\nAgranulocitose, anemia aplástica (raras, mas graves).\nReações cutâneas graves (SJS/NET) e síndrome de DRESS (raras).',
   E'Anorexia, headache, nausea, vomiting, gastric distress (about one-third of patients).\nReversible oligospermia (in men).\nSkin rash, pruritus, urticaria, fever.\nHaemolytic anaemia, Heinz body anaemia, cyanosis (frequency ≤1 in 30).\nElevated transaminases; hepatitis (rare).\nPhotosensitivity reactions.\nAgranulocytosis, aplastic anaemia (rare but serious).\nSevere skin reactions (SJS/TEN) and DRESS syndrome (rare).',
   E'Contraindicado em hipersensibilidade a sulfonamidas/salicilatos, porfíria, obstrução urinária ou intestinal.\nVigiar hemograma, função hepática e renal no início e periodicamente (risco de agranulocitose e hepatotoxicidade).\nSuspender imediatamente se ocorrer erupção grave, febre, odinofagia, úlceras orais ou icterícia.\nEvitar exposição solar (fotossensibilidade).\nGarantir ingestão hídrica adequada (risco de cristalúria).\nUsar com precaução em doentes com deficiência de G6PD (risco de hemólise), asma e alergia a sulfonamidas.\nPode reduzir a absorção de ácido fólico e digoxina; interage com varfarina.',
   E'Contraindicated in hypersensitivity to sulfonamides/salicylates, porphyria, urinary or intestinal obstruction.\nMonitor blood count, liver and renal function at initiation and periodically (risk of agranulocytosis and hepatotoxicity).\nDiscontinue immediately if severe rash, fever, sore throat, oral ulcers or jaundice occur.\nAvoid sun exposure (photosensitivity).\nEnsure adequate fluid intake (risk of crystalluria).\nUse with caution in G6PD deficiency (risk of haemolysis), asthma and sulfonamide allergy.\nMay reduce absorption of folic acid and digoxin; interacts with warfarin.',
   'DailyMed/FDA — Azulfidine (sulfasalazine) Tablets (Pfizer), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ddbe69f3-bd55-45f3-a64f-f60226c744c4',
   'DailyMed/FDA — Azulfidine (sulfasalazine) Tablets label (Pfizer), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ddbe69f3-bd55-45f3-a64f-f60226c744c4'),

  ('tobramicina',
   'A tobramicina é um antibiótico da classe dos aminoglicosídeos, usado por via injetável no tratamento de infeções bacterianas graves, sobretudo por Pseudomonas aeruginosa (infeções respiratórias, septicemia, infeções urinárias complicadas, meningite, intra-abdominais). Atua impedindo a síntese proteica das bactérias. É um fármaco de uso hospitalar: pode causar lesão renal e do ouvido (ototoxicidade), pelo que exige monitorização dos níveis e da função renal.',
   'Tobramycin is an antibiotic of the aminoglycoside class, given by injection for the treatment of serious bacterial infections, especially due to Pseudomonas aeruginosa (respiratory infections, septicaemia, complicated urinary tract infections, meningitis, intra-abdominal infections). It works by preventing bacterial protein synthesis. It is a hospital-use drug: it can cause kidney damage and ear damage (ototoxicity), so it requires monitoring of levels and renal function.',
   'Aminoglicosídeo bactericida derivado de Streptomyces tenebrarius: liga-se à subunidade ribossómica bacteriana e inibe a síntese proteica. Ativo sobretudo contra Gram-negativos (P. aeruginosa, E. coli, Klebsiella, Enterobacter, Serratia, Proteus, Providencia, Citrobacter) e estafilococos; baixa atividade contra estreptococos e enterococos. Semivida sérica ~2 h com função renal normal; eliminação quase exclusiva por filtração glomerular (até 93% da dose na urina em 24 h); picos de 4-6 mcg/mL a 1 mg/kg IM.',
   'Bactericidal aminoglycoside derived from Streptomyces tenebrarius: binds to the bacterial ribosomal subunit and inhibits protein synthesis. Active mainly against Gram-negatives (P. aeruginosa, E. coli, Klebsiella, Enterobacter, Serratia, Proteus, Providencia, Citrobacter) and staphylococci; low activity against streptococci and enterococci. Serum half-life ~2 h with normal renal function; elimination almost exclusively by glomerular filtration (up to 93% of the dose in urine within 24 h); peaks of 4-6 mcg/mL at 1 mg/kg IM.',
   E'Septicemia no recém-nascido, criança e adulto (P. aeruginosa, E. coli, Klebsiella).\nInfeções do trato respiratório inferior (incluindo pneumonia nosocomial por P. aeruginosa).\nInfeções graves do SNC (meningite).\nInfeções intra-abdominais (incluindo peritonite).\nInfeções da pele, ossos e estruturas cutâneas.\nInfeções urinárias complicadas e recorrentes.',
   E'Septicaemia in the neonate, child and adult (P. aeruginosa, E. coli, Klebsiella).\nLower respiratory tract infections (including nosocomial pneumonia due to P. aeruginosa).\nSerious CNS infections (meningitis).\nIntra-abdominal infections (including peritonitis).\nSkin, bone and skin-structure infections.\nComplicated and recurrent urinary tract infections.',
   E'Ototoxicidade (auditiva e vestibular) — perda auditiva geralmente irreversível, inicialmente nas altas frequências; risco com doses altas, terapêutica prolongada e função renal diminuída.\nNefrotoxicidade — subida da creatinina, oligúria, cilindrúria; geralmente reversível com a suspensão.\nBloqueio neuromuscular (raro) — apneia, paralisia muscular.\nHipersensibilidade (erupção, febre, eosinofilia).\nHipocaliemia, hipomagnesemia, anemia.',
   E'Ototoxicity (auditory and vestibular) — generally irreversible hearing loss, initially at high frequencies; risk with high doses, prolonged therapy and impaired renal function.\nNephrotoxicity — rising creatinine, oliguria, cylindruria; usually reversible on discontinuation.\nNeuromuscular blockade (rare) — apnoea, muscle paralysis.\nHypersensitivity (rash, fever, eosinophilia).\nHypokalaemia, hypomagnesaemia, anaemia.',
   E'Contraindicado em hipersensibilidade a aminoglicosídeos (reactividade cruzada).\nEvitar/ajustar na insuficiência renal (semivida prolongada — monitorizar níveis e dose).\nVigiar função renal, audiometria e níveis séricos (pico e vale) durante a terapêutica.\nEvitar associação com outros fármacos ototóxicos/nefrotóxicos (furosemida, vancomicina, anfotericina B, cisplatina, outros aminoglicosídeos).\nUsar com precaução em doentes com distúrbios neuromusculares (miastenia, Parkinson) — risco de bloqueio neuromuscular.\nRisco de ototoxicidade aumentado na variante mitocondrial m.1555A>G (MT-RNR1) — considerar alternativa.\nNão usar em grávidas salvo necessidade vital (atravessa a placenta).',
   E'Contraindicated in hypersensitivity to aminoglycosides (cross-reactivity).\nAvoid/adjust in renal impairment (prolonged half-life — monitor levels and dose).\nMonitor renal function, audiometry and serum levels (peak and trough) during therapy.\nAvoid combination with other ototoxic/nephrotoxic drugs (furosemide, vancomycin, amphotericin B, cisplatin, other aminoglycosides).\nUse with caution in patients with neuromuscular disorders (myasthenia, Parkinson) — risk of neuromuscular blockade.\nIncreased ototoxicity risk in the mitochondrial variant m.1555A>G (MT-RNR1) — consider alternatives.\nDo not use in pregnancy unless vitally necessary (crosses the placenta).',
   'DailyMed/FDA — Tobramycin for Injection (Fosun Pharma), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c4751a4f-c9c1-60c5-e053-2995a90aeba9',
   'DailyMed/FDA — Tobramycin for Injection label (Fosun Pharma), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c4751a4f-c9c1-60c5-e053-2995a90aeba9'),

  ('acetazolamida',
   'A acetazolamida é um medicamento que reduz a produção de líquido no olho (usado no glaucoma), atua como diurético e é também usado na prevenção do mal das montanhas. Funciona ao inibir uma enzima chamada anidrase carbónica. Pode causar formigueiro nas mãos e pés, alterações do paladar, fadiga e, com uso prolongado, risco de cálculos renais.',
   'Acetazolamide is a medicine that reduces fluid production in the eye (used in glaucoma), acts as a diuretic and is also used to prevent altitude (mountain) sickness. It works by inhibiting an enzyme called carbonic anhydrase. It can cause tingling in the hands and feet, taste changes, fatigue and, with prolonged use, a risk of kidney stones.',
   'Inibidor da anidrase carbónica (sulfonamida não bacteriostática): bloqueia a reação reversível de hidratação do CO2, reduzindo a secreção de humor aquoso no olho (diminui a pressão intraocular), promovendo diurese com perda renal de bicarbonato, sódio, água e potássio (alcalinização da urina) e reduzindo a descarga neuronal paroxística em certas epilepsias. Eficaz na profilaxia do mal agudo das montanhas (250 mg 8-12/8 h).',
   'Carbonic anhydrase inhibitor (non-bacteriostatic sulfonamide): blocks the reversible hydration of CO2, reducing aqueous humour secretion in the eye (lowers intraocular pressure), promoting diuresis with renal loss of bicarbonate, sodium, water and potassium (urinary alkalinisation) and reducing paroxysmal neuronal discharge in certain epilepsies. Effective in the prophylaxis of acute mountain sickness (250 mg every 8-12 h).',
   E'Glaucoma crónico simples (open-angle), glaucoma secundário e pré-operatório no glaucoma agudo de ângulo fechado.\nEdema associado a insuficiência cardíaca congestiva e edema induzido por fármacos.\nEpilepsias centrencefálicas (petit mal, crises não localizadas).\nPrevenção ou melhoria dos sintomas do mal agudo das montanhas.',
   E'Chronic simple (open-angle) glaucoma, secondary glaucoma and preoperatively in acute angle-closure glaucoma.\nOedema due to congestive heart failure and drug-induced oedema.\nCentrencephalic epilepsies (petit mal, unlocalised seizures).\nPrevention or amelioration of acute mountain sickness symptoms.',
   E'Parestesias (formigueiro) nas extremidades e face — muito frequente.\nAlterações do paladar (sabor metálico), anorexia, náuseas, diarreia.\nFadiga, sonolência, cefaleia, confusão, depressão.\nAcidose metabólica e desequilíbrio eletrolítico (hipocaliemia, hiponatremia) — com uso prolongado.\nLitíase renal (cálculos de fosfato de cálcio com uso crónico).\nDiscrasias sanguíneas (anemia aplástica, agranulocitose, leucopenia, trombocitopenia) — raras.\nReações cutâneas alérgicas (incluindo SJS) — raras.',
   E'Paraesthesia (tingling) in the extremities and face — very common.\nTaste alterations (metallic taste), anorexia, nausea, diarrhoea.\nFatigue, drowsiness, headache, confusion, depression.\nMetabolic acidosis and electrolyte imbalance (hypokalaemia, hyponatraemia) — with prolonged use.\nRenal lithiasis (calcium phosphate stones with chronic use).\nBlood dyscrasias (aplastic anaemia, agranulocytosis, leucopenia, thrombocytopenia) — rare.\nAllergic skin reactions (including SJS) — rare.',
   E'Contraindicado em hipersensibilidade a sulfonamidas (reacção cruzada), acidose metabólica, hipocaliemia/hiponatremia, insuficiência hepática ou renal grave, doença de Addison e cirrose.\nEvitar doses elevadas prolongadas (risco de acidose e litíase) — aumentar a ingestão de líquidos.\nVigiar eletrólitos, função renal e hemograma com uso crónico.\nPode potenciar a toxicidade do lítio e dos salicilatos (acidose); reduz a excreção de anfetaminas.\nUsar com precaução na diabetes (pode alterar a glicemia), DPOC e doentes com risco de insuficiência respiratória (acidose).\nNa gravidez, usar apenas se claramente necessário (teratogenicidade em animais).',
   E'Contraindicated in hypersensitivity to sulfonamides (cross-reaction), metabolic acidosis, hypokalaemia/hyponatraemia, severe hepatic or renal impairment, Addison disease and cirrhosis.\nAvoid prolonged high doses (risk of acidosis and lithiasis) — increase fluid intake.\nMonitor electrolytes, renal function and blood count with chronic use.\nMay potentiate lithium and salicylate toxicity (acidosis); reduces amphetamine excretion.\nUse with caution in diabetes (may alter glycaemia), COPD and patients at risk of respiratory failure (acidosis).\nIn pregnancy, use only if clearly needed (teratogenic in animals).',
   'DailyMed/FDA — Acetazolamide Tablets (Strides), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4813b9dd-5f58-44bb-ad64-cdb331828080',
   'DailyMed/FDA — Acetazolamide Tablets label (Strides), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4813b9dd-5f58-44bb-ad64-cdb331828080'),

  ('acido_tranexamico',
   'O ácido tranexâmico é um medicamento antifibrinolítico usado para reduzir hemorragias: impede a dissolução dos coágulos, ajudando a parar sangramentos. É usado no tratamento da hemorragia menstrual intensa (menorragia), em hemorragias pós-operatórias ou traumáticas, e em doentes com risco hemorrágico. Deve ser usado com precaução em doentes com antecedentes de trombose.',
   'Tranexamic acid is an antifibrinolytic medicine used to reduce bleeding: it prevents the breakdown of clots, helping to stop bleeding. It is used to treat heavy menstrual bleeding (menorrhagia), postoperative or traumatic bleeding, and in patients at bleeding risk. It should be used with caution in patients with a history of thrombosis.',
   'Antifibrinolítico (análogo sintético da lisina): liga-se reversivelmente aos sítios de ligação do plasminogénio, bloqueando a interação com a fibrina e impedindo a ativação do plasminogénio em plasmina — estabiliza o coágulo e reduz a fibrinólise. Biodisponibilidade oral ~45% (Cmax ~3 h); semivida terminal ~11 h; excreção renal predominante (95% inalterado na urina).',
   'Antifibrinolytic (synthetic lysine analogue): binds reversibly to plasminogen binding sites, blocking the interaction with fibrin and preventing the activation of plasminogen to plasmin — stabilises the clot and reduces fibrinolysis. Oral bioavailability ~45% (Cmax ~3 h); terminal half-life ~11 h; predominantly renal excretion (95% unchanged in urine).',
   E'Tratamento da hemorragia menstrual intensa (menorragia) em mulheres em idade reprodutiva.\nHemorragias por hiperfibrinólise (cirurgia, trauma, hemorragia digestiva, epistaxe).\nProfilaxia de hemorragia em doentes com risco (ex.: cirurgia cardíaca, hemofilia, angioedema hereditário).\nHemorragia pós-parto (uso off-label em muitos países).',
   E'Treatment of heavy menstrual bleeding (menorrhagia) in women of reproductive age.\nBleeding due to hyperfibrinolysis (surgery, trauma, GI bleeding, epistaxis).\nProphylaxis of bleeding in at-risk patients (e.g., cardiac surgery, haemophilia, hereditary angioedema).\nPostpartum haemorrhage (off-label use in many countries).',
   E'Náuseas, vómitos, diarreia.\nCefaleia, tonturas.\nAlterações visuais (raras) — suspender se ocorrerem.\nRisco tromboembólico (trombose venosa, embolia pulmonar) — mais relevante em doentes com fatores de risco.\nReações de hipersensibilidade (raras).\nConvulsões (com doses muito elevadas/IV rápida).',
   E'Nausea, vomiting, diarrhoea.\nHeadache, dizziness.\nVisual disturbances (rare) — discontinue if they occur.\nThromboembolic risk (venous thrombosis, pulmonary embolism) — more relevant in patients with risk factors.\nHypersensitivity reactions (rare).\nSeizures (with very high doses/rapid IV).',
   E'Contraindicado em tromboembolismo ativo ou antecedentes, hipercoagulabilidade, coagulopatia de consumo e hemorragia subaracnoideia.\nAjustar a dose na insuficiência renal (semivida prolongada — risco de acumulação).\nRisco de trombose aumentado em doentes com anticoncecionais orais combinados, neoplasia, obesidade — avaliar risco/benefício.\nVigiar alterações visuais (suspender imediatamente).\nEvitar associação com outros anticoagulantes/antiagregantes salvo indicação formal.\nNão usar em mulheres grávidas com risco tromboembólico aumentado; uso na gravidez só se benefício > risco.',
   E'Contraindicated in active thrombosis or history thereof, hypercoagulability, consumptive coagulopathy and subarachnoid haemorrhage.\nAdjust the dose in renal impairment (prolonged half-life — risk of accumulation).\nIncreased thrombosis risk in patients on combined oral contraceptives, malignancy, obesity — assess risk/benefit.\nMonitor visual changes (discontinue immediately).\nAvoid combination with other anticoagulants/antiplatelets unless formally indicated.\nDo not use in pregnant women at increased thromboembolic risk; use in pregnancy only if benefit > risk.',
   'DailyMed/FDA — Tranexamic Acid Tablets (Northstar Rx), secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4877eacd-fda7-4708-93a5-81052c1d2e14',
   'DailyMed/FDA — Tranexamic Acid Tablets label (Northstar Rx), section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4877eacd-fda7-4708-93a5-81052c1d2e14'),

  ('amoxicilina',
   'A amoxicilina é um antibiótico da classe das penicilinas, muito usado no tratamento de infeções bacterianas comuns: otites, amigdalites, sinusites, bronquites, infeções urinárias e dentárias. Atua impedindo a formação da parede das bactérias, matando-as. É geralmente bem tolerada; a reação alérgica (erupção, urticária; raramente anafilaxia) é a preocupação principal.',
   'Amoxicillin is an antibiotic of the penicillin class, widely used to treat common bacterial infections: otitis media, tonsillitis, sinusitis, bronchitis, urinary and dental infections. It works by preventing bacteria from building their cell wall, killing them. It is generally well tolerated; the allergic reaction (rash, urticaria; rarely anaphylaxis) is the main concern.',
   'Penicilina semissintética de largo espetro (aminopenicilina, bactericida): inibe a síntese da parede celular bacteriana ligando-se às proteínas de ligação às penicilinas (PBP). Ativa contra estreptococos, pneumococos, enterococos, Listeria, Haemophilus influenzae, E. coli, Proteus, Salmonella, Helicobacter pylori (em associação). Sensível a beta-lactamases (não ativa contra estafilococos produtores). Estável ao ácido gástrico; absorção oral rápida (picos 1-2 h); ~20% ligação proteica; semivida ~1 h; excreção renal (60-80% inalterado).',
   'Broad-spectrum semisynthetic penicillin (aminopenicillin, bactericidal): inhibits bacterial cell wall synthesis by binding to penicillin-binding proteins (PBPs). Active against streptococci, pneumococci, enterococci, Listeria, Haemophilus influenzae, E. coli, Proteus, Salmonella, Helicobacter pylori (in combination). Susceptible to beta-lactamases (not active against penicillinase-producing staphylococci). Stable to gastric acid; rapid oral absorption (peaks 1-2 h); ~20% protein binding; half-life ~1 h; renal excretion (60-80% unchanged).',
   E'Infeções do trato respiratório superior (otite média aguda, amigdalite/faringite estreptocócica, sinusite bacteriana aguda).\nInfeções do trato respiratório inferior (exacerbação de bronquite crónica, pneumonia adquirida na comunidade).\nInfeções urinárias não complicadas.\nInfeções dentárias e odontogénicas.\nTerapia tripla de erradicação do Helicobacter pylori (com inibidor da bomba de protões e outro antibiótico).\nProfilaxia da endocardite bacteriana (em doentes elegíveis).',
   E'Upper respiratory tract infections (acute otitis media, streptococcal tonsillitis/pharyngitis, acute bacterial sinusitis).\nLower respiratory tract infections (exacerbation of chronic bronchitis, community-acquired pneumonia).\nUncomplicated urinary tract infections.\nDental and odontogenic infections.\nHelicobacter pylori eradication triple therapy (with a proton pump inhibitor and another antibiotic).\nBacterial endocarditis prophylaxis (in eligible patients).',
   E'Diarreia (a mais frequente) e náuseas.\nErupção cutânea maculopapular (frequente; não indica necessariamente alergia).\nUrticária, prurido.\nVaginite/candidíase (disbiose).\nReações de hipersensibilidade: angioedema, anafilaxia (raras, potencialmente fatais).\nDiarreia associada a Clostridioides difficile.\nColite, nefrite intersticial (raras).\nReações cutâneas graves (SJS/NET, DRESS) — raras.',
   E'Diarrhoea (the most frequent) and nausea.\nMaculopapular skin rash (common; does not necessarily indicate allergy).\nUrticaria, pruritus.\nVaginitis/candidiasis (dysbiosis).\nHypersensitivity reactions: angioedema, anaphylaxis (rare, potentially fatal).\nClostridioides difficile-associated diarrhoea.\nColitis, interstitial nephritis (rare).\nSevere skin reactions (SJS/TEN, DRESS) — rare.',
   E'Contraindicado em hipersensibilidade a penicilinas (reacção cruzada com cefalosporinas em <10%).\nUsar apenas em infeções provadas ou fortemente suspeitas de etiologia bacteriana (evitar resistências).\nNa mononucleose infeciosa, a erupção cutânea é frequente — evitar.\nAjustar na insuficiência renal grave (intervalo de doses alargado).\nVigiar diarreia (CDAD pode ocorrer até 2 meses após) e reações cutâneas graves.\nInteração com alopurinol (mais erupções), metotrexato (toxicidade aumentada) e contracetivos orais (redução teórica da eficácia).\nUsar com precaução na gravidez (apenas se necessário — seguro na amamentação).',
   E'Contraindicated in penicillin hypersensitivity (cross-reaction with cephalosporins in <10%).\nUse only for proven or strongly suspected bacterial infections (avoid resistance).\nIn infectious mononucleosis, skin rash is common — avoid.\nAdjust in severe renal impairment (extended dosing interval).\nMonitor diarrhoea (CDAD may occur up to 2 months after) and severe skin reactions.\nInteraction with allopurinol (more rashes), methotrexate (increased toxicity) and oral contraceptives (theoretical reduced efficacy).\nUse with caution in pregnancy (only if needed — safe in breastfeeding).',
   'DailyMed/FDA — Amoxicillin Capsules, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb4149a-0714-4a85-b9e8-2379a8e6a302',
   'DailyMed/FDA — Amoxicillin Capsules label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb4149a-0714-4a85-b9e8-2379a8e6a302'),

  ('amoxicilina-clavulanato',
   'O amoxicilina + ácido clavulânico (co-amoxiclav) é um antibiótico que combina a amoxicilina com um inibidor de beta-lactamases, alargando o espetro a bactérias que inativariam a amoxicilina. É usado em infeções respiratórias, otites, sinusites, mordeduras, infeções dentárias e urinárias complicadas. Deve ser usado com prescrição médica; a diarreia é o efeito adverso mais comum.',
   'Amoxicillin + clavulanic acid (co-amoxiclav) is an antibiotic combining amoxicillin with a beta-lactamase inhibitor, extending the spectrum to bacteria that would inactivate amoxicillin. It is used for respiratory infections, otitis, sinusitis, bites, dental and complicated urinary infections. It should be used on medical prescription; diarrhoea is the most common adverse effect.',
   'Associação de amoxicilina (aminopenicilina bactericida) com ácido clavulânico, inibidor suicida das beta-lactamases (incluindo as de S. aureus, Haemophilus, Klebsiella, E. coli produtores) que protege a amoxicilina da inativação. Picos ~1,5 h após a toma (com refeição ligeira); semivida ~1,3 h (amoxicilina) e ~1 h (clavulanato); excreção renal. Risco de hepatotoxicidade colestática (mais frequente em idosos, homens e uso >14 dias).',
   'Combination of amoxicillin (bactericidal aminopenicillin) with clavulanic acid, a suicide inhibitor of beta-lactamases (including those of S. aureus, Haemophilus, Klebsiella, E. coli producers) that protects amoxicillin from inactivation. Peaks ~1.5 h after dosing (with a light meal); half-life ~1.3 h (amoxicillin) and ~1 h (clavulanate); renal excretion. Risk of cholestatic hepatotoxicity (more frequent in the elderly, men and use >14 days).',
   E'Infeções do trato respiratório superior (otite média recorrente, sinusite bacteriana aguda, amigdalite).\nInfeções do trato respiratório inferior (exacerbação de bronquite crónica, pneumonia).\nMordeduras de animais e infeções da pele/tecidos moles.\nInfeções dentárias e odontogénicas (incluindo abscesso).\nInfeções urinárias complicadas e pielonefrite (conforme guidelines).\nInfeções intra-abdominais (em associação).',
   E'Upper respiratory tract infections (recurrent otitis media, acute bacterial sinusitis, tonsillitis).\nLower respiratory tract infections (exacerbation of chronic bronchitis, pneumonia).\nAnimal bites and skin/soft tissue infections.\nDental and odontogenic infections (including abscess).\nComplicated urinary tract infections and pyelonephritis (per guidelines).\nIntra-abdominal infections (in combination).',
   E'Diarreia/fezes soltas (9% — a mais frequente; mais comum com doses altas e duração longa).\nNáuseas (3%), vómitos (1%).\nErupção cutânea e urticária (3%).\nCandidíase/vaginite (1%).\nHepatotoxicidade (colestase — icterícia; mais frequente em idosos, homens, uso >14 dias).\nReações de hipersensibilidade (incluindo anafilaxia).\nDiarreia associada a Clostridioides difficile.',
   E'Diarrhoea/loose stools (9% — the most frequent; more common with high doses and long duration).\nNausea (3%), vomiting (1%).\nSkin rash and urticaria (3%).\nCandidiasis/vaginitis (1%).\nHepatotoxicity (cholestasis — jaundice; more frequent in the elderly, men, use >14 days).\nHypersensitivity reactions (including anaphylaxis).\nClostridioides difficile-associated diarrhoea.',
   E'Contraindicado em hipersensibilidade a penicilinas e em antecedentes de icterícia/insuficiência hepática associada ao co-amoxiclav.\nLimitar a duração (≤14 dias) — risco de hepatotoxicidade aumenta com a duração.\nVigiar função hepática em doentes com doença hepática e nos idosos.\nAjustar a dose na insuficiência renal (intervalos alargados).\nTomar com alimentos para reduzir o desconforto gastrointestinal (absorção não é afetada).\nPrecaução com varfarina (aumento do INR), metotrexato e alopurinol.\nNa mononucleose infeciosa, evitar (erupção cutânea frequente).',
   E'Contraindicated in penicillin hypersensitivity and in a history of jaundice/hepatic impairment associated with co-amoxiclav.\nLimit the duration (≤14 days) — hepatotoxicity risk increases with duration.\nMonitor liver function in patients with liver disease and in the elderly.\nAdjust the dose in renal impairment (extended intervals).\nTake with food to reduce GI discomfort (absorption is not affected).\nCaution with warfarin (INR increase), methotrexate and allopurinol.\nIn infectious mononucleosis, avoid (frequent skin rash).',
   'DailyMed/FDA — Amoxicillin and Clavulanate Potassium Tablets, secção 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7526a33a-18d6-36ca-e053-2a91aa0ab9f9',
   'DailyMed/FDA — Amoxicillin and Clavulanate Potassium Tablets label, section 12 CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7526a33a-18d6-36ca-e053-2a91aa0ab9f9'),

  ('atovaquona-proguanil',
   'A atovaquona + proguanil (Malarone) é um antimalárico de associação usado na prevenção (profilaxia) e no tratamento da malária por Plasmodium falciparum, incluindo em zonas com resistência à cloroquina. Os dois princípios ativos atuam em conjunto, bloqueando etapas diferentes do ciclo de vida do parasita. Deve ser tomado com alimentos ou leite, para melhorar a absorção, e só com indicação médica adequada ao destino de viagem.',
   'Atovaquone + proguanil (Malarone) is a combination antimalarial used for the prevention (prophylaxis) and treatment of Plasmodium falciparum malaria, including areas with chloroquine resistance. The two active ingredients work together, blocking different steps of the parasite life cycle. It should be taken with food or milk to improve absorption, and only with medical advice appropriate for the travel destination.',
   'Associação sinérgica de atovaquona (análogo da ubiquinona que inibe o transporte de eletrões mitocondrial do parasita) e proguanil (pró-fármaco convertido em cicloguanil, inibidor da di-hidrofolato redutase do plasmódio). A combinação é sinérgica contra P. falciparum, incluindo estirpes resistentes à cloroquina, mefloquina e amodiaquina. A atovaquona tem semivida de 2-3 dias; o proguanil 12-21 h (maior em metabolizadores lentos). Biodisponibilidade da atovaquona com alimentos 23%; proguanil 40-60% excretado por via renal.',
   'Synergistic combination of atovaquone (a ubiquinone analogue that inhibits the parasite mitochondrial electron transport) and proguanil (a prodrug converted to cycloguanil, an inhibitor of the plasmodium dihydrofolate reductase). The combination is synergistic against P. falciparum, including strains resistant to chloroquine, mefloquine and amodiaquine. Atovaquone has a half-life of 2-3 days; proguanil 12-21 h (longer in slow metabolisers). Atovaquone bioavailability with food 23%; proguanil 40-60% excreted renally.',
   E'Profilaxia da malária por Plasmodium falciparum, incluindo em áreas com resistência à cloroquina.\nTratamento da malária aguda não complicada por P. falciparum.',
   E'Prophylaxis of Plasmodium falciparum malaria, including areas with chloroquine resistance.\nTreatment of acute uncomplicated P. falciparum malaria.',
   E'Dor abdominal, náuseas, vómitos e diarreia (mais frequentes nas doses de tratamento do que na profilaxia).\nCefaleia.\nErupção cutânea e prurido.\nElevação das transaminases.\nTonturas, insónia, febre.\nRaramente: reações cutâneas graves (SJS/NET), hepatotoxicidade, anemia, neutropenia.',
   E'Abdominal pain, nausea, vomiting and diarrhoea (more frequent at treatment doses than during prophylaxis).\nHeadache.\nSkin rash and pruritus.\nElevated transaminases.\nDizziness, insomnia, fever.\nRarely: severe cutaneous reactions (SJS/TEN), hepatotoxicity, anaemia, neutropenia.',
   E'Contraindicado em hipersensibilidade à atovaquona ou ao proguanil e na profilaxia de doentes com insuficiência renal grave (CrCl <30 mL/min).\nTomar com alimentos ou leite (a absorção da atovaquona aumenta 2-3x com gordura alimentar).\nVómitos e diarreia podem reduzir a absorção — vigiar e considerar alternativa em doentes com vómitos persistentes.\nEvitar em grávidas na profilaxia (usar apenas se o benefício superar o risco; na malária a doença materna é mais grave).\nVigiar sinais de hepatotoxicidade e reações cutâneas graves.\nPode interferir com o doseamento de anticorpos? Não — mas não administrar com tetraciclinas (redução teórica da eficácia da atovaquona).',
   E'Contraindicated in hypersensitivity to atovaquone or proguanil and in prophylaxis of patients with severe renal impairment (CrCl <30 mL/min).\nTake with food or milk (atovaquone absorption increases 2-3x with dietary fat).\nVomiting and diarrhoea can reduce absorption — monitor and consider an alternative in patients with persistent vomiting.\nAvoid in pregnancy for prophylaxis (use only if benefit outweighs risk; maternal malaria is more severe).\nMonitor for signs of hepatotoxicity and severe skin reactions.\nDo not co-administer with tetracyclines (theoretical reduction of atovaquone efficacy).',
   'DailyMed/FDA — Malarone (atovaquone and proguanil hydrochloride) Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc22e8d8-3bfb-4f70-a599-dd81262a4887',
   'DailyMed/FDA — Malarone (atovaquone and proguanil hydrochloride) Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc22e8d8-3bfb-4f70-a599-dd81262a4887'),

  ('budesonida',
   'A budesonida é um corticosteroide inalado usado na manutenção do tratamento da asma, incluindo em crianças pequenas (a partir dos 12 meses). Atua reduzindo a inflamação das vias respiratórias. Não serve para aliviar uma crise aguda de falta de ar — para isso existem os broncodilatadores de alívio rápido. Deve ser usada regularmente, conforme prescrito.',
   'Budesonide is an inhaled corticosteroid used for the maintenance treatment of asthma, including in young children (from 12 months of age). It works by reducing airway inflammation. It is not intended to relieve an acute asthma attack — rapid-relief bronchodilators are used for that. It must be used regularly, as prescribed.',
   'Corticosteroide inalado com elevada afinidade para o recetor dos glucocorticóides (ação anti-inflamatória potente e localizada nas vias aéreas). Na nebulização em crianças, a biodisponibilidade sistémica total (pulmonar + oral) é ~6% da dose; pico plasmático ~20 min após 1 mg nebulizado. Ligação proteica 85-90%; metabolismo CYP3A4 em 16α-hidroxiprednisolona e 6β-hidroxibudesonida (atividade <1% do composto-mãe); semivida terminal 2,3 h em crianças.',
   'Inhaled corticosteroid with high affinity for the glucocorticoid receptor (potent, localised anti-inflammatory action in the airways). After nebulisation in children, total systemic bioavailability (lung + oral) is ~6% of the dose; plasma peak ~20 min after a 1 mg nebulised dose. Protein binding 85-90%; CYP3A4 metabolism to 16α-hydroxyprednisolone and 6β-hydroxybudesonide (activity <1% of the parent compound); terminal half-life 2.3 h in children.',
   E'Manutenção do tratamento da asma em crianças dos 12 meses aos 8 anos.\nTerapia profilática da asma (prevenção de exacerbações).\nNão indicado para o alívio do broncospasmo agudo.',
   E'Maintenance treatment of asthma in children 12 months to 8 years of age.\nProphylactic asthma therapy (prevention of exacerbations).\nNot indicated for the relief of acute bronchospasm.',
   E'Candidíase oral e faringite (risco reduzido lavando a boca após a inalação).\nTosse e rouquidão.\nBroncospasmo paradoxal (raro).\nEfeitos sistémicos com doses altas/prolongadas: supressão adrenal, redução da densidade mineral óssea, atraso do crescimento em crianças, glaucoma e cataratas.\nReações de hipersensibilidade (incluindo anafilaxia — raras).',
   E'Oral candidiasis and pharyngitis (risk reduced by rinsing the mouth after inhalation).\nCough and hoarseness.\nParadoxical bronchospasm (rare).\nSystemic effects with high/prolonged doses: adrenal suppression, reduced bone mineral density, growth retardation in children, glaucoma and cataracts.\nHypersensitivity reactions (including anaphylaxis — rare).',
   E'Não usar para alívio do broncospasmo agudo (sem efeito imediato).\nLavar a boca com água após cada inalação para prevenir candidíase oral.\nMonitorizar o crescimento nas crianças em tratamento prolongado.\nVigiar supressão adrenal na transição de corticoides orais ou em doses altas.\nEvitar inibidores fortes do CYP3A4 (ex.: cetoconazol, ritonavir) — aumentam a exposição sistémica.\nUsar com precaução na tuberculose ativa ou latente, infeções fúngicas, bacterianas ou virais não tratadas.\nReavaliar o plano de tratamento se a asma não estiver controlada.',
   E'Do not use for relief of acute bronchospasm (no immediate effect).\nRinse the mouth with water after each inhalation to prevent oral candidiasis.\nMonitor growth in children on long-term treatment.\nWatch for adrenal suppression when switching from oral corticosteroids or on high doses.\nAvoid strong CYP3A4 inhibitors (e.g., ketoconazole, ritonavir) — they increase systemic exposure.\nUse with caution in active or latent tuberculosis and untreated fungal, bacterial or viral infections.\nReassess the treatment plan if asthma is not controlled.',
   'DailyMed/FDA — Budesonide Inhalation Suspension, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c52c5382-1400-44b9-95be-a30e1cf706da',
   'DailyMed/FDA — Budesonide Inhalation Suspension label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c52c5382-1400-44b9-95be-a30e1cf706da'),

  ('ceftazidima',
   'A ceftazidima é um antibiótico injetável da família das cefalosporinas (3.ª geração), usado em infeções hospitalares graves, com atividade importante contra a Pseudomonas aeruginosa. Só é administrada por via intravenosa ou intramuscular, geralmente em ambiente hospitalar.',
   'Ceftazidime is an injectable antibiotic of the cephalosporin family (third generation), used in severe hospital-acquired infections, with important activity against Pseudomonas aeruginosa. It is only given intravenously or intramuscularly, usually in hospital.',
   'Cefalosporina de 3.ª geração (bactericida, inibe a síntese da parede celular). Ativa contra Pseudomonas aeruginosa e outras Pseudomonas, Haemophilus influenzae (incluindo resistentes à ampicilina), Klebsiella, Enterobacter, Proteus mirabilis, E. coli, Serratia e Citrobacter. Semivida ~1,9 h (IV); ~10% ligação proteica; excreção renal 80-90% inalterada em 24 h (ajustar na insuficiência renal); sem ajuste na disfunção hepática isolada.',
   'Third-generation cephalosporin (bactericidal, inhibits cell wall synthesis). Active against Pseudomonas aeruginosa and other Pseudomonas, Haemophilus influenzae (including ampicillin-resistant strains), Klebsiella, Enterobacter, Proteus mirabilis, E. coli, Serratia and Citrobacter. Half-life ~1.9 h (IV); ~10% protein binding; 80-90% excreted unchanged in the urine within 24 h (adjust in renal impairment); no adjustment for isolated hepatic dysfunction.',
   E'Infeções do trato respiratório inferior, incluindo pneumonia por Pseudomonas aeruginosa.\nInfeções urinárias complicadas.\nSépsis e bacteriemia.\nInfeções intra-abdominais.\nMeningite bacteriana (em associação, quando adequado).\nInfeções da pele, tecidos moles, ossos e articulações.',
   E'Lower respiratory tract infections, including Pseudomonas aeruginosa pneumonia.\nComplicated urinary tract infections.\nSepsis and bacteraemia.\nIntra-abdominal infections.\nBacterial meningitis (in combination, when appropriate).\nSkin, soft tissue, bone and joint infections.',
   E'Flebite e inflamação no local de injeção (<2%).\nReações de hipersensibilidade: prurido, erupção cutânea, febre (~2%); raramente anafilaxia.\nDiarreia e perturbações gastrointestinais.\nEosinofilia, trombocitose, leucopenia.\nElevação das transaminases, BUN e creatinina.\nColite pseudomembranosa (Clostridioides difficile).\nNeurotoxicidade/convulsões (doses altas em insuficiência renal).',
   E'Phlebitis and injection site inflammation (<2%).\nHypersensitivity reactions: pruritus, skin rash, fever (~2%); rarely anaphylaxis.\nDiarrhoea and gastrointestinal disturbances.\nEosinophilia, thrombocytosis, leucopenia.\nElevated transaminases, BUN and creatinine.\nPseudomembranous colitis (Clostridioides difficile).\nNeurotoxicity/seizures (high doses in renal impairment).',
   E'Contraindicado em hipersensibilidade a cefalosporinas (reação cruzada com penicilinas).\nAjustar a dose na insuficiência renal (intervalos alargados) para evitar neurotoxicidade e acumulação.\nVigiar diarreia (colite por C. difficile pode surgir durante ou após o tratamento).\nUsar com precaução em doentes com doença gastrointestinal, especialmente colite.\nRisco de superinfeção com uso prolongado.\nNa gravidez, usar apenas se claramente necessário (categoria B nos EUA).',
   E'Contraindicated in cephalosporin hypersensitivity (cross-reaction with penicillins).\nAdjust the dose in renal impairment (extended intervals) to avoid accumulation and neurotoxicity.\nMonitor diarrhoea (C. difficile colitis may occur during or after treatment).\nUse with caution in patients with gastrointestinal disease, especially colitis.\nRisk of superinfection with prolonged use.\nIn pregnancy, use only if clearly needed (Category B in the US).',
   'DailyMed/FDA — Tazicef (ceftazidime for injection), secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b73979c-c95a-4433-0a9d-f9cea3cb557f',
   'DailyMed/FDA — Tazicef (ceftazidime for injection) label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b73979c-c95a-4433-0a9d-f9cea3cb557f'),

  ('ceftriaxona',
   'A ceftriaxona é um antibiótico injetável de largo espetro da família das cefalosporinas (3.ª geração), usado em infeções graves, incluindo meningite, sépsis, pneumonia e gonorreia. Como tem uma semivida longa, pode ser administrada uma vez por dia.',
   'Ceftriaxone is a broad-spectrum injectable antibiotic of the cephalosporin family (third generation), used in severe infections, including meningitis, sepsis, pneumonia and gonorrhoea. Because of its long half-life, it can be given once daily.',
   'Cefalosporina de 3.ª geração de largo espetro com semivida longa (~5,8-8,7 h) que permite dose única diária; atravessa a barreira hematoencefálica (útil na meningite). Excreção renal e biliar. Precaução importante: não administrar com soluções contendo cálcio em recém-nascidos (<28 dias) por risco de precipitados; pode causar lamas biliares e litíase biliar.',
   'Third-generation broad-spectrum cephalosporin with a long half-life (~5.8-8.7 h) allowing once-daily dosing; crosses the blood-brain barrier (useful in meningitis). Renal and biliary excretion. Important caution: do not administer with calcium-containing solutions in neonates (<28 days) due to the risk of precipitates; may cause biliary sludge and gallstones.',
   E'Pneumonia e infeções do trato respiratório inferior.\nInfeções urinárias complicadas e pielonefrite.\nSépsis e bacteriemia.\nMeningite bacteriana.\nGonorreia não complicada e complicada.\nDoença de Lyme e febre tifóide.\nProfilaxia cirúrgica.',
   E'Pneumonia and lower respiratory tract infections.\nComplicated urinary tract infections and pyelonephritis.\nSepsis and bacteraemia.\nBacterial meningitis.\nUncomplicated and complicated gonorrhoea.\nLyme disease and typhoid fever.\nSurgical prophylaxis.',
   E'Diarreia (2,7%).\nErupção cutânea (1,7%); prurido, febre (<1%).\nEosinofilia (6%), trombocitose (5,1%), leucopenia (2,1%).\nElevação das transaminases, BUN e creatinina.\nFlebite no local de injeção (<1%).\nLamas biliares e litíase biliar (reversíveis).\nRaramente: anemia hemolítica, agranulocitose, anafilaxia, convulsões, nefrolitíase.',
   E'Diarrhoea (2.7%).\nSkin rash (1.7%); pruritus, fever (<1%).\nEosinophilia (6%), thrombocytosis (5.1%), leucopenia (2.1%).\nElevated transaminases, BUN and creatinine.\nInjection site phlebitis (<1%).\nBiliary sludge and gallstones (reversible).\nRarely: haemolytic anaemia, agranulocytosis, anaphylaxis, seizures, nephrolithiasis.',
   E'Contraindicado em hipersensibilidade a cefalosporinas (reação cruzada com penicilinas).\nNão administrar com soluções contendo cálcio em recém-nascidos (<28 dias) — risco de precipitação fatal.\nVigiar diarreia (colite por C. difficile).\nEcografia em doentes com sintomas biliares (lamas/litíase).\nAjustar na insuficiência renal e hepática graves simultâneas.\nUsar com precaução na doença hemolítica/autoimune e na colite.\nNa gravidez, usar apenas se claramente necessário.',
   E'Contraindicated in cephalosporin hypersensitivity (cross-reaction with penicillins).\nDo not administer with calcium-containing solutions in neonates (<28 days) — risk of fatal precipitation.\nMonitor diarrhoea (C. difficile colitis).\nUltrasound in patients with biliary symptoms (sludge/gallstones).\nAdjust in combined severe renal and hepatic impairment.\nUse with caution in haemolytic/autoimmune disease and colitis.\nIn pregnancy, use only if clearly needed.',
   'DailyMed/FDA — Ceftriaxone Injection (premixed Galaxy containers), secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c2d3f-5038-41a1-a2fe-4dcd048dbac1',
   'DailyMed/FDA — Ceftriaxone Injection (premixed Galaxy containers) label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c2d3f-5038-41a1-a2fe-4dcd048dbac1'),

  ('cetirizina',
   'A cetirizina é um anti-histamínico de segunda geração usado no alívio dos sintomas de alergias respiratórias (rinite alérgica) e da urticária: espirros, corrimento e comichão no nariz, olhos lacrimejantes e comichão. É menos sedativa do que os anti-histamínicos antigos e, por isso, pode ser tomada durante o dia.',
   'Cetirizine is a second-generation antihistamine used to relieve the symptoms of respiratory allergies (allergic rhinitis) and urticaria: sneezing, runny and itchy nose, watery eyes and itching. It is less sedating than older antihistamines and can therefore be taken during the day.',
   'Anti-histamínico H1 de 2.ª geração (metabolito ativo da hidroxizina) com mínima penetração no SNC (menos sedação e efeitos anticolinérgicos do que os de 1.ª geração). Semivida de eliminação ~8,3 h (146 voluntários saudáveis); ~93% ligação proteica; excreção renal predominante (~60-70% inalterado — ajustar na insuficiência renal e nos idosos); início de ação ~1 h, duração ≥24 h com dose única diária.',
   'Second-generation H1 antihistamine (active metabolite of hydroxyzine) with minimal CNS penetration (less sedation and anticholinergic effects than first-generation agents). Elimination half-life ~8.3 h (146 healthy volunteers); ~93% protein binding; predominantly renal excretion (~60-70% unchanged — adjust in renal impairment and the elderly); onset ~1 h, duration ≥24 h with once-daily dosing.',
   E'Alívio temporário dos sintomas de rinite alérgica (sazonal e perene): espirros, corrimento nasal, comichão no nariz e na garganta, olhos lacrimejantes e comichão.\nAlívio da comichão e da urticária (urticária idiopática crónica).',
   E'Temporary relief of allergic rhinitis symptoms (seasonal and perennial): sneezing, runny nose, itching of the nose and throat, watery and itchy eyes.\nRelief of itching and hives (chronic idiopathic urticaria).',
   E'Sonolência ligeira e fadiga (menos frequente do que nos anti-histamínicos de 1.ª geração, mas possível).\nBoca seca.\nCefaleia, tonturas.\nDor abdominal, náuseas, diarreia.\nEm crianças: faringite, tosse, irritabilidade.\nRaramente: reações de hipersensibilidade, palpitações, aumento do apetite.',
   E'Mild drowsiness and fatigue (less frequent than with first-generation antihistamines, but possible).\nDry mouth.\nHeadache, dizziness.\nAbdominal pain, nausea, diarrhoea.\nIn children: pharyngitis, cough, irritability.\nRarely: hypersensitivity reactions, palpitations, increased appetite.',
   E'Evitar álcool e outros depressores do sistema nervoso central (potenciam a sonolência).\nAjustar a dose na insuficiência renal e nos idosos (semivida prolongada).\nPrecaução na gravidez e amamentação (usar apenas se necessário e após aconselhamento médico).\nNão exceder a dose recomendada (risco de sonolência e efeitos anticolinérgicos).\nPrecaução em doentes com epilepsia ou risco de convulsões.',
   E'Avoid alcohol and other CNS depressants (they potentiate drowsiness).\nAdjust the dose in renal impairment and the elderly (prolonged half-life).\nCaution in pregnancy and breastfeeding (use only if needed and after medical advice).\nDo not exceed the recommended dose (risk of drowsiness and anticholinergic effects).\nCaution in patients with epilepsy or seizure risk.',
   'DailyMed/FDA — Cetirizine Hydrochloride OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b9ac489a-80ed-4077-b68e-d03df1b892a6 + PubMed PMID 8477559 (farmacocinética/excreção renal)',
   'DailyMed/FDA — Cetirizine Hydrochloride OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b9ac489a-80ed-4077-b68e-d03df1b892a6 + PubMed PMID 8477559 (pharmacokinetics/renal excretion)'),

  ('cianocobalamina',
   'A cianocobalamina é a forma sintética da vitamina B12, essencial para a formação das células sanguíneas e para o funcionamento do sistema nervoso. É usada no tratamento da anemia perniciosa e de outras carências de vitamina B12 por má absorção, geralmente por injeção intramuscular. Em dietas vegetarianas/veganas pode ser necessária como suplemento oral.',
   'Cyanocobalamin is the synthetic form of vitamin B12, essential for blood cell formation and nervous system function. It is used to treat pernicious anaemia and other vitamin B12 deficiencies due to malabsorption, usually by intramuscular injection. Oral supplementation may be needed in vegetarian/vegan diets.',
   'Vitamina hidrossolúvel (cobalamina) essencial para a hematopoiese, síntese de nucleoproteínas e mielina. A absorção oral depende do fator intrínseco e do cálcio no íleo terminal (~1% por difusão simples com doses muito altas); a via parenteral (IM/SC) é rápida e fiável (pico plasmático <1 h), com o fígado como principal órgão de armazenamento. 50-98% da dose injetada aparece na urina em 48 h. Exige terapêutica de manutenção vitalícia na anemia perniciosa.',
   'Water-soluble vitamin (cobalamin) essential for haematopoiesis, nucleoprotein and myelin synthesis. Oral absorption depends on intrinsic factor and calcium in the terminal ileum (~1% by simple diffusion with very high doses); the parenteral route (IM/SC) is rapid and reliable (plasma peak <1 h), with the liver as the main storage organ. 50-98% of an injected dose appears in the urine within 48 h. Requires lifelong maintenance therapy in pernicious anaemia.',
   E'Anemia perniciosa (Addisoniana).\nCarências de vitamina B12 por má absorção: patologia/cirurgia gastrointestinal (gastrectomia, doença celíaca/sprue, sobrecrescimento bacteriano), parasitose por ténia do peixe, malignidade do pâncreas ou intestino, défice de ácido fólico.\nSuplementação oral em vegetarianos/veganos estritos e em necessidades aumentadas (gravidez, lactação).\nTeste de absorção de vitamina B12 (teste de Schilling).',
   E'Pernicious (Addisonian) anaemia.\nVitamin B12 deficiency due to malabsorption: gastrointestinal pathology/surgery (gastrectomy, coeliac disease/sprue, bacterial overgrowth), fish tapeworm infestation, malignancy of the pancreas or bowel, folic acid deficiency.\nOral supplementation in strict vegetarians/vegans and in increased requirements (pregnancy, lactation).\nVitamin B12 absorption test (Schilling test).',
   E'Reações no local de injeção (dor, eritema).\nComichão e exantema transitório.\nDiarreia ligeira e transitória.\nSensação de inchaço corporal.\nRaramente: edema pulmonar e insuficiência cardíaca congestiva no início do tratamento de anemia grave, trombose vascular periférica, policitemia vera.\nAnafilaxia (rara, após administração parentérica).',
   E'Injection site reactions (pain, erythema).\nItching and transient exanthema.\nMild transient diarrhoea.\nFeeling of swelling of the whole body.\nRarely: pulmonary oedema and congestive heart failure early in treatment of severe anaemia, peripheral vascular thrombosis, polycythaemia vera.\nAnaphylaxis (rare, after parenteral administration).',
   E'Contraindicado em sensibilidade ao cobalto e/ou à vitamina B12.\nDoentes com doença de Leber (atrofia ótica hereditária): risco de atrofia ótica grave e rápida.\nVigiar potássio sérico nas primeiras 48 h no tratamento de anemia megaloblástica grave (hipocaliemia, morte súbita).\nO ácido fólico pode corrigir a anemia mas não as lesões neurológicas — não usar em substituição.\nNa anemia perniciosa, a terapêutica é vitalícia.\nProdutos com álcool benzílico: evitar em prematuros (síndrome do gasping).',
   E'Contraindicated in sensitivity to cobalt and/or vitamin B12.\nPatients with Leber disease (hereditary optic atrophy): risk of severe and rapid optic atrophy.\nMonitor serum potassium in the first 48 h when treating severe megaloblastic anaemia (hypokalaemia, sudden death).\nFolic acid can correct the anaemia but not the neurological damage — do not use as a substitute.\nIn pernicious anaemia, therapy is lifelong.\nProducts with benzyl alcohol: avoid in premature infants (gasping syndrome).',
   'DailyMed/FDA — Cyanocobalamin Injection, USP (secção CLINICAL PHARMACOLOGY/INDICATIONS): https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=071f7c95-7243-4014-b336-db8962ac0f75',
   'DailyMed/FDA — Cyanocobalamin Injection, USP (section CLINICAL PHARMACOLOGY/INDICATIONS): https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=071f7c95-7243-4014-b336-db8962ac0f75'),

  ('daptomicina',
   'A daptomicina é um antibiótico injetável usado no tratamento de infeções graves da pele e dos tecidos moles causadas por bactérias Gram-positivas, incluindo estafilococos resistentes à meticilina (MRSA) e infeções da corrente sanguínea (bacteriemia). É administrada por via intravenosa, geralmente uma vez por dia.',
   'Daptomycin is an injectable antibiotic used to treat serious skin and soft tissue infections caused by Gram-positive bacteria, including methicillin-resistant staphylococci (MRSA), and bloodstream infections (bacteraemia). It is given intravenously, usually once daily.',
   'Lipopéptido cíclico bactericida dependente de cálcio que se insere na membrana citoplasmática das bactérias Gram-positivas, causando despolarização rápida e morte celular. Ativo contra S. aureus (incluindo MRSA), estreptococos e enterococos (incluindo VRE). Semivida ~8 h (permite dose única diária); excreção renal predominante (ajustar na insuficiência renal). Não é ativo contra Gram-negativos (não atravessa a membrana externa).',
   'Calcium-dependent cyclic lipopeptide, bactericidal, that inserts into the cytoplasmic membrane of Gram-positive bacteria, causing rapid depolarisation and cell death. Active against S. aureus (including MRSA), streptococci and enterococci (including VRE). Half-life ~8 h (allows once-daily dosing); predominantly renal excretion (adjust in renal impairment). Not active against Gram-negatives (does not cross the outer membrane).',
   E'Infeções complicadas da pele e tecidos moles (cSSSI) em adultos e crianças (1-17 anos) por bactérias Gram-positivas suscetíveis, incluindo MRSA.\nBacteriemia de S. aureus (incluindo endocardite do lado direito) em adultos.',
   E'Complicated skin and skin structure infections (cSSSI) in adults and children (1-17 years) caused by susceptible Gram-positive bacteria, including MRSA.\nStaphylococcus aureus bloodstream infections (including right-sided endocarditis) in adults.',
   E'Obstipação, náuseas, diarreia, vómitos.\nCefaleia, insónia, tonturas.\nErupção cutânea, prurido, febre.\nElevação da creatina quinase (CK) — sinal de miopatia.\nRaramente: rabdomiólise, pneumonia eosinofílica, nefrite túbulo-intersticial, neuropatia periférica, anafilaxia, aumento do INR.',
   E'Constipation, nausea, diarrhoea, vomiting.\nHeadache, insomnia, dizziness.\nSkin rash, pruritus, fever.\nElevated creatine kinase (CK) — a sign of myopathy.\nRarely: rhabdomyolysis, eosinophilic pneumonia, tubulointerstitial nephritis, peripheral neuropathy, anaphylaxis, INR increase.',
   E'Vigiar semanalmente a creatina kinase (CK) — suspender se houver miopatia/sintomas musculares com CK elevada.\nEvitar estatinas durante o tratamento (risco de miopatia aditiva).\nAjustar a dose na insuficiência renal (CrCl <30 mL/min).\nNão usar na pneumonia (inativado pelo surfactante pulmonar).\nVigiar pneumonia eosinofílica (febre, tosse, dispneia — suspender).\nMonitorizar INR em doentes em varfarina.',
   E'Monitor creatine kinase (CK) weekly — discontinue if myopathy/muscle symptoms with elevated CK.\nAvoid statins during treatment (additive myopathy risk).\nAdjust the dose in renal impairment (CrCl <30 mL/min).\nDo not use in pneumonia (inactivated by pulmonary surfactant).\nWatch for eosinophilic pneumonia (fever, cough, dyspnoea — discontinue).\nMonitor INR in patients on warfarin.',
   'DailyMed/FDA — Daptomycin for Injection, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f4ad8613-f25e-4b82-9621-cc5ff9525d3e',
   'DailyMed/FDA — Daptomycin for Injection label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f4ad8613-f25e-4b82-9621-cc5ff9525d3e'),

  ('donepezilo',
   'O donepezilo é um medicamento usado no tratamento da doença de Alzheimer (demência), em fases ligeira, moderada e grave. Atua aumentando os níveis de acetilcolina no cérebro, uma substância importante para a memória e o pensamento. Não cura a doença, mas pode melhorar ou estabilizar temporariamente os sintomas.',
   'Donepezil is a medicine used to treat Alzheimer disease (dementia) in mild, moderate and severe stages. It works by increasing acetylcholine levels in the brain, a substance important for memory and thinking. It does not cure the disease, but may temporarily improve or stabilise symptoms.',
   'Inibidor reversível e seletivo da acetilcolinesterase (aumenta a acetilcolina no SNC, melhorando a função cognitiva). Semivida de eliminação ~70 h (acumulação 4-7x, estado de equilíbrio em ~15 dias); ~96% ligação proteica; metabolismo CYP2D6 e CYP3A4 + glucuronidação; volume de distribuição 12-16 L/kg. Eficácia demonstrada na doença de Alzheimer ligeira, moderada e grave.',
   'Reversible, selective acetylcholinesterase inhibitor (increases CNS acetylcholine, improving cognitive function). Elimination half-life ~70 h (4-7x accumulation, steady state in ~15 days); ~96% protein binding; CYP2D6 and CYP3A4 metabolism plus glucuronidation; volume of distribution 12-16 L/kg. Efficacy demonstrated in mild, moderate and severe Alzheimer disease.',
   E'Tratamento sintomático da demência do tipo Alzheimer (fases ligeira, moderada e grave).',
   E'Symptomatic treatment of dementia of the Alzheimer type (mild, moderate and severe stages).',
   E'Diarreia, náuseas, vómitos (frequentes no início; mais comuns com a dose de 23 mg).\nAnorexia e perda de peso.\nInsónia, pesadelos, fadiga.\nCãibras musculares, cefaleia.\nBradicardia e síncope (efeito vagotónico).\nRaramente: úlcera péptica e hemorragia gastrointestinal, convulsões, bloqueio cardíaco.',
   E'Diarrhoea, nausea, vomiting (common at initiation; more frequent with the 23 mg dose).\nAnorexia and weight loss.\nInsomnia, nightmares, fatigue.\nMuscle cramps, headache.\nBradycardia and syncope (vagotonic effect).\nRarely: peptic ulcer and GI bleeding, seizures, heart block.',
   E'Vigiar frequência cardíaca (bradicardia, bloqueio — precaução em doença do nó sinusal e bloqueio cardíaco).\nPrecaução em doentes com risco de úlcera péptica/hemorragia GI (aumento da secreção ácida) e com doença pulmonar (asma/DPOC).\nRisco de convulsões — precaução em epilepsia.\nOs efeitos GI podem ser minimizados aumentando a dose gradualmente e tomando com alimentos.\nNão suspender bruscamente sem aconselhamento (deterioração cognitiva).',
   E'Monitor heart rate (bradycardia, block — caution in sick sinus syndrome and heart block).\nCaution in patients at risk of peptic ulcer/GI bleeding (increased acid secretion) and with pulmonary disease (asthma/COPD).\nSeizure risk — caution in epilepsy.\nGI effects can be minimised by gradual dose escalation and taking with food.\nDo not stop abruptly without advice (cognitive deterioration).',
   'DailyMed/FDA — Donepezil Hydrochloride Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=12a755c5-1ad9-43d1-832a-eb2ff17bd693',
   'DailyMed/FDA — Donepezil Hydrochloride Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=12a755c5-1ad9-43d1-832a-eb2ff17bd693'),

  ('epoetina_alfa',
   'A epoetina alfa é uma forma sintética da eritropoietina, a hormona que estimula a produção de glóbulos vermelhos na medula óssea. É usada no tratamento da anemia associada à doença renal crónica, à quimioterapia e ao tratamento da infeção por VIH com zidovudina, reduzindo a necessidade de transfusões.',
   'Epoetin alfa is a synthetic form of erythropoietin, the hormone that stimulates red blood cell production in the bone marrow. It is used to treat anaemia associated with chronic kidney disease, chemotherapy and HIV infection treated with zidovudine, reducing the need for transfusions.',
   'Eritropoietina humana recombinante (fator de crescimento hematopoiético) que estimula a eritropoiese na medula óssea. Semivida IV 4-13 h em doentes com DRC; SC: pico em 5-24 h, semivida ~40 h (16-67 h) em doentes oncológicos; excreção/clearance maioritariamente não renal (metabolismo celular). Requer monitorização da hemoglobina para evitar ultrapassar o alvo (risco tromboembólico).',
   'Recombinant human erythropoietin (haematopoietic growth factor) that stimulates erythropoiesis in the bone marrow. IV half-life 4-13 h in CKD patients; SC: peak in 5-24 h, half-life ~40 h (16-67 h) in cancer patients; clearance largely non-renal (cellular metabolism). Requires haemoglobin monitoring to avoid overshooting the target (thromboembolic risk).',
   E'Tratamento da anemia da doença renal crónica (em diálise e não diálise), para reduzir a necessidade de transfusões.\nAnemia associada à zidovudina (≤4200 mg/semana) em doentes com infeção por VIH.\nAnemia em doentes oncológicos sob quimioterapia (conforme indicações aprovadas).',
   E'Treatment of anaemia due to chronic kidney disease (on and off dialysis) to reduce the need for red blood cell transfusions.\nAnaemia due to zidovudine (≤4200 mg/week) in patients with HIV infection.\nAnaemia in cancer patients on chemotherapy (per approved indications).',
   E'Hipertensão (a mais comum) e agravamento de hipertensão pré-existente.\nCefaleia, artralgias, febre, tonturas.\nNáuseas, diarreia, vómitos.\nReações no local de injeção (SC).\nEventos tromboembólicos (trombose do acesso vascular, AVC, enfarte, TVP).\nRaramente: aplasia pura da série vermelha (PRCA) por anticorpos anti-eritropoetina, convulsões, reações alérgicas graves.',
   E'Hypertension (the most common) and worsening of pre-existing hypertension.\nHeadache, arthralgia, fever, dizziness.\nNausea, diarrhoea, vomiting.\nInjection site reactions (SC).\nThromboembolic events (vascular access thrombosis, stroke, myocardial infarction, DVT).\nRarely: pure red cell aplasia (PRCA) due to anti-erythropoietin antibodies, seizures, severe allergic reactions.',
   E'Monitorizar a hemoglobina e não exceder o alvo (Hb >11-12 g/dL aumenta mortalidade/eventos cardiovasculares e tromboembólicos).\nControlar a tensão arterial (hipertensão não controlada é contraindicação relativa).\nVigiar sinais de trombose do acesso vascular (fístula) em diálise.\nSuspender se PRCA (perda súbita de resposta com anemia grave e reticulocitopenia).\nNão agitar os frascos (desnaturação da proteína); usar uma dose por frasco (sem conservantes).\nAjustar a dose com base na resposta (não mais do que ±25% por ajuste).',
   E'Monitor haemoglobin and do not exceed the target (Hb >11-12 g/dL increases mortality/cardiovascular and thromboembolic events).\nControl blood pressure (uncontrolled hypertension is a relative contraindication).\nWatch for vascular access (fistula) thrombosis in dialysis.\nDiscontinue if PRCA occurs (sudden loss of response with severe anaemia and reticulocytopenia).\nDo not shake the vials (protein denaturation); use one dose per vial (preservative-free).\nAdjust the dose based on response (no more than ±25% per adjustment).',
   'DailyMed/FDA — Epogen (epoetin alfa) Injection, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f2d0b28-9cc5-4523-80b8-637fdaf3f7a5',
   'DailyMed/FDA — Epogen (epoetin alfa) Injection label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f2d0b28-9cc5-4523-80b8-637fdaf3f7a5'),

  ('etambutol',
   'O etambutol é um antibiótico usado no tratamento da tuberculose pulmonar, sempre em associação com outros medicamentos antituberculosos. É importante vigiar a visão durante o tratamento, porque pode afetar o nervo ótico (visão turva, alteração da visão das cores).',
   'Ethambutol is an antibiotic used to treat pulmonary tuberculosis, always in combination with other antituberculosis drugs. It is important to monitor vision during treatment, because it can affect the optic nerve (blurred vision, colour vision changes).',
   'Antimicobacteriano bacteriostático que inibe a síntese de metabolitos essenciais do bacilo (interfere com a arabinogalactana da parede celular). Ativo contra Mycobacterium tuberculosis; sem resistência cruzada com outros antimicobacterianos. Pico sérico 2-5 mcg/mL, 2-4 h após 25 mg/kg oral; ~50% excretado inalterado na urina em 24 h. Efeito adverso limitante: neurite ótica (dose e duração dependentes).',
   'Bacteriostatic antimycobacterial that inhibits synthesis of essential bacillus metabolites (interferes with cell wall arabinogalactan). Active against Mycobacterium tuberculosis; no cross-resistance with other antimycobacterials. Serum peak 2-5 mcg/mL, 2-4 h after 25 mg/kg orally; ~50% excreted unchanged in urine within 24 h. Dose-limiting adverse effect: optic neuritis (dose and duration dependent).',
   E'Tratamento da tuberculose pulmonar, em associação com pelo menos outro medicamento antituberculoso (nunca em monoterapia).',
   E'Treatment of pulmonary tuberculosis, in combination with at least one other antituberculosis drug (never as monotherapy).',
   E'Neurite ótica (diminuição da acuidade visual, escotomas, discromatopsia — vermelho/verde; potencialmente irreversível).\nPerturbações gastrointestinais (náuseas, anorexia, dor abdominal).\nCefaleia, tonturas, confusão.\nHiperuricemia (e gota, raramente).\nReações de hipersensibilidade (erupção, prurido, febre).\nRaramente: hepatotoxicidade, trombocitopenia, neuropatia periférica.',
   E'Optic neuritis (decreased visual acuity, scotomas, colour vision loss — red/green; potentially irreversible).\nGastrointestinal disturbances (nausea, anorexia, abdominal pain).\nHeadache, dizziness, confusion.\nHyperuricaemia (and gout, rarely).\nHypersensitivity reactions (rash, pruritus, fever).\nRarely: hepatotoxicity, thrombocytopenia, peripheral neuropathy.',
   E'Exame oftalmológico (acuidade visual e visão das cores) antes e periodicamente durante o tratamento — suspender se alterações.\nAjustar a dose na insuficiência renal (excreção renal predominante — acumulação).\nVigiar função hepática e ácido úrico.\nUsar com precaução em doentes com catarata ou lesão prévia do nervo ótico (difícil avaliar alterações).\nFazer parte de um esquema combinado (nunca isolado).',
   E'Ophthalmologic examination (visual acuity and colour vision) before and periodically during treatment — discontinue if changes.\nAdjust the dose in renal impairment (predominantly renal excretion — accumulation).\nMonitor liver function and uric acid.\nUse with caution in patients with cataracts or pre-existing optic nerve damage (difficult to assess changes).\nAlways part of a combination regimen (never alone).',
   'DailyMed/FDA — Ethambutol Hydrochloride Tablets, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c12b3482-55f0-4324-bdcd-b129ca2dae73',
   'DailyMed/FDA — Ethambutol Hydrochloride Tablets label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c12b3482-55f0-4324-bdcd-b129ca2dae73'),

  ('fitomenadiona',
   'A fitomenadiona (vitamina K1) é a vitamina usada no tratamento e prevenção de hemorragias causadas por défice de vitamina K, incluindo a hemorragia associada a anticoagulantes (varfarina, acenocumarol). É administrada por injeção (intramuscular, subcutânea ou intravenosa lenta) e o seu efeito demora algumas horas.',
   'Phytonadione (vitamin K1) is the vitamin used to treat and prevent bleeding caused by vitamin K deficiency, including bleeding associated with anticoagulants (warfarin, acenocoumarol). It is given by injection (intramuscular, subcutaneous or slow intravenous) and its effect takes a few hours.',
   'Vitamina lipossolúvel essencial para a carboxilação gama dos fatores de coagulação dependentes da vitamina K (II, VII, IX, X) e proteínas C e S no fígado. Antídoto específico da hipoprotrombinemia induzida por cumarínicos e indanedionas. Após a administração, os fatores de coagulação começam a normalizar em poucas horas (FVII, t½ curta) com efeito máximo ~12-24 h; a correção completa depende da síntese hepática. Bem absorvida por via IM; concentra-se no fígado.',
   'Fat-soluble vitamin essential for the gamma-carboxylation of vitamin K-dependent clotting factors (II, VII, IX, X) and proteins C and S in the liver. Specific antidote for coumarin- and indanedione-induced hypoprothrombinaemia. After administration, clotting factors begin to normalise within hours (FVII, short half-life) with maximal effect ~12-24 h; full correction depends on hepatic synthesis. Well absorbed IM; concentrates in the liver.',
   E'Tratamento da hipoprotrombinemia por défice de vitamina K ou interferência com a sua atividade: anticoagulação por derivados cumarínicos ou indanedionas.\nHipoprotrombinemia associada a terapêutica antibacteriana (destruição da flora intestinal produtora de vitamina K).\nDéfice de vitamina K por má absorção, doença hepática ou obstrutiva.\nProfilaxia da doença hemorrágica do recém-nascido.',
   E'Treatment of hypoprothrombinaemia due to vitamin K deficiency or interference with vitamin K activity: anticoagulation with coumarin or indanedione derivatives.\nHypoprothrombinaemia due to antibacterial therapy (destruction of the vitamin K-producing gut flora).\nVitamin K deficiency due to malabsorption, hepatic or obstructive disease.\nProphylaxis of haemorrhagic disease of the newborn.',
   E'Reações no local de injeção (dor, tumefação, eritema).\nRubor, gosto peculiar, tonturas (com perfusão IV rápida).\nReações de hipersensibilidade (incluindo anafilaxia) — raras, mais associadas a perfusão IV rápida.\nTaquicardia, hipotensão, broncospasmo (com IV rápida).\nReações cutâneas (eritema, esclerose) no local de injeção.',
   E'Injection site reactions (pain, swelling, erythema).\nFlushing, peculiar taste, dizziness (with rapid IV infusion).\nHypersensitivity reactions (including anaphylaxis) — rare, more associated with rapid IV infusion.\nTachycardia, hypotension, bronchospasm (with rapid IV).\nCutaneous reactions (erythema, sclerosis) at the injection site.',
   E'Administrar IV apenas quando absolutamente necessário e sempre em perfusão lenta (risco de reações anafilactoides).\nEm doentes anticoagulados, doses excessivas de vitamina K podem causar resistência temporária à anticoagulação — usar a menor dose eficaz e reiniciar a anticoagulação conforme indicado.\nVigiar o INR e o tempo de protrombina.\nContraindicado em hipersensibilidade à vitamina K1.\nPrecaução na deficiência de G6PD (risco teórico de hemólise).',
   E'Administer IV only when absolutely necessary and always as a slow infusion (risk of anaphylactoid reactions).\nIn anticoagulated patients, excessive vitamin K doses can cause temporary anticoagulation resistance — use the lowest effective dose and restart anticoagulation as indicated.\nMonitor INR and prothrombin time.\nContraindicated in hypersensitivity to vitamin K1.\nCaution in G6PD deficiency (theoretical haemolysis risk).',
   'DailyMed/FDA — Vitamin K1 Injection (Phytonadione Injectable Emulsion), secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e8808230-2c44-44c6-8cab-8f29b6b34051',
   'DailyMed/FDA — Vitamin K1 Injection (Phytonadione Injectable Emulsion) label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e8808230-2c44-44c6-8cab-8f29b6b34051'),

  ('formoterol',
   'O formoterol é um broncodilatador de ação prolongada (beta-2 agonista) usado na manutenção do tratamento da doença pulmonar obstrutiva crónica (DPOC), por inalação, duas vezes por dia. Não serve para alívio imediato de uma crise de falta de ar.',
   'Formoterol is a long-acting bronchodilator (beta-2 agonist) used for the maintenance treatment of chronic obstructive pulmonary disease (COPD), by inhalation, twice daily. It is not intended for immediate relief of an acute attack of breathlessness.',
   'Beta-2 adrenérgico agonista de ação prolongada (LABA) seletivo, broncodilatador de manutenção com início de ação rápido (minutos). Na DPOC, melhora o FEV1 e os sintomas com administração 2x/dia. Em monoterapia (sem corticoide inalado) na asma aumenta o risco de eventos relacionados com a asma — por isso não é indicado para asma. Exposição sistémica baixa por via inalatória (a maior parte da dose fica no dispositivo/orofaringe).',
   'Selective long-acting beta-2 adrenergic agonist (LABA), a maintenance bronchodilator with rapid onset (minutes). In COPD, it improves FEV1 and symptoms with twice-daily dosing. As monotherapy (without an inhaled corticosteroid) in asthma it increases the risk of asthma-related events — hence not indicated for asthma. Low systemic exposure via inhalation (most of the dose stays in the device/oropharynx).',
   E'Manutenção do tratamento da broncoconstrição na DPOC (bronquite crónica e enfisema), administração 2x/dia.\nNão indicado para o tratamento de deteriorações agudas da DPOC.',
   E'Maintenance treatment of bronchoconstriction in COPD (chronic bronchitis and emphysema), twice-daily administration.\nNot indicated for the treatment of acute deteriorations of COPD.',
   E'Tremor, cefaleia, nervosismo (efeitos beta-2 sistémicos, dose-dependentes).\nPalpitações, taquicardia, arritmias; angina em doentes predispostos.\nBoca seca, cãibras musculares, náuseas, tonturas, fadiga, insónia.\nHipocaliemia, hiperglicemia, acidose metabólica (doses altas).\nBroncospasmo paradoxal (raro).',
   E'Tremor, headache, nervousness (systemic beta-2 effects, dose-dependent).\nPalpitations, tachycardia, arrhythmias; angina in predisposed patients.\nDry mouth, muscle cramps, nausea, dizziness, fatigue, insomnia.\nHypokalaemia, hyperglycaemia, metabolic acidosis (high doses).\nParadoxical bronchospasm (rare).',
   E'Não usar para alívio de crises agudas (usar o broncodilatador de curta ação de resgate).\nNa asma, usar sempre com corticoide inalado (nunca em monoterapia).\nVigiar hipocaliemia em doentes com risco (diuréticos, corticoides, hipoxia).\nPrecaução em doença cardiovascular (isquemia, arritmias, hipertensão não controlada) e hipertiroidismo.\nSuspender o uso se ocorrer broncospasmo paradoxal.\nSe os sintomas piorarem apesar do tratamento, reavaliar o plano.',
   E'Do not use for relief of acute attacks (use the short-acting rescue bronchodilator).\nIn asthma, always use with an inhaled corticosteroid (never as monotherapy).\nMonitor hypokalaemia in at-risk patients (diuretics, corticosteroids, hypoxia).\nCaution in cardiovascular disease (ischaemia, arrhythmias, uncontrolled hypertension) and hyperthyroidism.\nDiscontinue if paradoxical bronchospasm occurs.\nIf symptoms worsen despite treatment, reassess the plan.',
   'DailyMed/FDA — Formoterol Fumarate Inhalation Solution, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=35538d89-a984-4335-acdf-85a893f51eee',
   'DailyMed/FDA — Formoterol Fumarate Inhalation Solution label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=35538d89-a984-4335-acdf-85a893f51eee'),

  ('fosfomicina',
   'A fosfomicina é um antibiótico usado no tratamento da infeção urinária não complicada (cistite aguda) em mulheres, administrado numa toma única em grânulos orais. Atua impedindo a formação da parede das bactérias.',
   'Fosfomycin is an antibiotic used to treat uncomplicated urinary tract infections (acute cystitis) in women, given as a single oral dose of granules. It works by preventing bacteria from building their cell wall.',
   'Antibiótico de largo espetro (derivado do ácido fosfónico) bactericida que inibe a síntese da parede celular bacteriana (bloqueia a enzima enolpiruviltransferase, impedindo a formação do peptidoglicano). Biodisponibilidade oral 37% (jejum), reduzida para 30% com alimentos; pico 26,1 mcg/mL ~2 h após 3 g; sem ligação proteica; excreção renal inalterada (38%) e fecal (18%). Indicação: cistite aguda não complicada em mulheres (E. coli e E. faecalis).',
   'Broad-spectrum antibiotic (phosphonic acid derivative), bactericidal, that inhibits bacterial cell wall synthesis (blocks enolpyruvyltransferase, preventing peptidoglycan formation). Oral bioavailability 37% (fasting), reduced to 30% with food; peak 26.1 mcg/mL ~2 h after 3 g; no protein binding; renal excretion unchanged (38%) and faecal (18%). Indication: acute uncomplicated cystitis in women (E. coli and E. faecalis).',
   E'Tratamento da infeção urinária não complicada (cistite aguda) em mulheres, por estirpes suscetíveis de Escherichia coli e Enterococcus faecalis (dose única de 3 g).\nNão indicado para pielonefrite ou abcesso perinefrítico.',
   E'Treatment of uncomplicated urinary tract infection (acute cystitis) in women, due to susceptible strains of Escherichia coli and Enterococcus faecalis (single 3 g dose).\nNot indicated for pyelonephritis or perinephric abscess.',
   E'Diarreia (9%), vaginite (5,5%), náuseas (4,1%), cefaleia (3,9%).\nTonturas (1,3%), astenia (1,1%), dispepsia (1,1%).\nDor abdominal, dor de costas, dismenorreia, faringite.\nRaramente: anafilaxia, angioedema, anemia aplástica, colestase, necrose hepática, megacólon tóxico, perda auditiva.',
   E'Diarrhoea (9%), vaginitis (5.5%), nausea (4.1%), headache (3.9%).\nDizziness (1.3%), asthenia (1.1%), dyspepsia (1.1%).\nAbdominal pain, back pain, dysmenorrhoea, pharyngitis.\nRarely: anaphylaxis, angioedema, aplastic anaemia, cholestasis, hepatic necrosis, toxic megacolon, hearing loss.',
   E'Dissolver o conteúdo do sachê em água e tomar em jejum (absorção reduzida com alimentos).\nNÃO administrar com metoclopramida (reduz as concentrações séricas e urinárias de fosfomicina).\nSe a bacteriúria persistir ou reaparecer após o tratamento, reavaliar (pode ser necessário outro antibiótico).\nPrecaução em doentes com insuficiência renal (CrCl <10 mL/min) — não recomendado.\nVigiar diarreia (colite por C. difficile) e reações de hipersensibilidade.',
   E'Dissolve the sachet content in water and take on an empty stomach (absorption reduced with food).\nDo NOT co-administer with metoclopramide (reduces serum and urinary fosfomycin concentrations).\nIf bacteriuria persists or recurs after treatment, reassess (another antibiotic may be needed).\nCaution in renal impairment (CrCl <10 mL/min) — not recommended.\nMonitor diarrhoea (C. difficile colitis) and hypersensitivity reactions.',
   'DailyMed/FDA — Fosfomycin Tromethamine Granules for Oral Solution, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4f206750-8126-99a3-e063-6294a90ade4c',
   'DailyMed/FDA — Fosfomycin Tromethamine Granules for Oral Solution label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4f206750-8126-99a3-e063-6294a90ade4c'),

  ('hidromorfona',
   'A hidromorfona é um analgésico opióide forte, semelhante à morfina mas mais potente, usado no alívio da dor grave que requer opióide e quando as alternativas não são suficientes. É um medicamento sujeito a controlo especial: pode causar dependência, sonolência, obstipação e depressão respiratória em doses elevadas. Deve ser usado sob prescrição e vigilância médica.',
   'Hydromorphone is a strong opioid analgesic, similar to morphine but more potent, used to relieve severe pain that requires an opioid and when alternatives are inadequate. It is a controlled substance: it can cause dependence, drowsiness, constipation and respiratory depression at high doses. It must be used under medical prescription and supervision.',
   'Agonista opióide mu potente (5-7x mais potente que a morfina por via oral). Biodisponibilidade oral ~24% (extenso metabolismo de primeira passagem); pico em 0,5-1 h; semivida terminal ~2,3 h (IV); metabolismo por glucuronidação hepática (>95% em hidromorfona-3-glucuronídeo); excreção renal dos metabolitos. Risco de dependência, tolerância, abstinência, hiperalgesia e depressão respiratória — reservar para quando alternativas são inadequadas.',
   'Potent mu opioid agonist (5-7x more potent than oral morphine). Oral bioavailability ~24% (extensive first-pass metabolism); peak in 0.5-1 h; terminal half-life ~2.3 h (IV); hepatic glucuronidation (>95% to hydromorphone-3-glucuronide); renal excretion of metabolites. Risk of dependence, tolerance, withdrawal, hyperalgesia and respiratory depression — reserve for when alternatives are inadequate.',
   E'Tratamento da dor grave que requer analgésico opióide e para a qual os tratamentos alternativos são inadequados.',
   E'Management of severe pain requiring an opioid analgesic and for which alternative treatments are inadequate.',
   E'Obstipação, náuseas, vómitos.\nSonolência, tonturas, sedação.\nCefaleia, confusão, pesadelos.\nPrurido, sudação, boca seca.\nHipoventilação/depressão respiratória (dose-dependente; risco maior em idosos e com depressores do SNC).\nHipotensão ortostática, bradicardia.\nRetenção urinária.\nDependência e síndrome de abstinência com uso prolongado.',
   E'Constipation, nausea, vomiting.\nDrowsiness, dizziness, sedation.\nHeadache, confusion, nightmares.\nPruritus, sweating, dry mouth.\nHypoventilation/respiratory depression (dose-dependent; higher risk in the elderly and with CNS depressants).\nOrthostatic hypotension, bradycardia.\nUrinary retention.\nDependence and withdrawal syndrome with prolonged use.',
   E'Contraindicado em depressão respiratória significativa, obstrução gastrointestinal (íleo paralítico) e hipersensibilidade.\nNUNCA associar a álcool, benzodiazepinas ou outros depressores do SNC sem indicação (risco de depressão respiratória fatal).\nIniciar com a menor dose eficaz e titular; prescrever laxantes e antieméticos profiláticos.\nVigiar sedação e frequência respiratória (escala de sedação).\nPrecaução em insuficiência hepática e renal (acumulação), idosos, asma grave e hipertensão intracraniana.\nNão suspender bruscamente (síndrome de abstinência).',
   E'Contraindicated in significant respiratory depression, gastrointestinal obstruction (paralytic ileus) and hypersensitivity.\nNEVER combine with alcohol, benzodiazepines or other CNS depressants without indication (risk of fatal respiratory depression).\nStart at the lowest effective dose and titrate; prescribe prophylactic laxatives and antiemetics.\nMonitor sedation and respiratory rate (sedation scale).\nCaution in hepatic and renal impairment (accumulation), the elderly, severe asthma and raised intracranial pressure.\nDo not stop abruptly (withdrawal syndrome).',
   'DailyMed/FDA — Hydromorphone Hydrochloride Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c1cc8-c42b-46e3-ad68-8e22f57101f2',
   'DailyMed/FDA — Hydromorphone Hydrochloride Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c1cc8-c42b-46e3-ad68-8e22f57101f2'),

  ('indapamida',
   'A indapamida é um diurético usado no tratamento da hipertensão arterial, isolado ou em associação com outros anti-hipertensores, e no tratamento da retenção de líquidos (edema) associada à insuficiência cardíaca. Atua nos rins aumentando a eliminação de água e sal.',
   'Indapamide is a diuretic used to treat high blood pressure, alone or with other antihypertensive drugs, and to treat fluid retention (oedema) associated with heart failure. It acts on the kidneys to increase the elimination of water and salt.',
   'Diurético do tipo tiazida-like (indolina) com ação anti-hipertensora e diurética; reduz a reabsorção de sódio no túbulo distal e tem efeito vasodilatador direto. Pico plasmático ~2 h; semivida ~14 h (sangue total); 71-79% ligação proteica; excreção renal mínima de fármaco inalterado (~7%); extenso metabolismo. Reduz o potássio sérico (dose-dependente) e aumenta o ácido úrico.',
   'Thiazide-like (indoline) diuretic with antihypertensive and diuretic action; reduces sodium reabsorption in the distal tubule and has a direct vasodilatory effect. Plasma peak ~2 h; half-life ~14 h (whole blood); 71-79% protein binding; minimal renal excretion of unchanged drug (~7%); extensive metabolism. Lowers serum potassium (dose-dependent) and raises uric acid.',
   E'Tratamento da hipertensão arterial, isolado ou em associação com outros anti-hipertensores.\nTratamento da retenção de sódio e água (edema) associada à insuficiência cardíaca congestiva.',
   E'Treatment of hypertension, alone or in combination with other antihypertensive drugs.\nTreatment of salt and fluid retention (oedema) associated with congestive heart failure.',
   E'Hipocaliemia (dose-dependente), hiponatremia.\nHiperuricemia (e gota).\nHiperglicemia, hiperlipidemia.\nCefaleia, tonturas, fadiga.\nObstipação, náuseas, boca seca.\nHipotensão ortostática.\nErupção cutânea, reações de fotossensibilidade.\nRaramente: pancreatite, discrasias sanguíneas, insuficiência renal.',
   E'Hypokalaemia (dose-dependent), hyponatraemia.\nHyperuricaemia (and gout).\nHyperglycaemia, hyperlipidaemia.\nHeadache, dizziness, fatigue.\nConstipation, nausea, dry mouth.\nOrthostatic hypotension.\nSkin rash, photosensitivity reactions.\nRarely: pancreatitis, blood dyscrasias, renal failure.',
   E'Monitorizar potássio sérico, sódio, glicemia, ácido úrico e função renal.\nEvitar em doentes com hipocaliemia refratária, insuficiência renal grave (anúria) e encefalopatia hepática.\nPrecaução em doentes com gota, diabetes e doença renal.\nPrecaução com digitálicos (hipocaliemia aumenta a toxicidade), lítio (níveis aumentados) e AINEs (redução do efeito).\nEvitar exposição solar excessiva (fotossensibilidade).\nNa gravidez, o uso rotineiro de diuréticos é inadequado.',
   E'Monitor serum potassium, sodium, glucose, uric acid and renal function.\nAvoid in refractory hypokalaemia, severe renal impairment (anuria) and hepatic encephalopathy.\nCaution in patients with gout, diabetes and renal disease.\nCaution with digoxin (hypokalaemia increases toxicity), lithium (increased levels) and NSAIDs (reduced effect).\nAvoid excessive sun exposure (photosensitivity).\nIn pregnancy, routine use of diuretics is inappropriate.',
   'DailyMed/FDA — Indapamide Tablets, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=59cd3331-7afe-432a-8b50-39533fd5f392',
   'DailyMed/FDA — Indapamide Tablets label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=59cd3331-7afe-432a-8b50-39533fd5f392'),

  ('lamivudina',
   'A lamivudina é um medicamento antiviral usado no tratamento da hepatite B crónica, em doentes com replicação viral ativa e inflamação do fígado. Reduz a multiplicação do vírus e ajuda a controlar a doença. Como pode desenvolver resistência, o tratamento deve ser bem planeado e acompanhado pelo médico.',
   'Lamivudine is an antiviral medicine used to treat chronic hepatitis B, in patients with active viral replication and liver inflammation. It reduces virus multiplication and helps control the disease. Because resistance can develop, treatment must be well planned and followed up by a doctor.',
   'Análogo nucleósido inibidor da transcriptase reversa (NRTI) que bloqueia a replicação do vírus da hepatite B (e do VIH). Biodisponibilidade oral ~86-87%; pico 0,5-2 h; semivida ~5-7 h (intracelular ~17-19 h); distribuição extravascular (Vd 1,3 L/kg); excreção renal (ajustar na insuficiência renal). Limitação: altas taxas de resistência (mutação YMDD) com uso prolongado — reservar quando apropriado.',
   'Nucleoside analogue reverse transcriptase inhibitor (NRTI) that blocks replication of the hepatitis B virus (and HIV). Oral bioavailability ~86-87%; peak 0.5-2 h; half-life ~5-7 h (intracellular ~17-19 h); extravascular distribution (Vd 1.3 L/kg); renal excretion (adjust in renal impairment). Limitation: high resistance rates (YMDD mutation) with prolonged use — reserve when appropriate.',
   E'Tratamento da infeção crónica pelo vírus da hepatite B (VHB), associada a evidência de replicação viral e inflamação hepática ativa.',
   E'Treatment of chronic hepatitis B virus (HBV) infection associated with evidence of viral replication and active liver inflammation.',
   E'Cefaleia, fadiga, mal-estar.\nNáuseas, diarreia, dor abdominal.\nTosse, sintomas respiratórios.\nAumento das transaminases.\nExacerbação da hepatite B após a suspensão do tratamento.\nRaramente: acidose láctica e hepatomegalia grave com esteatose (potencialmente fatais), pancreatite, neuropatia periférica.',
   E'Headache, fatigue, malaise.\nNausea, diarrhoea, abdominal pain.\nCough, respiratory symptoms.\nElevated transaminases.\nHepatitis B exacerbation after treatment discontinuation.\nRarely: lactic acidosis and severe hepatomegaly with steatosis (potentially fatal), pancreatitis, peripheral neuropathy.',
   E'Monitorizar a função hepática (transaminases) e os marcadores virais durante e após o tratamento.\nNÃO suspender bruscamente — risco de exacerbação grave da hepatite B (vigiar vários meses após a suspensão).\nAjustar a dose na insuficiência renal.\nVigiar sinais de acidose láctica (fadiga, dor abdominal, dispneia) e de resistência viral.\nPrecaução na insuficiência hepática avançada/Child-Pugh.\nEvitar em doentes coinfectados VIH sem TARV adequado (risco de resistência do VIH a lamivudina).',
   E'Monitor liver function (transaminases) and viral markers during and after treatment.\nDo NOT stop abruptly — risk of severe hepatitis B exacerbation (monitor for several months after discontinuation).\nAdjust the dose in renal impairment.\nWatch for signs of lactic acidosis (fatigue, abdominal pain, dyspnoea) and viral resistance.\nCaution in advanced hepatic impairment/Child-Pugh.\nAvoid in HIV-coinfected patients without adequate ART (risk of HIV resistance to lamivudine).',
   'DailyMed/FDA — Lamivudine Tablets (HBV), secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6bd6b9da-df69-46db-813e-4e7f3bdecf95',
   'DailyMed/FDA — Lamivudine Tablets (HBV) label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6bd6b9da-df69-46db-813e-4e7f3bdecf95'),

  ('levocetirizina',
   'A levocetirizina é um anti-histamínico de segunda geração, usado no alívio dos sintomas de alergias respiratórias (rinite alérgica) e da urticária: espirros, corrimento e comichão no nariz, olhos lacrimejantes e comichão. É o enantiómero ativo da cetirizina, com menos sedação.',
   'Levocetirizine is a second-generation antihistamine used to relieve the symptoms of respiratory allergies (allergic rhinitis) and urticaria: sneezing, runny and itchy nose, watery eyes and itching. It is the active enantiomer of cetirizine, with less sedation.',
   'Enantiómero (R) ativo da cetirizina, anti-H1 de 2.ª geração com afinidade dupla para o recetor H1. Semivida ~7-8 h; excreção renal predominante (~85,8% inalterado em 48 h — 95% da dose total; ajustar na insuficiência renal); metabolismo hepático mínimo (CYP3A4/CYP2D6 menor); biodisponibilidade oral elevada (sem efeito de primeira passagem significativo). Início de ação <1 h, duração ≥24 h.',
   'Active (R) enantiomer of cetirizine, a second-generation H1 antihistamine with twice the H1 receptor affinity. Half-life ~7-8 h; predominantly renal excretion (~85.8% unchanged in 48 h — 95% of total dose; adjust in renal impairment); minimal hepatic metabolism (minor CYP3A4/CYP2D6); high oral bioavailability (no significant first-pass effect). Onset <1 h, duration ≥24 h.',
   E'Alívio dos sintomas de rinite alérgica (sazonal e perene) e de urticária idiopática crónica: espirros, corrimento nasal, comichão nasal/ocular, lacrimejo.',
   E'Relief of allergic rhinitis symptoms (seasonal and perennial) and of chronic idiopathic urticaria: sneezing, runny nose, nasal/ocular itching, watery eyes.',
   E'Sonolência ligeira, fadiga, astenia (menos frequente do que nos anti-histamínicos de 1.ª geração).\nBoca seca.\nCefaleia, tonturas.\nDor abdominal, náuseas, diarreia.\nEm crianças: febre, faringite, irritabilidade.\nRaramente: reações de hipersensibilidade, palpitações, aumento do apetite.',
   E'Mild drowsiness, fatigue, asthenia (less frequent than with first-generation antihistamines).\nDry mouth.\nHeadache, dizziness.\nAbdominal pain, nausea, diarrhoea.\nIn children: fever, pharyngitis, irritability.\nRarely: hypersensitivity reactions, palpitations, increased appetite.',
   E'Evitar álcool e outros depressores do SNC (potenciam a sonolência).\nAjustar a dose na insuficiência renal (semivida prolongada: 5 mg em dias alternados ou 2,5 mg/dia conforme CrCl).\nPrecaução na gravidez e amamentação (usar apenas se necessário).\nNão exceder a dose recomendada.\nPrecaução em doentes com epilepsia ou risco de convulsões.\nEm crianças <6 anos, usar conforme indicação aprovada.',
   E'Avoid alcohol and other CNS depressants (they potentiate drowsiness).\nAdjust the dose in renal impairment (prolonged half-life: 5 mg on alternate days or 2.5 mg/day depending on CrCl).\nCaution in pregnancy and breastfeeding (use only if needed).\nDo not exceed the recommended dose.\nCaution in patients with epilepsy or seizure risk.\nIn children <6 years, use per approved indication.',
   'DailyMed/FDA — Levocetirizine OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f722b84-08de-7e6a-41ac-2c9d9bb9fb43 + PubMed PMID 11758635 (ADME [14C]levocetirizina)',
   'DailyMed/FDA — Levocetirizine OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f722b84-08de-7e6a-41ac-2c9d9bb9fb43 + PubMed PMID 11758635 ([14C]levocetirizine ADME)'),

  ('loperamida',
   'A loperamida é um medicamento usado no alívio sintomático da diarreia aguda (em adultos e crianças com ≥2 anos) e da diarreia crónica associada a doença inflamatória intestinal, e na redução do débito de ileostomia. Atua abrandando os movimentos do intestino e reduzindo a perda de água e sais.',
   'Loperamide is a medicine used for the symptomatic relief of acute diarrhoea (in adults and children ≥2 years) and of chronic diarrhoea associated with inflammatory bowel disease, and to reduce ileostomy output. It works by slowing bowel movements and reducing water and salt loss.',
   'Agonista opióide periférico (não atravessa a barreira hematoencefálica em condições normais — é substrato da glicoproteína P) que reduz o peristaltismo e aumenta o tempo de trânsito intestinal, o tónus do esfíncter anal e a reabsorção de água/eletrólitos. Semivida ~10,8 h (9,1-14,4 h); ~95% ligação proteica; metabolismo CYP2C8/CYP3A4 (N-desmetilação); excreção fecal predominante.',
   'Peripheral opioid agonist (does not cross the blood-brain barrier under normal conditions — it is a P-glycoprotein substrate) that reduces peristalsis and increases intestinal transit time, anal sphincter tone and water/electrolyte reabsorption. Half-life ~10.8 h (9.1-14.4 h); ~95% protein binding; CYP2C8/CYP3A4 metabolism (N-demethylation); predominantly faecal excretion.',
   E'Controlo e alívio sintomático da diarreia aguda não específica (≥2 anos).\nDiarreia crónica em adultos associada a doença inflamatória intestinal.\nRedução do volume de débito de ileostomia.',
   E'Control and symptomatic relief of acute non-specific diarrhoea (≥2 years).\nChronic diarrhoea in adults associated with inflammatory bowel disease.\nReduction of ileostomy output volume.',
   E'Obstipação.\nTonturas, sonolência, fadiga.\nNáuseas, dor abdominal, desconforto abdominal.\nBoca seca.\nRaramente: íleo paralítico, megacólon tóxico, reações cutâneas graves, retenção urinária.',
   E'Constipation.\nDizziness, drowsiness, fatigue.\nNausea, abdominal pain, abdominal discomfort.\nDry mouth.\nRarely: paralytic ileus, toxic megacolon, severe skin reactions, urinary retention.',
   E'NÃO usar em diarreia com febre alta ou sangue nas fezes (diarreia invasiva — risco de megacólon tóxico).\nNão usar na colite ulcerosa aguda, colite pseudomembranosa ou diarreia associada a antibióticos.\nSuspender se não houver melhoria em 48 h ou se aparecer distensão abdominal/obstipação.\nEvitar doses altas com inibidores do CYP3A4 ou da glicoproteína P (ex.: itraconazol, quinidina, ritonavir) — risco de efeitos opióides centrais (depressão respiratória, arritmias QT).\nPrecaução em crianças pequenas e em doentes com doença hepática.\nNão usar em monoterapia na disenteria aguda.',
   E'Do NOT use in diarrhoea with high fever or blood in the stool (invasive diarrhoea — risk of toxic megacolon).\nDo not use in acute ulcerative colitis, pseudomembranous colitis or antibiotic-associated diarrhoea.\nDiscontinue if no improvement within 48 h or if abdominal distension/constipation develops.\nAvoid high doses with CYP3A4 or P-glycoprotein inhibitors (e.g., itraconazole, quinidine, ritonavir) — risk of central opioid effects (respiratory depression, QT arrhythmias).\nCaution in young children and in patients with liver disease.\nDo not use as monotherapy in acute dysentery.',
   'DailyMed/FDA — Loperamide Hydrochloride Capsules, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3fdfc0e5-56a2-48a0-8ee6-390a194a29f3',
   'DailyMed/FDA — Loperamide Hydrochloride Capsules label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3fdfc0e5-56a2-48a0-8ee6-390a194a29f3'),

  ('losartano',
   'O losartano é um medicamento usado no tratamento da hipertensão arterial, na proteção dos rins em doentes diabéticos com doença renal e na insuficiência cardíaca. Pertence à classe dos antagonistas dos recetores da angiotensina II (ARA II) e atua relaxando os vasos sanguíneos, baixando a pressão arterial.',
   'Losartan is a medicine used to treat high blood pressure, to protect the kidneys in diabetic patients with kidney disease, and in heart failure. It belongs to the angiotensin II receptor blocker (ARB) class and works by relaxing blood vessels, lowering blood pressure.',
   'Antagonista seletivo e competitivo do recetor AT1 da angiotensina II (ARA II); converte-se no metabolito ativo E-3174 (responsável pela maior parte do efeito). Biodisponibilidade oral ~33%; pico 1 h (metabolito 3-4 h); semivida ~2 h (metabolito 6-9 h); metabolismo CYP2C9/CYP3A4; excreção renal e biliar; ~98-99% ligação proteica. Reduz a proteinúria e retarda a progressão da doença renal diabética.',
   'Selective competitive antagonist of the angiotensin II AT1 receptor (ARB); converted to the active metabolite E-3174 (responsible for most of the effect). Oral bioavailability ~33%; peak 1 h (metabolite 3-4 h); half-life ~2 h (metabolite 6-9 h); CYP2C9/CYP3A4 metabolism; renal and biliary excretion; ~98-99% protein binding. Reduces proteinuria and slows diabetic kidney disease progression.',
   E'Tratamento da hipertensão arterial em adultos e crianças ≥6 anos.\nNefropatia em doentes adultos com diabetes tipo 2 e hipertensão (redução da progressão da doença renal).\nRedução do risco de acidente vascular cerebral em doentes hipertensos com hipertrofia ventricular esquerda.\nInsuficiência cardíaca (quando os IECA não são tolerados).',
   E'Treatment of hypertension in adults and children ≥6 years.\nNephropathy in adult patients with type 2 diabetes and hypertension (reduction of kidney disease progression).\nReduction of stroke risk in hypertensive patients with left ventricular hypertrophy.\nHeart failure (when ACE inhibitors are not tolerated).',
   E'Tonturas, hipotensão ortostática.\nFadiga, astenia.\nNáuseas, diarreia, dor abdominal.\nHipercaliemia.\nElevação das transaminases (rara).\nTosse (menos frequente do que com IECA).\nRaramente: angioedema, insuficiência renal aguda, anemia.',
   E'Dizziness, orthostatic hypotension.\nFatigue, asthenia.\nNausea, diarrhoea, abdominal pain.\nHyperkalaemia.\nElevated transaminases (rare).\nCough (less frequent than with ACE inhibitors).\nRarely: angioedema, acute renal failure, anaemia.',
   E'Contraindicado na gravidez (2.º e 3.º trimestres — fetotoxicidade) e em hipersensibilidade.\nNÃO usar em associação com alisquireno na diabetes ou insuficiência renal.\nVigiar potássio sérico e creatinina (risco de hipercaliemia, especialmente com suplementos de potássio, diuréticos poupadores e AINEs).\nCorrigir a hipovolemia antes de iniciar (risco de hipotensão).\nPrecaução em estenose bilateral das artérias renais.\nEvitar AINEs (reduzem o efeito e aumentam o risco renal).',
   E'Contraindicated in pregnancy (2nd and 3rd trimesters — fetotoxicity) and in hypersensitivity.\nDo NOT use with aliskiren in diabetes or renal impairment.\nMonitor serum potassium and creatinine (risk of hyperkalaemia, especially with potassium supplements, potassium-sparing diuretics and NSAIDs).\nCorrect hypovolaemia before starting (risk of hypotension).\nCaution in bilateral renal artery stenosis.\nAvoid NSAIDs (reduce the effect and increase renal risk).',
   'DailyMed/FDA — Losartan Potassium Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c15387df-87a4-4784-acb5-7dd550498f8f',
   'DailyMed/FDA — Losartan Potassium Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c15387df-87a4-4784-acb5-7dd550498f8f'),

  ('mesalazina',
   'A mesalazina (ácido 5-aminossalicílico, 5-ASA) é um medicamento usado no tratamento da colite ulcerosa, para induzir e manter a remissão da doença em fases ligeiras a moderadas. Atua diretamente no revestimento do intestino grosso, reduzindo a inflamação. É geralmente bem tolerada.',
   'Mesalamine (5-aminosalicylic acid, 5-ASA) is a medicine used to treat ulcerative colitis, to induce and maintain remission in mild to moderate disease. It acts directly on the lining of the large intestine, reducing inflammation. It is generally well tolerated.',
   'Anti-inflamatório intestinal (5-ASA) com ação tópica no cólon (formulação de libertação diferida com revestimento sensível ao pH). Absorção sistémica total ~21-22% da dose (2,4-4,8 g/dia); pico plasmático 9-12 h; a maior parte do fármaco permanece no lúmen do cólon. Mecanismo: inibição da via da COX e da lipoxigenase, redução da síntese de prostaglandinas/leucotrienos e de citocinas pró-inflamatórias.',
   'Intestinal anti-inflammatory (5-ASA) with topical action in the colon (delayed-release formulation with a pH-sensitive coating). Total systemic absorption ~21-22% of the dose (2.4-4.8 g/day); plasma peak 9-12 h; most of the drug remains in the colonic lumen. Mechanism: inhibition of the COX and lipoxygenase pathways, reduced prostaglandin/leukotriene synthesis and pro-inflammatory cytokines.',
   E'Indução e manutenção da remissão da colite ulcerosa ligeira a moderadamente ativa em adultos.\nTratamento da colite ulcerosa ligeira a moderadamente ativa em doentes pediátricos com ≥24 kg.',
   E'Induction and maintenance of remission in mildly to moderately active ulcerative colitis in adults.\nTreatment of mildly to moderately active ulcerative colitis in paediatric patients weighing at least 24 kg.',
   E'Cefaleia, diarreia, náuseas, dor abdominal.\nFlatulência, dispepsia.\nErupção cutânea, prurido.\nAlterações renais (aumento da creatinina; nefrite intersticial — rara mas grave).\nSíndrome de intolerância aguda (cólicas, diarreia sanguinolenta, febre, cefaleia).\nRaramente: insuficiência hepática, reações cutâneas graves, fotossensibilidade, nefrolitíase, pericardite.',
   E'Headache, diarrhoea, nausea, abdominal pain.\nFlatulence, dyspepsia.\nSkin rash, pruritus.\nRenal changes (elevated creatinine; interstitial nephritis — rare but serious).\nAcute intolerance syndrome (cramps, bloody diarrhoea, fever, headache).\nRarely: hepatic failure, severe skin reactions, photosensitivity, nephrolithiasis, pericarditis.',
   E'Monitorizar a função renal (creatinina) antes e durante o tratamento — suspender se deterioração (nefrite intersticial).\nVigiar o síndrome de intolerância aguda (cólicas, diarreia com sangue, febre) — suspender.\nEvitar em doentes com insuficiência renal grave e em hipersensibilidade a salicilatos.\nNão esmagar nem partir os comprimidos (libertação diferida no cólon).\nIngerir bastante água (risco de nefrolitíase).\nPrecaução em doentes com doença hepática e com estenose/obstrução gastrointestinal.',
   E'Monitor renal function (creatinine) before and during treatment — discontinue if deterioration (interstitial nephritis).\nWatch for the acute intolerance syndrome (cramps, bloody diarrhoea, fever) — discontinue.\nAvoid in severe renal impairment and in salicylate hypersensitivity.\nDo not crush or break the tablets (delayed release in the colon).\nDrink plenty of water (nephrolithiasis risk).\nCaution in patients with liver disease and with GI stenosis/obstruction.',
   'DailyMed/FDA — Mesalamine Delayed-Release Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=14ac4435-903b-41f5-a3c4-8c73de3e4cef',
   'DailyMed/FDA — Mesalamine Delayed-Release Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=14ac4435-903b-41f5-a3c4-8c73de3e4cef')
) AS v(slug, overview_public_pt, overview_public_en, overview_pro_pt, overview_pro_en,
        indications_pt, indications_en, side_effects_pt, side_effects_en,
        precautions_pt, precautions_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

-- =====================================================================
-- Farmacologia (drug_pharmacology, padrão 088/091/092)
-- =====================================================================

INSERT INTO public.drug_pharmacology
  (drug_id, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
   metabolism_pt, metabolism_en, absorption_pt, absorption_en,
   half_life_pt, half_life_en, source_pt, source_en, status)
SELECT d.id, v.pharmacodynamics_pt, v.pharmacodynamics_en, v.mechanism_pt, v.mechanism_en,
       v.metabolism_pt, v.metabolism_en, v.absorption_pt, v.absorption_en,
       v.half_life_pt, v.half_life_en, v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('morfina',
   'Agonista opióide mu de referência: analgesia potente, sedação e euforia, com depressão respiratória dose-dependente (o efeito limitante). O efeito analgésico máximo ocorre ~60 min após a toma oral e a duração do efeito é de 4-6 h. Causa obstipação (redução do peristaltismo), miose, náuseas/vómitos e libertação de histamina (prurido).',
   'Reference mu opioid agonist: potent analgesia, sedation and euphoria, with dose-dependent respiratory depression (the limiting effect). Peak analgesic effect occurs ~60 min after oral dosing and the duration of effect is 4-6 h. It causes constipation (reduced peristalsis), miosis, nausea/vomiting and histamine release (pruritus).',
   'Agonista seletivo dos recetores opióides mu (μ) no SNC e periferia, com menor afinidade para delta e kappa. Ativa as vias inibitórias descendentes da dor e inibe a libertação de neurotransmissores pró-nociceptivos (ex.: substância P) nos aferentes primários, reduzindo a transmissão do estímulo doloroso na medula espinhal.',
   'Selective agonist of mu (μ) opioid receptors in the CNS and periphery, with lower affinity for delta and kappa. It activates descending pain-inhibitory pathways and inhibits the release of pro-nociceptive neurotransmitters (e.g., substance P) from primary afferents, reducing pain signal transmission in the spinal cord.',
   'Conjugação hepática com ácido glucurónico: morfina-3-glucuronídeo (M3G, ~50%, sem atividade analgésica) e morfina-6-glucuronídeo (M6G, ~15%, com atividade analgésica mas baixa passagem da barreira hematoencefálica); <5% desmetilação. Excreção renal dos glucuronídeos; acumulação de M3G/M6G na insuficiência renal.',
   'Hepatic conjugation with glucuronic acid: morphine-3-glucuronide (M3G, ~50%, no analgesic activity) and morphine-6-glucuronide (M6G, ~15%, analgesic activity but poor blood-brain barrier penetration); <5% demethylation. Renal excretion of glucuronides; M3G/M6G accumulation in renal impairment.',
   'Cerca de 2/3 da dose oral é absorvida no trato gastrointestinal; biodisponibilidade oral <40% com grande variabilidade interindividual (extenso metabolismo pré-sistémico). Os alimentos não alteram a extensão da absorção (AUC). Estado de equilíbrio atingido em ~48 h com administração 6/6 h.',
   'About two-thirds of an oral dose is absorbed from the GI tract; oral bioavailability <40% with large inter-individual variability (extensive pre-systemic metabolism). Food does not change the extent of absorption (AUC). Steady state reached within ~48 h with 6-hourly dosing.',
   'Semivida de eliminação ~2 h após administração IV; a duração do efeito analgésico é de 4-6 h (as formulações de libertação prolongada estendem o intervalo de dosagem). Volume de distribuição 1-6 L/kg; ligação proteica 20-35%.',
   'Elimination half-life ~2 h after IV administration; the duration of analgesic effect is 4-6 h (extended-release formulations extend the dosing interval). Volume of distribution 1-6 L/kg; protein binding 20-35%.',
   'DailyMed/FDA — Morphine Sulfate Tablets (SpecGx), secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8b69f67f-30b3-4982-953e-5a4b87ec6ac6',
   'DailyMed/FDA — Morphine Sulfate Tablets label (SpecGx), section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8b69f67f-30b3-4982-953e-5a4b87ec6ac6'),

  ('moxifloxacina',
   'Fluoroquinolona bactericida de largo espetro (incluindo pneumococos multirresistentes, atípicos e anaeróbios), com semivida longa que permite dose única diária. Efeitos adversos de classe: tendinopatia/rotura tendinosa, neuropatia periférica, efeitos no SNC, prolongamento do QT e exacerbação da miastenia gravis.',
   'Broad-spectrum bactericidal fluoroquinolone (including multidrug-resistant pneumococci, atypicals and anaerobes), with a long half-life allowing once-daily dosing. Class adverse effects: tendinopathy/tendon rupture, peripheral neuropathy, CNS effects, QT prolongation and myasthenia gravis exacerbation.',
   'Inibe a replicação do ADN bacteriano bloqueando as topoisomerases II (ADN girase) e IV, impedindo a superenrolamento e a separação dos cromossomas durante a divisão celular — efeito bactericida concentração-dependente.',
   'Inhibits bacterial DNA replication by blocking topoisomerases II (DNA gyrase) and IV, preventing supercoiling and chromosome separation during cell division — concentration-dependent bactericidal effect.',
   'Metabolização hepática fase II predominante (conjugação com glucuronídeo e sulfato); o metabolismo oxidativo CYP é minoritário (~14% por CYP2C9/2D6? minor). Excreção mista: ~20% inalterado na urina e ~25% nas fezes; sem ajuste relevante na insuficiência renal ou hepática ligeira/moderada.',
   'Predominantly hepatic phase II metabolism (glucuronide and sulphate conjugation); oxidative CYP metabolism is minor. Mixed excretion: ~20% unchanged in urine and ~25% in faeces; no relevant adjustment in mild/moderate renal or hepatic impairment.',
   'Bem absorvido no trato gastrointestinal; biodisponibilidade oral absoluta ~90%; pico plasmático ~2 h após a toma; refeições ricas em gordura e iogurte não afetam a absorção. Concentrações plasmáticas proporcionais à dose até 1200 mg.',
   'Well absorbed from the GI tract; absolute oral bioavailability ~90%; plasma peak ~2 h after dosing; high-fat meals and yoghurt do not affect absorption. Plasma concentrations proportional to dose up to 1200 mg.',
   'Semivida de eliminação plasmática ~12±1,3 h (8,2-15,6 h); estado de equilíbrio atingido após ~3 dias com 400 mg 1x/dia.',
   'Plasma elimination half-life ~12±1.3 h (8.2-15.6 h); steady state reached after ~3 days with 400 mg once daily.',
   'DailyMed/FDA — Moxifloxacin Hydrochloride Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1ed191f5-7df5-488c-bb72-91ac0b618d9a',
   'DailyMed/FDA — Moxifloxacin Hydrochloride Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1ed191f5-7df5-488c-bb72-91ac0b618d9a'),

  ('nevirapina',
   'Inibidor não nucleósido da transcriptase reversa (NNRTI) do VIH-1, usado em associação com outros antirretrovirais. Risco grave de hepatotoxicidade (incluindo falência hepática) e de reações cutâneas graves (SJS/NET), sobretudo nas primeiras semanas — exige monitorização apertada.',
   'Non-nucleoside reverse transcriptase inhibitor (NNRTI) of HIV-1, used in combination with other antiretrovirals. Serious risk of hepatotoxicity (including hepatic failure) and severe skin reactions (SJS/TEN), especially in the first weeks — requires close monitoring.',
   'Liga-se diretamente a um sítio alostérico da transcriptase reversa do VIH-1, induzindo uma mudança conformacional que inibe a atividade da polimerase viral (não compete com os nucleósidos). Sem atividade clínica contra o VIH-2.',
   'Binds directly to an allosteric site of HIV-1 reverse transcriptase, inducing a conformational change that inhibits viral polymerase activity (does not compete with nucleosides). No clinical activity against HIV-2.',
   'Metabolismo hepático extenso (CYP3A4 e CYP2B6) com autoindução do CYP3A4 (acelera o próprio metabolismo com doses repetidas); metabolitos hidroxilados excretados na urina (~80%) e fezes (~10%). Interações farmacocinéticas relevantes (indutor CYP3A4).',
   'Extensive hepatic metabolism (CYP3A4 and CYP2B6) with CYP3A4 autoinduction (accelerates its own metabolism with repeated dosing); hydroxylated metabolites excreted in urine (~80%) and faeces (~10%). Relevant pharmacokinetic interactions (CYP3A4 inducer).',
   'Absorção rápida (>90%) após administração oral; biodisponibilidade absoluta 93±9%; pico plasmático 2±0,4 mcg/mL ~4 h após 200 mg; alimentos, antiácidos e didanosina não alteram a absorção. Atinge ~45% da concentração plasmática no LCR; atravessa a placenta e passa para o leite.',
   'Rapid absorption (>90%) after oral administration; absolute bioavailability 93±9%; plasma peak 2±0.4 mcg/mL ~4 h after 200 mg; food, antacids and didanosine do not alter absorption. Reaches ~45% of the plasma concentration in CSF; crosses the placenta and passes into breast milk.',
   'Semivida de eliminação ~45 h após dose única, diminuindo para ~25-30 h com doses múltiplas de 200-400 mg/dia (autoindução enzimática).',
   'Elimination half-life ~45 h after a single dose, decreasing to ~25-30 h with multiple dosing of 200-400 mg/day (enzyme autoinduction).',
   'DailyMed/FDA — Nevirapine Tablets (Mylan), secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c6e93829-7024-48f6-8023-da6ff27dfc0a',
   'DailyMed/FDA — Nevirapine Tablets label (Mylan), section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c6e93829-7024-48f6-8023-da6ff27dfc0a'),

  ('orlistat',
   'Inibidor das lipases gastrointestinais usado na obesidade (IMC ≥30, ou ≥27 com fatores de risco) em associação com dieta hipocalórica; reduz ~30% da absorção da gordura alimentar. Efeitos adversos GI (esteatorreia, flatulência com descarga, urgência fecal) são a manifestação do mecanismo de ação.',
   'Gastrointestinal lipase inhibitor used in obesity (BMI ≥30, or ≥27 with risk factors) together with a reduced-calorie diet; reduces dietary fat absorption by ~30%. GI adverse effects (steatorrhoea, oily spotting, faecal urgency) are the manifestation of the mechanism of action.',
   'Inibe de forma covalente e irreversível as lipases gástrica e pancreática no lúmen do estômago e intestino delgado, impedindo a hidrólise dos triglicéridos da dieta em ácidos gordos livres e monoglicéridos absorvíveis.',
   'Covalently and irreversibly inhibits gastric and pancreatic lipases in the lumen of the stomach and small intestine, preventing hydrolysis of dietary triglycerides into absorbable free fatty acids and monoglycerides.',
   'A fração mínima absorvida é metabolizada em M1 (produto da hidrólise do anel β-lactona) e M3 (metabolito sequencial), ambos com atividade inibidora das lipases 1000-2500x menor que o orlistat — farmacologicamente inconsequentes. Sem acumulação.',
   'The minimal absorbed fraction is metabolised to M1 (hydrolysis product of the β-lactone ring) and M3 (sequential metabolite), both with lipase-inhibitory activity 1000-2500x lower than orlistat — pharmacologically inconsequential. No accumulation.',
   'Absorção sistémica mínima: concentrações plasmáticas de orlistat intacto <10 ng/mL (perto do limite de deteção); pico de radioatividade plasmática ~8 h após 360 mg de 14C-orlistat. ~97% da dose excretada nas fezes (83% como fármaco inalterado); excreção renal <2%.',
   'Minimal systemic absorption: plasma concentrations of intact orlistat <10 ng/mL (near the limit of detection); plasma radioactivity peak ~8 h after 360 mg of 14C-orlistat. ~97% of the dose excreted in faeces (83% as unchanged drug); renal excretion <2%.',
   'Ação local no lúmen GI (sem semivida sistémica relevante); metabolitos plasmáticos M1 t½ ~3 h e M3 ~13,5 h; eliminação fecal + urinária completa em 3-5 dias.',
   'Local action in the GI lumen (no relevant systemic half-life); plasma metabolites M1 t½ ~3 h and M3 ~13.5 h; complete faecal + urinary elimination within 3-5 days.',
   'DailyMed/FDA — Xenical (orlistat) Capsules, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6240792b-9224-2d10-e053-2a91aa0a2c3e',
   'DailyMed/FDA — Xenical (orlistat) Capsules label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6240792b-9224-2d10-e053-2a91aa0a2c3e'),

  ('sulfassalazina',
   'Anti-inflamatório intestinal (pró-fármaco) para a colite ulcerosa: a ação terapêutica reside sobretudo no ácido 5-aminossalicílico (5-ASA) libertado no cólon. Reações adversas frequentes (anorexia, cefaleia, náuseas, oligospermia reversível) relacionadas com a sulfapiridina sistémica.',
   'Intestinal anti-inflammatory (prodrug) for ulcerative colitis: the therapeutic action resides mainly in the 5-aminosalicylic acid (5-ASA) released in the colon. Frequent adverse reactions (anorexia, headache, nausea, reversible oligospermia) related to systemic sulfapyridine.',
   'A sulfassalazina é clivada pela flora bacteriana do cólon em sulfapiridina (transportadora) e 5-ASA (componente ativo). O 5-ASA inibe localmente a via da COX e da lipoxigenase, reduzindo prostaglandinas, leucotrienos e a quimiotaxia/degranulação dos neutrófilos na mucosa.',
   'Sulfasalazine is cleaved by the colonic bacterial flora into sulfapyridine (carrier) and 5-ASA (active moiety). 5-ASA locally inhibits the COX and lipoxygenase pathways, reducing prostaglandins, leukotrienes and neutrophil chemotaxis/degranulation in the mucosa.',
   'A SSZ não clivada é parcialmente metabolizada (acetilação); a sulfapiridina é extensamente metabolizada no fígado (acetilação, hidroxilação com conjugação) — o fenótipo de acetilação influencia a toxicidade; o 5-ASA é N-acetilado no epitélio intestinal e no fígado. Excreção renal dos metabolitos.',
   'Uncleaved SSZ is partially metabolised (acetylation); sulfapyridine is extensively metabolised in the liver (acetylation, hydroxylation with conjugation) — the acetylation phenotype influences toxicity; 5-ASA is N-acetylated in the intestinal epithelium and liver. Renal excretion of metabolites.',
   '<15% da SSZ absorvida como fármaco-mãe (pico sérico ~6 µg/mL às 6 h, entre 3-12 h); a sulfapiridina é bem absorvida no cólon (bio ~60%); o 5-ASA é pouco absorvido (bio 10-30%). Picos de sulfapiridina e 5-ASA ~10 h após a toma (trânsito até ao cólon).',
   '<15% of SSZ absorbed as the parent drug (serum peak ~6 µg/mL at 6 h, 3-12 h); sulfapyridine is well absorbed from the colon (bioavailability ~60%); 5-ASA is poorly absorbed (bioavailability 10-30%). Sulfapyridine and 5-ASA peaks ~10 h after dosing (transit to the colon).',
   'Semivida da sulfassalazina IV ~7,4 h; semivida da sulfapiridina ~10 h (dependente da acetilação); excreção renal da sulfapiridina e dos metabolitos, com eliminação fecal do 5-ASA não absorvido.',
   'Half-life of IV sulfasalazine ~7.4 h; half-life of sulfapyridine ~10 h (acetylation dependent); renal excretion of sulfapyridine and metabolites, with faecal elimination of unabsorbed 5-ASA.',
   'DailyMed/FDA — Azulfidine (sulfasalazine) Tablets, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ddbe69f3-bd55-45f3-a64f-f60226c744c4',
   'DailyMed/FDA — Azulfidine (sulfasalazine) Tablets label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ddbe69f3-bd55-45f3-a64f-f60226c744c4'),

  ('tobramicina',
   'Aminoglicosídeo bactericida ativo contra Gram-negativos (incluindo Pseudomonas aeruginosa), usado em infeções hospitalares graves (sépsis, pneumonia, infeções urinárias complicadas, meningite). Nefrotoxicidade e ototoxicidade (vestibular e auditiva) são os efeitos limitantes — exige monitorização de níveis e da função renal.',
   'Bactericidal aminoglycoside active against Gram-negatives (including Pseudomonas aeruginosa), used in severe hospital infections (sepsis, pneumonia, complicated urinary tract infections, meningitis). Nephrotoxicity and ototoxicity (vestibular and auditory) are the limiting effects — requires level and renal function monitoring.',
   'Aminoglicosídeo bactericida que se liga à subunidade 30S do ribossoma bacteriano, causando erro de leitura do ARNm e produção de proteínas defeituosas, com perturbação da membrana citoplasmática. Efeito pós-antibiótico prolongado; atividade concentração-dependente.',
   'Bactericidal aminoglycoside that binds the bacterial 30S ribosomal subunit, causing mRNA misreading and defective protein synthesis, with disruption of the cytoplasmic membrane. Prolonged post-antibiotic effect; concentration-dependent activity.',
   'Praticamente sem metabolização; eliminação quase exclusiva por filtração glomerular (até 84% da dose na urina em 8 h e 93% em 24 h em função renal normal; clearance renal semelhante à creatinina). Acumulação na insuficiência renal.',
   'Virtually no metabolism; elimination almost exclusively by glomerular filtration (up to 84% of the dose in urine within 8 h and 93% within 24 h with normal renal function; renal clearance similar to creatinine). Accumulation in renal impairment.',
   'Bem absorvido por via intramuscular (pico 30-90 min; ~4 mcg/mL após 1 mg/kg); por perfusão IV os níveis são semelhantes aos IM; praticamente não absorvido pelo trato gastrointestinal (não usar oral para efeito sistémico). Sem ligação proteica relevante.',
   'Well absorbed intramuscularly (peak 30-90 min; ~4 mcg/mL after 1 mg/kg); IV infusion produces levels similar to IM; virtually unabsorbed from the GI tract (not used orally for systemic effect). No relevant protein binding.',
   'Semivida sérica ~2 h em indivíduos com função renal normal; relação inversa entre semivida e clearance de creatinina (ajustar o intervalo de doses na insuficiência renal).',
   'Serum half-life ~2 h in individuals with normal renal function; inverse relationship between half-life and creatinine clearance (extend the dosing interval in renal impairment).',
   'DailyMed/FDA — Tobramycin for Injection, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c4751a4f-c9c1-60c5-e053-2995a90aeba9',
   'DailyMed/FDA — Tobramycin for Injection label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c4751a4f-c9c1-60c5-e053-2995a90aeba9'),

  ('acetazolamida',
   'Inibidor da anidrase carbónica com indicações variadas: glaucoma, epilepsia (crises de ausência), edema (insuficiência cardíaca, induzido por fármacos) e prevenção/alívio do mal de montanha. Diurético fraco que alcaliniza a urina e pode causar acidose metabólica.',
   'Carbonic anhydrase inhibitor with varied indications: glaucoma, epilepsy (absence seizures), oedema (heart failure, drug-induced) and prevention/relief of acute mountain sickness. A weak diuretic that alkalinises the urine and can cause metabolic acidosis.',
   'Inibe a anidrase carbónica (a enzima que catalisa a hidratação do CO2 e a desidratação do ácido carbónico). No olho, reduz a secreção de humor aquoso e a pressão intraocular; no rim, causa perda renal de HCO3- com eliminação de sódio, água e potássio (alcalinização da urina); no SNC, retarda a descarga neuronal paroxística.',
   'Inhibits carbonic anhydrase (the enzyme catalysing CO2 hydration and carbonic acid dehydration). In the eye, it reduces aqueous humour secretion and intraocular pressure; in the kidney, it causes renal HCO3- loss with sodium, water and potassium elimination (urinary alkalinisation); in the CNS, it retards abnormal paroxysmal neuronal discharge.',
   'Metabolização mínima; eliminação predominantemente renal inalterada (secreção tubular ativa). A alcalinização da urina reduz a reabsorção tubular do fármaco.',
   'Minimal metabolism; predominantly renal elimination unchanged (active tubular secretion). Urinary alkalinisation reduces tubular reabsorption of the drug.',
   'Bem absorvido por via oral; a inibição da anidrase carbónica nos eritrócitos e tecidos ocorre em minutos após a toma. Utilizado em doses de 250 mg 8-12/8-12 h (ou 500 mg de libertação prolongada 1x/dia) na profilaxia do mal de montanha.',
   'Well absorbed orally; carbonic anhydrase inhibition in erythrocytes and tissues occurs within minutes of dosing. Used at 250 mg every 8-12 h (or 500 mg extended-release once daily) for acute mountain sickness prophylaxis.',
   'Semivida plasmática ~10-15 h; concentra-se nos eritrócitos (ligação à anidrase carbónica), com efeito que se prolonga para além da semivida plasmática.',
   'Plasma half-life ~10-15 h; concentrates in erythrocytes (carbonic anhydrase binding), with an effect extending beyond the plasma half-life.',
   'DailyMed/FDA — Acetazolamide Tablets (Strides Pharma), secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4813b9dd-5f58-44bb-ad64-cdb331828080',
   'DailyMed/FDA — Acetazolamide Tablets label (Strides Pharma), section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4813b9dd-5f58-44bb-ad64-cdb331828080'),

  ('acido_tranexamico',
   'Antifibrinolítico (análogo sintético da lisina) usado no tratamento da hemorragia menstrual intensa em mulheres em idade reprodutiva; reduz a perda de sangue ao inibir a degradação do coágulo de fibrina.',
   'Antifibrinolytic (synthetic lysine analogue) used to treat heavy menstrual bleeding in women of reproductive potential; reduces blood loss by inhibiting fibrin clot breakdown.',
   'Inibe competitivamente a ativação do plasminogénio em plasmina (ligando-se aos locais de ligação da lisina), bloqueando a fibrinólise e estabilizando o coágulo de fibrina; também inibe diretamente a plasmina em doses altas.',
   'Competitively inhibits the activation of plasminogen to plasmin (binding to the lysine-binding sites), blocking fibrinolysis and stabilising the fibrin clot; also directly inhibits plasmin at high doses.',
   'Metabolização mínima; excreção predominantemente renal inalterada (~95%) por filtração glomerular e secreção tubular — acumula na insuficiência renal (ajustar a dose).',
   'Minimal metabolism; predominantly renal excretion unchanged (~95%) by glomerular filtration and tubular secretion — accumulates in renal impairment (adjust the dose).',
   'Biodisponibilidade oral ~45% (mulheres 18-49 anos); pico plasmático ~3 h (Tmax 2,5 h, 1-5 h); concentração máxima 13,8 mcg/mL após 1300 mg; os alimentos aumentam ligeiramente Cmax e AUC (+7%/+16%). Ligação proteica ~3%.',
   'Oral bioavailability ~45% (women aged 18-49); plasma peak ~3 h (Tmax 2.5 h, 1-5 h); Cmax 13.8 mcg/mL after 1300 mg; food slightly increases Cmax and AUC (+7%/+16%). Protein binding ~3%.',
   'Semivida terminal ~11 h (t1/2 11,08 h após dose única); semivida beta ~2 h; volume de distribuição inicial 0,18 L/kg.',
   'Terminal half-life ~11 h (t1/2 11.08 h after a single dose); beta half-life ~2 h; initial volume of distribution 0.18 L/kg.',
   'DailyMed/FDA — Tranexamic Acid Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4877eacd-fda7-4708-93a5-81052c1d2e14',
   'DailyMed/FDA — Tranexamic Acid Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4877eacd-fda7-4708-93a5-81052c1d2e14'),

  ('amoxicilina',
   'Penicilina semissintética de largo espetro (aminopenicilina, bactericida), estável ao ácido gástrico e bem absorvida por via oral; ativa contra estreptococos, pneumococos, enterococos, Listeria, Haemophilus, E. coli, Proteus, Salmonella e H. pylori (em associação). Sensível a beta-lactamases.',
   'Broad-spectrum semisynthetic penicillin (aminopenicillin, bactericidal), stable to gastric acid and well absorbed orally; active against streptococci, pneumococci, enterococci, Listeria, Haemophilus, E. coli, Proteus, Salmonella and H. pylori (in combination). Susceptible to beta-lactamases.',
   'Inibe a síntese da parede celular bacteriana ligando-se às proteínas de ligação às penicilinas (PBP), bloqueando a transpeptidação do peptidoglicano — efeito bactericida dependente do tempo.',
   'Inhibits bacterial cell wall synthesis by binding to penicillin-binding proteins (PBPs), blocking peptidoglycan transpeptidation — time-dependent bactericidal effect.',
   'Metabolização parcial; ~60-80% excretado inalterado por via renal (filtração glomerular e secreção tubular); probenecida reduz a excreção. Ajustar na insuficiência renal.',
   'Partial metabolism; ~60-80% excreted unchanged renally (glomerular filtration and tubular secretion); probenecid reduces excretion. Adjust in renal impairment.',
   'Estável ao ácido gástrico, rapidamente absorvido: picos 1-2 h após a toma (3,5-7,5 mcg/mL para 250-500 mg); ~20% ligação proteica; difunde bem para a maioria dos tecidos e fluidos (exceto SNC com meninges não inflamadas).',
   'Stable to gastric acid, rapidly absorbed: peaks 1-2 h after dosing (3.5-7.5 mcg/mL for 250-500 mg); ~20% protein binding; diffuses well into most tissues and fluids (except CNS with uninflamed meninges).',
   'Semivida de eliminação ~1 h em função renal normal; a semivida prolonga-se na insuficiência renal (intervalo de doses alargado).',
   'Elimination half-life ~1 h with normal renal function; the half-life is prolonged in renal impairment (extended dosing interval).',
   'DailyMed/FDA — Amoxicillin Capsules, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb4149a-0714-4a85-b9e8-2379a8e6a302',
   'DailyMed/FDA — Amoxicillin Capsules label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=afb4149a-0714-4a85-b9e8-2379a8e6a302'),

  ('amoxicilina-clavulanato',
   'Associação de amoxicilina (aminopenicilina bactericida) com ácido clavulânico, inibidor suicida das beta-lactamases que protege a amoxicilina da inativação — alarga o espetro a estafilococos produtores, Haemophilus, Klebsiella e E. coli. Risco de hepatotoxicidade colestática (mais frequente em idosos, homens e uso >14 dias).',
   'Combination of amoxicillin (bactericidal aminopenicillin) with clavulanic acid, a suicide inhibitor of beta-lactamases that protects amoxicillin from inactivation — extending the spectrum to penicillinase-producing staphylococci, Haemophilus, Klebsiella and E. coli. Risk of cholestatic hepatotoxicity (more frequent in the elderly, men and use >14 days).',
   'A amoxicilina inibe a síntese da parede celular (ligação às PBP); o clavulanato liga-se covalentemente às beta-lactamases (incluindo as plasmidiais de S. aureus, Haemophilus, Klebsiella, E. coli), inativando-as e restaurando a atividade da amoxicilina.',
   'Amoxicillin inhibits cell wall synthesis (PBP binding); clavulanate binds covalently to beta-lactamases (including plasmid-mediated enzymes of S. aureus, Haemophilus, Klebsiella, E. coli), inactivating them and restoring amoxicillin activity.',
   'A amoxicilina é parcialmente metabolizada e excretada inalterada por via renal; o clavulanato é extensamente metabolizado e excretado na urina e nas fezes. Ajustar na insuficiência renal (ambos os componentes acumulam).',
   'Amoxicillin is partially metabolised and excreted unchanged renally; clavulanate is extensively metabolised and excreted in urine and faeces. Adjust in renal impairment (both components accumulate).',
   'Picos ~1,5 h após a toma com refeição ligeira (amoxicilina 11,6 mcg/mL; clavulanato 2,2 mcg/mL para 875/125 mg); absorção oral rápida e completa; pode ser tomado com ou sem alimentos (menos desconforto GI com alimentos).',
   'Peaks ~1.5 h after dosing with a light meal (amoxicillin 11.6 mcg/mL; clavulanate 2.2 mcg/mL for 875/125 mg); rapid, complete oral absorption; can be taken with or without food (less GI discomfort with food).',
   'Semivida ~1,3 h (amoxicilina) e ~1 h (clavulanato) em adultos com função renal normal.',
   'Half-life ~1.3 h (amoxicillin) and ~1 h (clavulanate) in adults with normal renal function.',
   'DailyMed/FDA — Amoxicillin and Clavulanate Potassium Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7526a33a-18d6-36ca-e053-2a91aa0ab9f9',
   'DailyMed/FDA — Amoxicillin and Clavulanate Potassium Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7526a33a-18d6-36ca-e053-2a91aa0ab9f9'),

  ('atovaquona-proguanil',
   'Antimalárico de associação (atovaquona + proguanil) com ação sinérgica contra P. falciparum, incluindo estirpes resistentes à cloroquina; usado na profilaxia e no tratamento da malária não complicada.',
   'Combination antimalarial (atovaquone + proguanil) with synergistic action against P. falciparum, including chloroquine-resistant strains; used for prophylaxis and treatment of uncomplicated malaria.',
   'A atovaquona é um análogo da ubiquinona que inibe seletivamente o complexo III da cadeia de transporte de eletrões mitocondrial do plasmódio; o proguanil (pró-fármaco → cicloguanil via CYP2C19) inibe a di-hidrofolato redutase do parasita. A combinação é sinérgica (bloqueio sequencial).',
   'Atovaquone is a ubiquinone analogue that selectively inhibits complex III of the plasmodial mitochondrial electron transport chain; proguanil (prodrug → cycloguanil via CYP2C19) inhibits the parasite dihydrofolate reductase. The combination is synergistic (sequential blockade).',
   'Atovaquona: metabolização limitada (metabolito específico não identificado), excreção fecal >94% inalterada em 21 dias e <0,6% urinária. Proguanil: metabolizado em cicloguanil (CYP2C19) e 4-clorofenilbiguanida; 40-60% excretado por via renal (ajustar na insuficiência renal).',
   'Atovaquone: limited metabolism (no specific metabolite identified), faecal excretion >94% unchanged over 21 days and <0.6% urinary. Proguanil: metabolised to cycloguanil (CYP2C19) and 4-chlorophenylbiguanide; 40-60% excreted renally (adjust in renal impairment).',
   'A atovaquona é lipofílica com baixa solubilidade aquosa — absorção altamente variável; com alimentos (gordura) o AUC aumenta 2-3x e a Cmax 5x; biodisponibilidade absoluta com alimentos 23%; ligação proteica >99% (atovaquona) e 75% (proguanil).',
   'Atovaquone is lipophilic with low aqueous solubility — highly variable absorption; with food (fat) AUC increases 2-3x and Cmax 5x; absolute bioavailability with food 23%; protein binding >99% (atovaquone) and 75% (proguanil).',
   'Semivida de eliminação ~2-3 dias (atovaquona) e 12-21 h (proguanil, maior em metabolizadores lentos); volume de distribuição ~8,8 L/kg (atovaquona).',
   'Elimination half-life ~2-3 days (atovaquone) and 12-21 h (proguanil, longer in slow metabolisers); volume of distribution ~8.8 L/kg (atovaquone).',
   'DailyMed/FDA — Malarone (atovaquone and proguanil hydrochloride) Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc22e8d8-3bfb-4f70-a599-dd81262a4887',
   'DailyMed/FDA — Malarone (atovaquone and proguanil hydrochloride) Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=fc22e8d8-3bfb-4f70-a599-dd81262a4887'),

  ('budesonida',
   'Corticosteroide inalado de alta afinidade para o recetor dos glucocorticóides, com potente ação anti-inflamatória local nas vias aéreas e baixa biodisponibilidade sistémica — indicado na manutenção da asma em crianças (12 meses-8 anos).',
   'Inhaled corticosteroid with high affinity for the glucocorticoid receptor, with potent local anti-inflammatory action in the airways and low systemic bioavailability — indicated for asthma maintenance in children (12 months-8 years).',
   'Liga-se ao recetor dos glucocorticóides no citoplasma, modulando a transcrição genética: aumenta a síntese de proteínas anti-inflamatórias (lipocortina-1, IκB) e inibe a de citocinas pró-inflamatórias, quimiocinas e enzimas inflamatórias (COX-2, iNOS) — redução da inflamação das vias aéreas e da hiperreatividade brônquica.',
   'Binds the cytoplasmic glucocorticoid receptor, modulating gene transcription: increases synthesis of anti-inflammatory proteins (lipocortin-1, IκB) and inhibits pro-inflammatory cytokines, chemokines and inflammatory enzymes (COX-2, iNOS) — reduced airway inflammation and bronchial hyperresponsiveness.',
   'Metabolização rápida e extensa no fígado por CYP3A4 em 16α-hidroxiprednisolona e 6β-hidroxibudesonida (atividade <1% do composto-mãe); clearance sistémico elevado (~0,5 L/min em crianças); excreção urinária (~60% IV) e fecal sob a forma de metabolitos; sem budesonida inalterada na urina.',
   'Rapid, extensive hepatic metabolism by CYP3A4 to 16α-hydroxyprednisolone and 6β-hydroxybudesonide (activity <1% of the parent); high systemic clearance (~0.5 L/min in children); urinary (~60% IV) and faecal excretion as metabolites; no unchanged budesonide in urine.',
   'Após nebulização, a biodisponibilidade sistémica total (pulmonar + oral) é ~6% da dose; pico plasmático ~20 min após 1 mg nebulizado (2,6 nmol/L); ligação proteica 85-90%; volume de distribuição 3 L/kg.',
   'After nebulisation, total systemic bioavailability (lung + oral) is ~6% of the dose; plasma peak ~20 min after a 1 mg nebulised dose (2.6 nmol/L); protein binding 85-90%; volume of distribution 3 L/kg.',
   'Semivida terminal ~2,3 h após nebulização em crianças com asma; clearance sistémico ~0,5 L/min (≈50% superior ao dos adultos).',
   'Terminal half-life ~2.3 h after nebulisation in children with asthma; systemic clearance ~0.5 L/min (≈50% higher than in adults).',
   'DailyMed/FDA — Budesonide Inhalation Suspension, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c52c5382-1400-44b9-95be-a30e1cf706da',
   'DailyMed/FDA — Budesonide Inhalation Suspension label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c52c5382-1400-44b9-95be-a30e1cf706da'),

  ('ceftazidima',
   'Cefalosporina de 3.ª geração com atividade antipseudomonas de referência; bactericida dependente do tempo, com excreção renal — exige ajuste de dose na insuficiência renal.',
   'Third-generation cephalosporin with reference antipseudomonal activity; time-dependent bactericidal, with renal excretion — requires dose adjustment in renal impairment.',
   'Inibe a síntese da parede celular bacteriana por ligação às PBP (incluindo PBP3 de Pseudomonas aeruginosa), bloqueando a transpeptidação do peptidoglicano — lise bacteriana.',
   'Inhibits bacterial cell wall synthesis by binding to PBPs (including PBP3 of Pseudomonas aeruginosa), blocking peptidoglycan transpeptidation — bacterial lysis.',
   'Praticamente sem metabolização; 80-90% excretado inalterado por via renal (filtração glomerular e secreção tubular) em 24 h; a disfunção hepática não afeta a farmacocinética.',
   'Virtually no metabolism; 80-90% excreted unchanged renally (glomerular filtration and tubular secretion) within 24 h; hepatic dysfunction does not affect the pharmacokinetics.',
   'Administração IV/IM (sem absorção oral); picos séricos 45 e 90 mcg/mL após 500 mg e 1 g IV em 5 min; ~10% ligação proteica; concentrações proporcionais à dose; penetra bem nos tecidos, incluindo LCR com meninges inflamadas.',
   'IV/IM administration (no oral absorption); serum peaks 45 and 90 mcg/mL after 500 mg and 1 g IV over 5 min; ~10% protein binding; dose-proportional concentrations; penetrates tissues well, including CSF with inflamed meninges.',
   'Semivida ~1,9 h (IV) e ~2 h (IM); sem acumulação em função renal normal com 1-2 g 8/8 h; a semivida prolonga-se na insuficiência renal.',
   'Half-life ~1.9 h (IV) and ~2 h (IM); no accumulation with normal renal function at 1-2 g 8-hourly; the half-life is prolonged in renal impairment.',
   'DailyMed/FDA — Tazicef (ceftazidime for injection), secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b73979c-c95a-4433-0a9d-f9cea3cb557f',
   'DailyMed/FDA — Tazicef (ceftazidime for injection) label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9b73979c-c95a-4433-0a9d-f9cea3cb557f'),

  ('ceftriaxona',
   'Cefalosporina de 3.ª geração de largo espetro com semivida longa (dose única diária), penetração no LCR e eliminação dupla (renal + biliar); atenção à precipitação com cálcio em recém-nascidos.',
   'Broad-spectrum third-generation cephalosporin with a long half-life (once-daily dosing), CSF penetration and dual elimination (renal + biliary); attention to calcium precipitation in neonates.',
   'Inibe a síntese da parede celular bacteriana por ligação às PBP (transpeptidação do peptidoglicano); bactericida dependente do tempo com atividade contra Gram-positivos e Gram-negativos, incluindo meningococos, gonococos e Treponema.',
   'Inhibits bacterial cell wall synthesis by binding to PBPs (peptidoglycan transpeptidation); time-dependent bactericidal with activity against Gram-positives and Gram-negatives, including meningococci, gonococci and Treponema.',
   'Não é metabolizado de forma significativa; eliminação dupla: ~33-67% inalterado por via renal e o restante por via biliar (sem ajuste na insuficiência renal isolada, exceto se combinada com hepática grave).',
   'Not significantly metabolised; dual elimination: ~33-67% unchanged renally and the rest biliarily (no adjustment for isolated renal impairment, except when combined with severe hepatic impairment).',
   'Administração IV/IM (sem absorção oral); ligação proteica reversível e concentração-dependente (95% a <25 mcg/mL → 85% a 300 mcg/mL); volume de distribuição 5,78-13,5 L; atravessa a placenta e penetra bem no LCR com meninges inflamadas.',
   'IV/IM administration (no oral absorption); reversible, concentration-dependent protein binding (95% at <25 mcg/mL → 85% at 300 mcg/mL); volume of distribution 5.78-13.5 L; crosses the placenta and penetrates well into CSF with inflamed meninges.',
   'Semivida de eliminação 5,8-8,7 h em adultos (0,15-3 g); em crianças com meningite 4,3-4,6 h; clearance plasmático 0,58-1,45 L/h; renal 0,32-0,73 L/h.',
   'Elimination half-life 5.8-8.7 h in adults (0.15-3 g); 4.3-4.6 h in children with meningitis; plasma clearance 0.58-1.45 L/h; renal 0.32-0.73 L/h.',
   'DailyMed/FDA — Ceftriaxone Injection (premixed Galaxy containers), secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c2d3f-5038-41a1-a2fe-4dcd048dbac1',
   'DailyMed/FDA — Ceftriaxone Injection (premixed Galaxy containers) label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c2d3f-5038-41a1-a2fe-4dcd048dbac1'),

  ('cetirizina',
   'Anti-histamínico H1 de 2.ª geração (metabolito ativo da hidroxizina) com mínima penetração no SNC — menos sedação e efeitos anticolinérgicos do que os anti-H1 de 1.ª geração; início de ação ~1 h e duração ≥24 h com dose única diária.',
   'Second-generation H1 antihistamine (active metabolite of hydroxyzine) with minimal CNS penetration — less sedation and anticholinergic effects than first-generation H1 antihistamines; onset ~1 h and duration ≥24 h with once-daily dosing.',
   'Antagonista seletivo e periférico dos recetores H1 da histamina, bloqueando a resposta alérgica (vasodilatação, aumento da permeabilidade capilar, prurido, espirros) sem antagonismo significativo de recetores colinérgicos ou serotoninérgicos.',
   'Selective peripheral antagonist of histamine H1 receptors, blocking the allergic response (vasodilation, increased capillary permeability, pruritus, sneezing) without significant cholinergic or serotonergic antagonism.',
   'Metabolização hepática mínima (a cetirizina é em grande parte excretada inalterada); sem metabolito ativo adicional relevante; excreção renal predominante (~60-70% inalterado) e fecal.',
   'Minimal hepatic metabolism (cetirizine is largely excreted unchanged); no relevant additional active metabolite; predominantly renal excretion (~60-70% unchanged) and faecal.',
   'Bem absorvido por via oral; pico plasmático ~1 h; ~93% ligação proteica; a absorção não é afetada pelos alimentos de forma relevante; Tmax ~0,5-1 h.',
   'Well absorbed orally; plasma peak ~1 h; ~93% protein binding; absorption is not relevantly affected by food; Tmax ~0.5-1 h.',
   'Semivida de eliminação ~8,3 h (146 voluntários saudáveis); prolonga-se na insuficiência renal e nos idosos (ajustar a dose); semivida ~6 h em crianças 6-12 anos.',
   'Elimination half-life ~8.3 h (146 healthy volunteers); prolonged in renal impairment and the elderly (adjust the dose); half-life ~6 h in children 6-12 years.',
   'DailyMed/FDA — Cetirizine Hydrochloride OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b9ac489a-80ed-4077-b68e-d03df1b892a6 + PubMed PMID 8477559',
   'DailyMed/FDA — Cetirizine Hydrochloride OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b9ac489a-80ed-4077-b68e-d03df1b892a6 + PubMed PMID 8477559'),

  ('cianocobalamina',
   'Vitamina B12 (cobalamina) essencial para a hematopoiese, síntese de nucleoproteínas e mielina; a forma ciano é a mais usada, com atividade hematopoiética idêntica à hidroxicobalamina. A via parenteral é rápida e fiável; a absorção oral depende do fator intrínseco.',
   'Vitamin B12 (cobalamin) essential for haematopoiesis, nucleoprotein and myelin synthesis; the cyano form is the most widely used, with haematopoietic activity identical to hydroxocobalamin. The parenteral route is rapid and reliable; oral absorption depends on intrinsic factor.',
   'Cofator essencial para a metionina sintase (conversão de homocisteína em metionina, com regeneração do tetrahidrofolato) e para a metilmalonil-CoA mutase (catabolismo dos ácidos gordos de cadeia ímpar) — défice causa anemia megaloblástica e degeneração subaguda combinada da medula espinhal.',
   'Essential cofactor for methionine synthase (conversion of homocysteine to methionine, with tetrahydrofolate regeneration) and for methylmalonyl-CoA mutase (odd-chain fatty acid catabolism) — deficiency causes megaloblastic anaemia and subacute combined degeneration of the spinal cord.',
   'Na forma livre (não ligada), é excretada rapidamente na urina: 50-98% de uma dose injetada de 100-1000 mcg aparece na urina em 48 h (a maior parte nas primeiras 8 h); a maior parte da dose retida fica armazenada no fígado.',
   'In the free (unbound) form, it is rapidly excreted in urine: 50-98% of an injected 100-1000 mcg dose appears in urine within 48 h (most within the first 8 h); most of the retained dose is stored in the liver.',
   'Absorção oral dependente do fator intrínseco e do cálcio no íleo terminal (via recetor cubilina); ~1% é absorvido por difusão simples (apenas relevante com doses muito altas); por via IM/SC a absorção é rápida (pico plasmático <1 h); o transporte plasmático faz-se pelas transcobalaminas I e II.',
   'Oral absorption depends on intrinsic factor and calcium in the terminal ileum (cubilin receptor pathway); ~1% is absorbed by simple diffusion (only relevant with very high doses); IM/SC absorption is rapid (plasma peak <1 h); plasma transport via transcobalamins I and II.',
   'A cobalamina livre tem uma semivida plasmática curta até captação hepática (a vitamina ligada à transcobalamina II tem semivida de 60-90 min); a reserva hepática prolonga o efeito clínico durante meses; a semivida da vitamina armazenada é de ~6 dias até utilização tecidular.',
   'Free cobalamin has a short plasma half-life until hepatic uptake (transcobalamin II-bound vitamin has a half-life of 60-90 min); the hepatic reserve extends the clinical effect for months; the half-life of stored vitamin is ~6 days until tissue utilisation.',
   'DailyMed/FDA — Cyanocobalamin Injection, USP (secção CLINICAL PHARMACOLOGY): https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=071f7c95-7243-4014-b336-db8962ac0f75 + revisão PMC9822362',
   'DailyMed/FDA — Cyanocobalamin Injection, USP (section CLINICAL PHARMACOLOGY): https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=071f7c95-7243-4014-b336-db8962ac0f75 + review PMC9822362'),

  ('daptomicina',
   'Lipopéptido cíclico bactericida dependente de cálcio, ativo contra Gram-positivos (incluindo MRSA e VRE); semivida ~8 h permite dose única diária; inativado pelo surfactante pulmonar (não usar na pneumonia).',
   'Calcium-dependent cyclic lipopeptide, bactericidal, active against Gram-positives (including MRSA and VRE); ~8 h half-life allows once-daily dosing; inactivated by pulmonary surfactant (do not use in pneumonia).',
   'Insere-se na membrana citoplasmática bacteriana de forma dependente do cálcio, causando despolarização rápida e maciça com perda do potencial de membrana e morte celular (sem lise); não atravessa a membrana externa dos Gram-negativos.',
   'Inserts into the bacterial cytoplasmic membrane in a calcium-dependent manner, causing rapid, massive depolarisation with loss of membrane potential and cell death (without lysis); does not cross the outer membrane of Gram-negatives.',
   'Metabolização limitada (pequena fração); excreção renal predominante (~78% da dose recuperada na urina, maioritariamente inalterado) — ajustar a dose na insuficiência renal (CrCl <30 mL/min: 6 mg/kg 48/48 h).',
   'Limited metabolism (small fraction); predominantly renal excretion (~78% of the dose recovered in urine, mostly unchanged) — adjust the dose in renal impairment (CrCl <30 mL/min: 6 mg/kg every 48 h).',
   'Administração IV (infusão de 30 min ou 2 min); farmacocinética linear e independente do tempo (4-12 mg/kg); volume de distribuição no estado de equilíbrio ~0,1 L/kg (baixo — permanece sobretudo no plasma); Cmax 57,8 mcg/mL após 4 mg/kg.',
   'IV administration (30-min or 2-min infusion); linear, time-independent pharmacokinetics (4-12 mg/kg); steady-state volume of distribution ~0.1 L/kg (low — remains mostly in plasma); Cmax 57.8 mcg/mL after 4 mg/kg.',
   'Semivida de eliminação ~8 h (7,7-8,3 h em 4-12 mg/kg); estado de equilíbrio atingido ao 3.º dia de dose diária; clearance total 8-9 mL/h/kg.',
   'Elimination half-life ~8 h (7.7-8.3 h at 4-12 mg/kg); steady state reached by the third daily dose; total clearance 8-9 mL/h/kg.',
   'DailyMed/FDA — Daptomycin for Injection, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f4ad8613-f25e-4b82-9621-cc5ff9525d3e',
   'DailyMed/FDA — Daptomycin for Injection label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f4ad8613-f25e-4b82-9621-cc5ff9525d3e'),

  ('donepezilo',
   'Inibidor reversível e seletivo da acetilcolinesterase para o tratamento sintomático da doença de Alzheimer (ligeira, moderada e grave); semivida longa (~70 h) com dose única diária.',
   'Reversible, selective acetylcholinesterase inhibitor for the symptomatic treatment of Alzheimer disease (mild, moderate and severe); long half-life (~70 h) with once-daily dosing.',
   'Inibe de forma reversível a acetilcolinesterase (predominantemente central), aumentando a concentração de acetilcolina na fenda sináptica e melhorando a transmissão colinérgica nas áreas corticais e hipocampais envolvidas na memória.',
   'Reversibly inhibits acetylcholinesterase (predominantly central), increasing synaptic acetylcholine concentration and improving cholinergic transmission in the cortical and hippocampal areas involved in memory.',
   'Metabolização hepática extensa: CYP2D6 e CYP3A4 + glucuronidação, com quatro metabolitos principais (dois ativos — inclui o 6-O-desmetil donepezilo); excreção renal dos metabolitos (~57% da radioatividade na urina); o fármaco intacto representa ~53% da radioatividade plasmática.',
   'Extensive hepatic metabolism: CYP2D6 and CYP3A4 plus glucuronidation, with four major metabolites (two active — including 6-O-desmethyl donepezil); renal excretion of metabolites (~57% of radioactivity in urine); intact drug accounts for ~53% of plasma radioactivity.',
   'Boa absorção oral, não afetada pelos alimentos; pico plasmático ~3 h (10 mg) e ~8 h (23 mg); ~96% ligação proteica (albumina ~75%, alfa-1-glicoproteína ~21%); volume de distribuição 12-16 L/kg no estado de equilíbrio.',
   'Good oral absorption, not affected by food; plasma peak ~3 h (10 mg) and ~8 h (23 mg); ~96% protein binding (albumin ~75%, alpha-1-acid glycoprotein ~21%); steady-state volume of distribution 12-16 L/kg.',
   'Semivida de eliminação ~70 h; acumulação plasmática 4-7x com doses múltiplas; estado de equilíbrio em ~15 dias; clearance plasmática aparente 0,13-0,19 L/h/kg.',
   'Elimination half-life ~70 h; 4-7x plasma accumulation with multiple dosing; steady state within ~15 days; apparent plasma clearance 0.13-0.19 L/h/kg.',
   'DailyMed/FDA — Donepezil Hydrochloride Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=12a755c5-1ad9-43d1-832a-eb2ff17bd693',
   'DailyMed/FDA — Donepezil Hydrochloride Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=12a755c5-1ad9-43d1-832a-eb2ff17bd693'),

  ('epoetina_alfa',
   'Eritropoietina humana recombinante (fator de crescimento hematopoiético) que estimula a eritropoiese na medula óssea; usada na anemia da doença renal crónica, na anemia da zidovudina (VIH) e na anemia oncológica induzida por quimioterapia.',
   'Recombinant human erythropoietin (haematopoietic growth factor) that stimulates erythropoiesis in the bone marrow; used in anaemia of chronic kidney disease, zidovudine-associated anaemia (HIV) and chemotherapy-induced anaemia in cancer.',
   'Liga-se aos recetores da eritropoietina nos progenitores eritroides da medula óssea, ativando vias de sinalização (JAK2/STAT5, PI3K/Akt, MAPK) que promovem a sobrevivência, proliferação e diferenciação dos eritroblastos — aumento da produção de glóbulos vermelhos.',
   'Binds erythropoietin receptors on bone marrow erythroid progenitors, activating signalling pathways (JAK2/STAT5, PI3K/Akt, MAPK) that promote erythroblast survival, proliferation and differentiation — increased red blood cell production.',
   'Clearance maioritariamente não renal (metabolismo celular/recaptação pelos recetores); sem acumulação com regimes de 150 U/kg 3x/semana ou 40 000 U/semana; a hemodiálise não remove quantidades clinicamente relevantes.',
   'Largely non-renal clearance (cellular metabolism/receptor uptake); no accumulation with 150 U/kg 3x/week or 40 000 U/week regimens; haemodialysis does not remove clinically relevant amounts.',
   'IV: semivida 4-13 h em doentes com DRC; SC: pico 5-24 h após a administração; em doentes oncológicos anémicos, a semivida média SC é ~40 h (16-67 h); farmacocinética semelhante em adultos e crianças.',
   'IV: half-life 4-13 h in CKD patients; SC: peak 5-24 h after administration; in anaemic cancer patients, mean SC half-life is ~40 h (16-67 h); similar pharmacokinetics in adults and children.',
   'Semivida IV 4-13 h (DRC); SC ~40 h em doentes oncológicos (16-67 h); a semivida é semelhante entre doentes em diálise e não diálise e acima/abaixo dos 65 anos.',
   'IV half-life 4-13 h (CKD); SC ~40 h in cancer patients (16-67 h); the half-life is similar between dialysis and non-dialysis patients and above/below 65 years.',
   'DailyMed/FDA — Epogen (epoetin alfa) Injection, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f2d0b28-9cc5-4523-80b8-637fdaf3f7a5',
   'DailyMed/FDA — Epogen (epoetin alfa) Injection label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f2d0b28-9cc5-4523-80b8-637fdaf3f7a5'),

  ('etambutol',
   'Antimicobacteriano bacteriostático usado na tuberculose (sempre em associação); efeito adverso limitante é a neurite ótica (dose e duração dependentes) — exige vigilância oftalmológica.',
   'Bacteriostatic antimycobacterial used in tuberculosis (always in combination); the dose-limiting adverse effect is optic neuritis (dose and duration dependent) — requires ophthalmological surveillance.',
   'Inibe seletivamente a síntese de arabinogalactana da parede celular micobacteriana (bloqueia a arabinosiltransferase EmbB), comprometendo a integridade da parede; difunde para os macrófagos e para os bacilos em crescimento ativo; sem resistência cruzada com outros antimicobacterianos.',
   'Selectively inhibits arabinogalactan synthesis of the mycobacterial cell wall (blocks arabinosyltransferase EmbB), compromising wall integrity; diffuses into macrophages and actively growing bacilli; no cross-resistance with other antimycobacterials.',
   'Metabolização parcial: oxidação do grupo álcool a intermediário aldeídico e conversão em ácido dicarboxílico; ~50% da dose excretada inalterada na urina em 24 h e 8-15% como metabolitos; 20-22% nas fezes; acumulação na insuficiência renal.',
   'Partial metabolism: oxidation of the alcohol group to an aldehydic intermediate and conversion to a dicarboxylic acid; ~50% of the dose excreted unchanged in urine within 24 h and 8-15% as metabolites; 20-22% in faeces; accumulation in renal impairment.',
   'Bem absorvido por via oral: pico sérico 2-5 mcg/mL, 2-4 h após 25 mg/kg; concentrações intracelulares nos eritrócitos ~2x as plasmáticas; níveis indetetáveis 24 h após a última dose em função renal normal.',
   'Well absorbed orally: serum peak 2-5 mcg/mL, 2-4 h after 25 mg/kg; erythrocyte intracellular concentrations ~2x plasma levels; undetectable levels 24 h after the last dose with normal renal function.',
   'Sem acumulação com doses diárias de 25 mg/kg em função renal normal (semivida ~3-4 h com eliminação renal); acumulação marcada na insuficiência renal.',
   'No accumulation with daily 25 mg/kg doses with normal renal function (half-life ~3-4 h with renal elimination); marked accumulation in renal impairment.',
   'DailyMed/FDA — Ethambutol Hydrochloride Tablets, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c12b3482-55f0-4324-bdcd-b129ca2dae73',
   'DailyMed/FDA — Ethambutol Hydrochloride Tablets label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c12b3482-55f0-4324-bdcd-b129ca2dae73'),

  ('fitomenadiona',
   'Vitamina K1 — cofator essencial para a carboxilação dos fatores de coagulação dependentes da vitamina K (II, VII, IX, X) e proteínas C e S; antídoto específico da hipoprotrombinemia induzida por cumarínicos.',
   'Vitamin K1 — essential cofactor for the gamma-carboxylation of vitamin K-dependent clotting factors (II, VII, IX, X) and proteins C and S; specific antidote for coumarin-induced hypoprothrombinaemia.',
   'A vitamina K atua como cofator da gama-glutamil carboxilase hepática, que converte os precursores inativos dos fatores II, VII, IX, X e proteínas C/S em proteínas funcionais com capacidade de ligação ao cálcio (domínios Gla) — necessária à coagulação.',
   'Vitamin K acts as a cofactor for hepatic gamma-glutamyl carboxylase, converting the inactive precursors of factors II, VII, IX, X and proteins C/S into functional calcium-binding proteins (Gla domains) — required for coagulation.',
   'Quase nenhuma vitamina K livre inalterada aparece na bílis ou na urina; após a absorção concentra-se no fígado, mas a concentração hepática declina rapidamente; muito pouca vitamina K se acumula nos tecidos.',
   'Virtually no free unmetabolised vitamin K appears in bile or urine; after absorption it initially concentrates in the liver, but the hepatic concentration declines rapidly; very little vitamin K accumulates in tissues.',
   'Bem absorvida por via intramuscular (e por via oral na forma de fitomenadiona); após a administração, os fatores de coagulação (sobretudo o FVII, de semivida curta) começam a normalizar em poucas horas, com efeito máximo ~12-24 h.',
   'Well absorbed intramuscularly (and orally as phytonadione); after administration, clotting factors (especially FVII, short half-life) begin to normalise within hours, with maximal effect ~12-24 h.',
   'Ação rápida mas de duração limitada (as reservas hepáticas esgotam-se em dias); a correção completa e sustentada da coagulação depende da síntese hepática e da reposição continuada na causa subjacente.',
   'Rapid but limited duration of action (hepatic reserves deplete within days); complete and sustained correction of coagulation depends on hepatic synthesis and continued replacement of the underlying cause.',
   'DailyMed/FDA — Vitamin K1 Injection (Phytonadione Injectable Emulsion), secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e8808230-2c44-44c6-8cab-8f29b6b34051',
   'DailyMed/FDA — Vitamin K1 Injection (Phytonadione Injectable Emulsion) label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e8808230-2c44-44c6-8cab-8f29b6b34051'),

  ('formoterol',
   'Beta-2 agonista de ação prolongada (LABA) com início de ação rápido (minutos), indicado na manutenção da broncoconstrição na DPOC (2x/dia); não indicado na asma em monoterapia (risco de eventos relacionados com a asma).',
   'Long-acting beta-2 agonist (LABA) with rapid onset (minutes), indicated for maintenance of bronchoconstriction in COPD (twice daily); not indicated for asthma as monotherapy (risk of asthma-related events).',
   'Agonista seletivo dos recetores beta-2 adrenérgicos do músculo liso brônquico: ativa a adenilato ciclase, aumenta o AMPc e ativa a proteína quinase A, causando relaxamento do músculo liso (broncodilatação) e estabilização mastocitária; efeito prolongado (>12 h) por ligação persistente ao recetor.',
   'Selective agonist of beta-2 adrenergic receptors on bronchial smooth muscle: activates adenylyl cyclase, raises cAMP and activates protein kinase A, causing smooth muscle relaxation (bronchodilation) and mast cell stabilisation; prolonged effect (>12 h) due to persistent receptor binding.',
   'Metabolização hepática extensa (glucuronidação e O-desmetilação; CYP2D6/CYP2C/2A6 envolvidos na desmetilação); excreção renal dos metabolitos e de fármaco inalterado (a excreção urinária inalterada é usada como medida indireta da exposição sistémica).',
   'Extensive hepatic metabolism (glucuronidation and O-demethylation; CYP2D6/CYP2C/2A6 involved in demethylation); renal excretion of metabolites and unchanged drug (urinary excretion of unchanged drug is used as an indirect measure of systemic exposure).',
   'Exposição sistémica baixa por via inalatória: após 244 mcg nebulizados (≈12x a dose clínica), Cmax de 72 pg/mL em ~12 min; com doses terapêuticas (10-20 mcg) as concentrações plasmáticas são indetetáveis ou esporádicas; acumulação ligeira com doses repetidas (índice 1,19-1,38).',
   'Low systemic exposure via inhalation: after 244 mcg nebulised (≈12x the clinical dose), Cmax of 72 pg/mL within ~12 min; at therapeutic doses (10-20 mcg) plasma concentrations are undetectable or sporadic; slight accumulation with repeated dosing (index 1.19-1.38).',
   'Semivida de eliminação ~10 h (calculada a partir da excreção urinária e plasmática); a broncodilatação dura ≥12 h, permitindo administração 2x/dia.',
   'Elimination half-life ~10 h (calculated from urinary and plasma excretion); bronchodilation lasts ≥12 h, allowing twice-daily administration.',
   'DailyMed/FDA — Formoterol Fumarate Inhalation Solution, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=35538d89-a984-4335-acdf-85a893f51eee',
   'DailyMed/FDA — Formoterol Fumarate Inhalation Solution label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=35538d89-a984-4335-acdf-85a893f51eee'),

  ('fosfomicina',
   'Antibiótico de largo espetro (derivado do ácido fosfónico) bactericida, usado em dose única oral de 3 g na cistite aguda não complicada em mulheres; bem tolerado, com diarreia como efeito mais frequente.',
   'Broad-spectrum antibiotic (phosphonic acid derivative), bactericidal, used as a single 3 g oral dose for acute uncomplicated cystitis in women; well tolerated, with diarrhoea as the most frequent effect.',
   'Inibe a enolpiruviltransferase (MurA), bloqueando a síntese do peptidoglicano (primeiro passo da biossíntese da parede celular) — bactericida de amplo espetro contra Gram-positivos e Gram-negativos, incluindo E. coli e E. faecalis.',
   'Inhibits enolpyruvyltransferase (MurA), blocking peptidoglycan synthesis (first step of cell wall biosynthesis) — broad-spectrum bactericidal against Gram-positives and Gram-negatives, including E. coli and E. faecalis.',
   'Metabolização mínima; excreção inalterada na urina (~38% da dose oral) e nas fezes (~18%); clearance total 16,9 L/h e renal 6,3 L/h; não se liga a proteínas plasmáticas.',
   'Minimal metabolism; excretion unchanged in urine (~38% of the oral dose) and faeces (~18%); total clearance 16.9 L/h and renal 6.3 L/h; no plasma protein binding.',
   'Absorção rápida: biodisponibilidade oral absoluta 37% em jejum (30% com alimentos); Cmax 26,1±9,1 mcg/mL ~2 h após 3 g (17,6 mcg/mL às 4 h com refeição rica em gordura); volume de distribuição 136,1 L; distribui-se para o rim, parede vesical, próstata e vesículas seminais.',
   'Rapid absorption: absolute oral bioavailability 37% fasting (30% with food); Cmax 26.1±9.1 mcg/mL ~2 h after 3 g (17.6 mcg/mL at 4 h with a high-fat meal); volume of distribution 136.1 L; distributes to the kidney, bladder wall, prostate and seminal vesicles.',
   'Semivida de eliminação ~5,7 h após dose oral de 3 g (a semivida prolonga-se na insuficiência renal); concentração urinária média de 706 mcg/mL 2-4 h após a toma.',
   'Elimination half-life ~5.7 h after a 3 g oral dose (half-life prolonged in renal impairment); mean urinary concentration of 706 mcg/mL 2-4 h after dosing.',
   'DailyMed/FDA — Fosfomycin Tromethamine Granules for Oral Solution, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4f206750-8126-99a3-e063-6294a90ade4c',
   'DailyMed/FDA — Fosfomycin Tromethamine Granules for Oral Solution label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4f206750-8126-99a3-e063-6294a90ade4c'),

  ('hidromorfona',
   'Agonista opióide mu potente (5-7x mais potente que a morfina por via oral) para dor grave que requer opióide; biodisponibilidade oral ~24% e semivida curta; metabolismo por glucuronidação com excreção renal dos metabolitos.',
   'Potent mu opioid agonist (5-7x more potent than oral morphine) for severe pain requiring an opioid; oral bioavailability ~24% and short half-life; glucuronidation metabolism with renal excretion of metabolites.',
   'Agonista seletivo dos recetores opióides mu (μ), ativando as vias inibitórias descendentes da dor e inibindo a libertação de neurotransmissores nociceptivos — analgesia, sedação, euforia e depressão respiratória dose-dependente.',
   'Selective agonist of mu (μ) opioid receptors, activating descending pain-inhibitory pathways and inhibiting nociceptive neurotransmitter release — analgesia, sedation, euphoria and dose-dependent respiratory depression.',
   'Metabolização extensa por glucuronidação hepática (>95% em hidromorfona-3-glucuronídeo, com pequenas quantidades de metabolitos 6-hidroxi); apenas pequenas quantidades excretadas inalteradas na urina; acumulação na insuficiência hepática (exposição 4x em Child-Pugh B).',
   'Extensive hepatic glucuronidation (>95% to hydromorphone-3-glucuronide, with minor 6-hydroxy metabolites); only small amounts excreted unchanged in urine; accumulation in hepatic impairment (4x exposure in Child-Pugh B).',
   'Absorção rápida do trato GI com extenso metabolismo de primeira passagem: biodisponibilidade oral ~24%; pico plasmático 0,5-1 h; os alimentos reduzem a Cmax 25% e prolongam o Tmax 0,8 h (AUC +35%); ligação proteica 8-19%.',
   'Rapid GI absorption with extensive first-pass metabolism: oral bioavailability ~24%; plasma peak 0.5-1 h; food lowers Cmax 25% and prolongs Tmax 0.8 h (AUC +35%); protein binding 8-19%.',
   'Semivida terminal ~2,3 h (IV); duração do efeito 4-5 h; clearance sistémico ~1,96 L/min; volume de distribuição ~303 L; a semivida prolonga-se na insuficiência renal e hepática.',
   'Terminal half-life ~2.3 h (IV); duration of effect 4-5 h; systemic clearance ~1.96 L/min; volume of distribution ~303 L; the half-life is prolonged in renal and hepatic impairment.',
   'DailyMed/FDA — Hydromorphone Hydrochloride Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c1cc8-c42b-46e3-ad68-8e22f57101f2',
   'DailyMed/FDA — Hydromorphone Hydrochloride Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4c5c1cc8-c42b-46e3-ad68-8e22f57101f2'),

  ('indapamida',
   'Diurético do tipo tiazida-like (indolina) com efeito anti-hipertensor e diurético; reduz a reabsorção de sódio no túbulo distal com efeito vasodilatador direto; hipocaliemia dose-dependente é o efeito a vigiar.',
   'Thiazide-like (indoline) diuretic with antihypertensive and diuretic effects; reduces sodium reabsorption in the distal tubule with a direct vasodilatory effect; dose-dependent hypokalaemia is the effect to watch.',
   'Inibe o cotransportador Na+/Cl- no túbulo contorcido distal, aumentando a excreção de sódio, cloro e água (diurese); tem ainda efeito vasodilatador direto (redução da resistência vascular periférica) que contribui para o efeito anti-hipertensor em doses baixas.',
   'Inhibits the Na+/Cl- cotransporter in the distal convoluted tubule, increasing sodium, chloride and water excretion (diuresis); also has a direct vasodilatory effect (reduced peripheral vascular resistance) contributing to the antihypertensive effect at low doses.',
   'Extensamente metabolizado (apenas ~7% excretado inalterado na urina em 48 h); eliminação renal de ~70% da dose e 23% pelo trato gastrointestinal (incluindo via biliar); excreção urinária bifásica com semivida terminal da radioatividade total de 26 h.',
   'Extensively metabolised (only ~7% excreted unchanged in urine within 48 h); renal elimination of ~70% of the dose and 23% via the GI tract (including biliary); biphasic urinary excretion with a terminal half-life of total radioactivity of 26 h.',
   'Bem absorvido por via oral: pico 115 ng/mL (2,5 mg) e 260 ng/mL (5 mg) ~2 h após a toma; captação preferencial reversível pelos eritrócitos (rácio sangue/plasma ~6:1 no pico); ligação proteica 71-79%.',
   'Well absorbed orally: peak 115 ng/mL (2.5 mg) and 260 ng/mL (5 mg) ~2 h after dosing; preferential reversible uptake by erythrocytes (blood/plasma ratio ~6:1 at peak); protein binding 71-79%.',
   'Semivida no sangue total ~14 h; o efeito anti-hipertensor mantém-se com dose única diária (1,25-2,5 mg).',
   'Whole blood half-life ~14 h; the antihypertensive effect is maintained with once-daily dosing (1.25-2.5 mg).',
   'DailyMed/FDA — Indapamide Tablets, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=59cd3331-7afe-432a-8b50-39533fd5f392',
   'DailyMed/FDA — Indapamide Tablets label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=59cd3331-7afe-432a-8b50-39533fd5f392'),

  ('lamivudina',
   'Análogo nucleósido inibidor da transcriptase reversa (NRTI) ativo contra o VHB (e VIH); biodisponibilidade oral ~86-87%; excreção renal — ajustar na insuficiência renal. Limitação: resistência (mutação YMDD) com uso prolongado.',
   'Nucleoside analogue reverse transcriptase inhibitor (NRTI) active against HBV (and HIV); oral bioavailability ~86-87%; renal excretion — adjust in renal impairment. Limitation: resistance (YMDD mutation) with prolonged use.',
   'Fosforilado intracelularmente em lamivudina-trifosfato, que inibe a transcriptase reversa viral por competição com a desoxicitidina-trifosfato e terminação da cadeia de ADN — bloqueia a replicação do VHB e do VIH.',
   'Intracellularly phosphorylated to lamivudine-triphosphate, which inhibits viral reverse transcriptase by competing with deoxycytidine-triphosphate and chain termination of DNA — blocks HBV and HIV replication.',
   'Metabolização intracelular (fosforilação); excreção predominantemente renal inalterada (filtração glomerular e secreção tubular ativa) — ajustar o intervalo de doses na insuficiência renal; pequena metabolização oxidativa hepática.',
   'Intracellular metabolism (phosphorylation); predominantly renal excretion unchanged (glomerular filtration and active tubular secretion) — extend the dosing interval in renal impairment; minor hepatic oxidative metabolism.',
   'Bem absorvido por via oral: biodisponibilidade absoluta 86±16% (comprimido 150 mg) e 87±13% (solução); pico sérico 1,28±0,56 mcg/mL (VHB) 0,5-2 h após 100 mg; alimentos não alteram a absorção; volume de distribuição 1,3±0,4 L/kg (distribuição extravascular).',
   'Well absorbed orally: absolute bioavailability 86±16% (150 mg tablet) and 87±13% (solution); serum peak 1.28±0.56 mcg/mL (HBV) 0.5-2 h after 100 mg; food does not alter absorption; volume of distribution 1.3±0.4 L/kg (extravascular distribution).',
   'Semivida plasmática ~5-7 h; a semivida intracelular da lamivudina-trifosfato é de 13-19 h (justifica a dose única diária na hepatite B); sem acumulação relevante com doses repetidas.',
   'Plasma half-life ~5-7 h; the intracellular half-life of lamivudine-triphosphate is 13-19 h (supports once-daily dosing in hepatitis B); no relevant accumulation with repeated dosing.',
   'DailyMed/FDA — Lamivudine Tablets (HBV), secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6bd6b9da-df69-46db-813e-4e7f3bdecf95',
   'DailyMed/FDA — Lamivudine Tablets (HBV) label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6bd6b9da-df69-46db-813e-4e7f3bdecf95'),

  ('levocetirizina',
   'Enantiómero (R) ativo da cetirizina, anti-H1 de 2.ª geração com afinidade dupla para o recetor H1 e mínima sedação; excreção renal predominante (~85,8% inalterado) — ajustar na insuficiência renal.',
   'Active (R) enantiomer of cetirizine, a second-generation H1 antihistamine with twice the H1 receptor affinity and minimal sedation; predominantly renal excretion (~85.8% unchanged) — adjust in renal impairment.',
   'Antagonista seletivo e periférico dos recetores H1 da histamina (o enantiómero R é o responsável pela atividade da cetirizina racémica), bloqueando a resposta alérgica sem efeitos anticolinérgicos ou serotoninérgicos relevantes.',
   'Selective peripheral antagonist of histamine H1 receptors (the R enantiomer is responsible for the activity of racemic cetirizine), blocking the allergic response without relevant anticholinergic or serotonergic effects.',
   'Metabolismo hepático mínimo (~14% — N-oxidação e O-desalquilação, com metabolito inativo); excreção renal predominante: 85,8% da dose oral excretada inalterada em 48 h (equivalente a ~95% da dose total eliminada); sem interações CYP relevantes.',
   'Minimal hepatic metabolism (~14% — N-oxidation and O-dealkylation, with an inactive metabolite); predominantly renal excretion: 85.8% of the oral dose excreted unchanged within 48 h (equivalent to ~95% of the total dose eliminated); no relevant CYP interactions.',
   'Boa absorção oral com biodisponibilidade elevada (sem efeito de primeira passagem significativo); pico plasmático ~0,9 h; os alimentos reduzem ligeiramente a Cmax (sem alteração do AUC); ligação proteica ~92%.',
   'Good oral absorption with high bioavailability (no significant first-pass effect); plasma peak ~0.9 h; food slightly reduces Cmax (without changing AUC); protein binding ~92%.',
   'Semivida ~7-8 h (7,3-7,6 h em adultos); prolonga-se na insuficiência renal e nos idosos (CrCl <50 mL/min: dose reduzida ou em dias alternados).',
   'Half-life ~7-8 h (7.3-7.6 h in adults); prolonged in renal impairment and the elderly (CrCl <50 mL/min: reduced or alternate-day dosing).',
   'DailyMed/FDA — Levocetirizine OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f722b84-08de-7e6a-41ac-2c9d9bb9fb43 + PubMed PMID 11758635 (ADME [14C]levocetirizina)',
   'DailyMed/FDA — Levocetirizine OTC label (Drug Facts): https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f722b84-08de-7e6a-41ac-2c9d9bb9fb43 + PubMed PMID 11758635 ([14C]levocetirizine ADME)'),

  ('loperamida',
   'Agonista opióide periférico antidiarreico (não atravessa a barreira hematoencefálica em condições normais — substrato da glicoproteína P); reduz o peristaltismo e a perda de fluidos; sem efeito analgésico central.',
   'Peripheral opioid antidiarrhoeal agonist (does not cross the blood-brain barrier under normal conditions — P-glycoprotein substrate); reduces peristalsis and fluid loss; no central analgesic effect.',
   'Liga-se aos recetores opióides da parede intestinal, inibindo a libertação de acetilcolina e prostaglandinas: reduz o peristaltismo propulsivo, aumenta o tempo de trânsito, o tónus do esfíncter anal e a reabsorção de água/eletrólitos.',
   'Binds opioid receptors in the gut wall, inhibiting acetylcholine and prostaglandin release: reduces propulsive peristalsis, increases transit time, anal sphincter tone and water/electrolyte reabsorption.',
   'Metabolização hepática extensa por N-desmetilação oxidativa (CYP2C8 e CYP3A4, com papéis menores de CYP2B6/CYP2D6); excreção fecal predominante do fármaco e metabolitos, com pequena excreção urinária.',
   'Extensive hepatic metabolism by oxidative N-demethylation (CYP2C8 and CYP3A4, with minor roles of CYP2B6/CYP2D6); predominantly faecal excretion of the drug and metabolites, with minor urinary excretion.',
   'Baixa absorção sistémica: concentrações plasmáticas <2 ng/mL após 2 mg oral; pico plasmático ~5 h (cápsula); ~95% ligação proteica; substrato da glicoproteína P (efluxo intestinal limita a entrada no SNC).',
   'Low systemic absorption: plasma concentrations <2 ng/mL after 2 mg orally; plasma peak ~5 h (capsule); ~95% protein binding; P-glycoprotein substrate (intestinal efflux limits CNS entry).',
   'Semivida de eliminação aparente ~10,8 h (9,1-14,4 h); a duração do efeito antidiarreico é de ~12-24 h com a dose habitual.',
   'Apparent elimination half-life ~10.8 h (9.1-14.4 h); the antidiarrhoeal effect lasts ~12-24 h with the usual dose.',
   'DailyMed/FDA — Loperamide Hydrochloride Capsules, secção CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3fdfc0e5-56a2-48a0-8ee6-390a194a29f3',
   'DailyMed/FDA — Loperamide Hydrochloride Capsules label, section CLINICAL PHARMACOLOGY: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3fdfc0e5-56a2-48a0-8ee6-390a194a29f3'),

  ('losartano',
   'Antagonista dos recetores AT1 da angiotensina II (ARA II), ativo sobretudo através do metabolito E-3174; usado na hipertensão, nefropatia diabética e redução do risco de AVC na hipertrofia ventricular esquerda.',
   'Angiotensin II AT1 receptor antagonist (ARB), active mainly through the metabolite E-3174; used in hypertension, diabetic nephropathy and stroke risk reduction in left ventricular hypertrophy.',
   'Bloqueia seletiva e competitivamente os recetores AT1 da angiotensina II (vasoconstrição, retenção de sódio, proliferação celular, aldosterona), sem interferir com os recetores AT2; o metabolito ativo E-3174 (ácido carboxílico) é responsável pela maior parte do antagonismo.',
   'Selectively and competitively blocks angiotensin II AT1 receptors (vasoconstriction, sodium retention, cell proliferation, aldosterone), without affecting AT2 receptors; the active metabolite E-3174 (carboxylic acid) is responsible for most of the antagonism.',
   'Metabolismo de primeira passagem por CYP2C9 e CYP3A4: ~14% da dose convertida no metabolito ativo E-3174, além de metabolitos inativos; excreção renal (~35%) e biliar/fecal (~60%) do fármaco e metabolitos.',
   'First-pass metabolism by CYP2C9 and CYP3A4: ~14% of the dose converted to the active metabolite E-3174, plus inactive metabolites; renal (~35%) and biliary/faecal (~60%) excretion of the drug and metabolites.',
   'Bem absorvido com metabolismo de primeira passagem substancial: biodisponibilidade sistémica ~33%; pico 1 h (losartano) e 3-4 h (metabolito); os alimentos retardam a absorção e reduzem a Cmax (AUC quase inalterado); ligação proteica elevada (frações livres 1,3% e 0,2%).',
   'Well absorbed with substantial first-pass metabolism: systemic bioavailability ~33%; peak 1 h (losartan) and 3-4 h (metabolite); food slows absorption and reduces Cmax (AUC barely changed); high protein binding (free fractions 1.3% and 0.2%).',
   'Semivida terminal ~2 h (losartano) e 6-9 h (metabolito ativo E-3174); clearance plasmática total 600 mL/min (metabolito 50 mL/min).',
   'Terminal half-life ~2 h (losartan) and 6-9 h (active metabolite E-3174); total plasma clearance 600 mL/min (metabolite 50 mL/min).',
   'DailyMed/FDA — Losartan Potassium Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c15387df-87a4-4784-acb5-7dd550498f8f',
   'DailyMed/FDA — Losartan Potassium Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c15387df-87a4-4784-acb5-7dd550498f8f'),

  ('mesalazina',
   'Anti-inflamatório intestinal (5-ASA) de ação local no cólon (formulação de libertação diferida sensível ao pH); absorção sistémica ~21-22% com a maior parte do fármaco a permanecer no lúmen colónico.',
   'Intestinal anti-inflammatory (5-ASA) with local action in the colon (pH-sensitive delayed-release formulation); systemic absorption ~21-22% with most of the drug remaining in the colonic lumen.',
   'Inibe localmente a via da COX e da lipoxigenase e a síntese de prostaglandinas e leucotrienos, reduz a quimiotaxia/degranulação dos neutrófilos e a produção de citocinas pró-inflamatórias na mucosa colónica — efeito anti-inflamatório tópico.',
   'Locally inhibits the COX and lipoxygenase pathways and prostaglandin/leukotriene synthesis, reduces neutrophil chemotaxis/degranulation and pro-inflammatory cytokine production in the colonic mucosa — topical anti-inflammatory effect.',
   'A fração absorvida é N-acetilada (no epitélio intestinal e no fígado) em N-acetil-5-ASA (inativo); excreção renal da mesalazina e do metabolito; a maior parte da dose é eliminada nas fezes.',
   'The absorbed fraction is N-acetylated (in the intestinal epithelium and liver) to N-acetyl-5-ASA (inactive); renal excretion of mesalamine and the metabolite; most of the dose is eliminated in faeces.',
   'Libertação diferida no cólon: o comprimido passa intacto pelo trato gastrointestinal superior; concentrações plasmáticas detetáveis após ~2 h com pico em 9-12 h; absorção sistémica total ~21-22% (2,4-4,8 g/dia); parâmetros altamente variáveis entre doentes.',
   'Delayed release in the colon: the tablet passes intact through the upper GI tract; plasma concentrations detectable after ~2 h with a peak at 9-12 h; total systemic absorption ~21-22% (2.4-4.8 g/day); highly variable parameters between patients.',
   'Semivida terminal aparente da mesalazina e do metabolito ~7-9 h na formulação de libertação diferida (rótulo DailyMed não especifica t½ — valor do rótulo Lialda/FDA).',
   'Apparent terminal half-life of mesalamine and its metabolite ~7-9 h with the delayed-release formulation (DailyMed label does not state a t½ — Lialda/FDA label value).',
   'DailyMed/FDA — Mesalamine Delayed-Release Tablets, secção 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=14ac4435-903b-41f5-a3c4-8c73de3e4cef',
   'DailyMed/FDA — Mesalamine Delayed-Release Tablets label, section 12.3 Pharmacokinetics: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=14ac4435-903b-41f5-a3c4-8c73de3e4cef')
) AS v(slug, pharmacodynamics_pt, pharmacodynamics_en, mechanism_pt, mechanism_en,
        metabolism_pt, metabolism_en, absorption_pt, absorption_en,
        half_life_pt, half_life_en, source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;

